  JOIN za p_inventory_entitie  to_entity ON (to_entity.organization_id,to_entity.work pace_id,to_entity.environment_id,to_entity.id,to_entity. tate)=(relation hip.organization_id,relation hip.work pace_id,relation hip.environment_id,relation hip.to_entity_id,'active')
