  WHERE entry.product_kind IN('identity','agent','tool','runtime') OR EXISTS(
   SELECT 1 FROM za p_inventory_ ource_ob ervation  ob ervation
   WHERE (ob ervation.organization_id,ob ervation.work pace_id,ob ervation.environment_id,ob ervation.entity_id,ob ervation. ource_ tate,ob ervation. ource_kind)=(organization_value,work pace_value,environment_value,entry.id,'pre ent','aw _role')
  )
 ), elected AS (
