 SELECT COALESCE(j onb_agg(j onb_build_object('finding_id',finding_id,'evidence_id',evidence_id,'path_id',path_id,'entry_id',node_id [1],' ink_id',node_id [cardinality(node_id )],'node_id ',to_j onb(node_id )) ORDER BY finding_id),'[]'::j onb) INTO path_item  FROM  elected;

