DECLARE input_value record;updated_count integer;annotation_item  j onb; tate_value j onb;
BEGIN
 PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),'za p-inventory-cutover',organization_value,work pace_value,environment_value),0));
  tate_value:=za p_inventory_ cope_ tate(organization_value,work pace_value,environment_value);
 IF  tate_value IS NULL THEN PERFORM za p_inventory_advance_ cope(organization_value,work pace_value,environment_value,'expanded',NULL,NULL);ELSIF  tate_value->>'pha e'<>'expanded' THEN IF  tate_value->>'pha e'='backfilled' THEN RETURN  tate_value;END IF;RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='inventory backfill pha e conflict';END IF;
 FOR input_value IN
  SELECT input.integration_id,input. ource,input.generation,input. nap hot_id,input.candidate_dige t,input.entitie ,input.evidence, nap hot.collected_at
  FROM za p_di covery_ nap hot_input  input JOIN za p_di covery_ nap hot   nap hot ON ( nap hot.organization_id, nap hot.work pace_id, nap hot.environment_id, nap hot.id, nap hot.integration_id, nap hot. ource, nap hot.generation, nap hot. tate, nap hot.i _la t_good)=(input.organization_id,input.work pace_id,input.environment_id,input. nap hot_id,input.integration_id,input. ource,input.generation,'complete',true)
  WHERE (input.organization_id,input.work pace_id,input.environment_id)=(organization_value,work pace_value,environment_value) ORDER BY input.integration_id,input. ource
 LOOP
  IF j onb_typeof(input_value.entitie )<>'array' OR j onb_typeof(input_value.evidence)<>'array' OR j onb_array_length(input_value.entitie )<>j onb_array_length(input_value.evidence) OR NOT za p_inventory_validate_typed_entitie (input_value. ource,input_value.entitie )
   OR EXISTS(SELECT 1 FROM j onb_to_record et(input_value.entitie ) entity_value(id text,evidence_id text) LEFT JOIN j onb_to_record et(input_value.evidence) evidence_value(id text,entity_id text) ON (evidence_value.id,evidence_value.entity_id)=(entity_value.evidence_id,entity_value.id) WHERE evidence_value.id IS NULL)
  THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy inventory lack  typed  nap hot';END IF;
  UPDATE za p_inventory_evidence  tored SET  ource=input_value. ource,generation=input_value.generation,artifact_reference=typed.artifact_reference,artifact_key=typed.artifact_key,artifact_ver ion_id=typed.artifact_ver ion_id, ize_byte =typed. ize_byte ,tool_ver ion=typed.tool_ver ion
  FROM j onb_to_record et(input_value.evidence) typed(id text,artifact_reference text,artifact_key text,artifact_ver ion_id text, ize_byte  bigint,tool_ver ion text)
  WHERE ( tored.organization_id, tored.work pace_id, tored.environment_id, tored.integration_id, tored. nap hot_id, tored.id)=(organization_value,work pace_value,environment_value,input_value.integration_id,input_value. nap hot_id,typed.id);
  GET DIAGNOSTICS updated_count=ROW_COUNT;IF updated_count<>j onb_array_length(input_value.evidence) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy evidence authority incomplete';END IF;
  UPDATE za p_inventory_ ource_ob ervation   tored SET provider=input_value. ource, ource_kind=typed.kind,di play_name=typed.di play_name, table_field =typed. table_field ,attribute =typed.attribute ,identity_name pace=typed.identity_name pace,product_kind=typed.product_kind,generation=input_value.generation,content_dige t=input_value.candidate_dige t,evidence_id=typed.evidence_id,confidence_ba i _point =typed.confidence_ba i _point ,ob erved_at=typed.ob erved_at,fre h_until=typed.fre h_until,identity_rule_ver ion=typed.identity_rule_ver ion,identity_priority=typed.identity_priority, ource_projection_ver ion=typed. ource_projection_ver ion,la t_ een_at=typed.ob erved_at
  FROM j onb_to_record et(input_value.entitie ) typed(id text,kind text,di play_name text, table_field  j onb,attribute  j onb,identity_name pace text,product_kind text,evidence_id text,confidence_ba i _point  integer,ob erved_at time tamptz,fre h_until time tamptz,identity_rule_ver ion integer,identity_priority integer, ource_projection_ver ion integer)
  WHERE ( tored.organization_id, tored.work pace_id, tored.environment_id, tored.integration_id, tored. ource, tored. nap hot_id, tored.entity_id, tored. ource_ tate)=(organization_value,work pace_value,environment_value,input_value.integration_id,input_value. ource,input_value. nap hot_id,typed.id,'pre ent');
  GET DIAGNOSTICS updated_count=ROW_COUNT;IF updated_count<>j onb_array_length(input_value.entitie ) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy ob ervation authority incomplete';END IF;
  IF NOT za p_inventory_bind_typed_entitie (organization_value,work pace_value,environment_value,input_value. ource,input_value. ource,input_value.entitie ) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='legacy identity binding conflict';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM za p_inventory_ ource_ob ervation  ob ervation WHERE (ob ervation.organization_id,ob ervation.work pace_id,ob ervation.environment_id,ob ervation. ource_ tate)=(organization_value,work pace_value,environment_value,'pre ent') AND (ob ervation.provider IS NULL OR ob ervation.product_kind IS NULL OR ob ervation.content_dige t IS NULL OR ob ervation.evidence_id IS NULL OR ob ervation.ob erved_at IS NULL OR ob ervation.fre h_until IS NULL)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy inventory lack  typed  nap hot';END IF;
 WITH pre ent AS (SELECT ob ervation.*,row_number() OVER(PARTITION BY ob ervation.entity_id ORDER BY ob ervation.identity_priority,ob ervation.integration_id,ob ervation.provider,ob ervation. ource,ob ervation.identity_name pace,ob ervation. ource_native_id) rank_value,min(ob ervation.fir t_ een_at) OVER(PARTITION BY ob ervation.entity_id) minimum_ een,max(ob ervation.la t_ een_at) OVER(PARTITION BY ob ervation.entity_id) maximum_ een FROM za p_inventory_ ource_ob ervation  ob ervation WHERE (ob ervation.organization_id,ob ervation.work pace_id,ob ervation.environment_id,ob ervation. ource_ tate)=(organization_value,work pace_value,environment_value,'pre ent')),winner AS (SELECT * FROM pre ent WHERE rank_value=1)
 UPDATE za p_inventory_entitie  entity_value SET kind=winner.product_kind,di play_name=winner.di play_name, table_field =winner. table_field , tate='active',fir t_ een_at=winner.minimum_ een,la t_ een_at=winner.maximum_ een,tomb toned_at=NULL,product_kind=winner.product_kind,confidence_ba i _point =winner.confidence_ba i _point ,winning_evidence_id=winner.evidence_id,winning_ nap hot_id=winner. nap hot_id,winning_generation=winner.generation,ob erved_at=winner.ob erved_at,fre h_until=winner.fre h_until,projection_ver ion=winner. ource_projection_ver ion,winning_integration_id=winner.integration_id,winning_provider=winner.provider,winning_ ource=winner. ource,winning_ ource_native_id=winner. ource_native_id,winning_attribute =winner.attribute ,winning_identity_rule=winner.identity_rule_ver ion,winning_ ource_projection=winner. ource_projection_ver ion FROM winner WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id)=(organization_value,work pace_value,environment_value,winner.entity_id);
 IF EXISTS(SELECT 1 FROM unne t(ARRAY['agent ','tool ','identitie ','runtime ']) operation_value CROSS JOIN LATERAL (SELECT za p_core_read(operation_value,organization_value,work pace_value,environment_value) payload) legacy WHERE legacy.payload IS NOT NULL AND j onb_typeof(legacy.payload->'item ')<>'array') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy annotation payload malformed';END IF;
 SELECT COALESCE(j onb_agg(j onb_build_object('id',candidate.id,'owner',candidate.owner_value,'team',candidate.team_value,'tag ',candidate.tag ) ORDER BY candidate.id),'[]'::j onb) INTO annotation_item  FROM (
  SELECT item.id,min(item.owner) owner_value,min(item.team) team_value,(array_agg(item.tag  ORDER BY item.tag ::text))[1] tag  FROM unne t(ARRAY['agent ','tool ','identitie ','runtime ']) operation_value CROSS JOIN LATERAL (SELECT za p_core_read(operation_value,organization_value,work pace_value,environment_value) payload) legacy CROSS JOIN LATERAL j onb_to_record et(COALESCE(legacy.payload->'item ','[]'::j onb)) item(id text,owner text,team text,tag  j onb)
  WHERE EXISTS(SELECT 1 FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id)=(organization_value,work pace_value,environment_value,item.id))
  GROUP BY item.id HAVING count(DISTINCT j onb_build_object('owner',item.owner,'team',item.team,'tag ',item.tag ))=1
 ) candidate;
 IF NOT za p_inventory_import_annotation (organization_value,work pace_value,environment_value,annotation_item ) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='legacy annotation conflict';END IF;
 RETURN za p_inventory_advance_ cope(organization_value,work pace_value,environment_value,'backfilled',NULL,NULL);
