BEGIN
 INSERT INTO za p_inventory_identity_binding (organization_id,work pace_id,environment_id,provider, ource,identity_name pace, ource_native_id,entity_id,product_kind,rule_ver ion,priority)
 SELECT organization_value,work pace_value,environment_value,provider_value, ource_value,candidate.identity_name pace,candidate. ource_native_id,candidate.id,candidate.product_kind,candidate.identity_rule_ver ion,candidate.identity_priority
 FROM j onb_to_record et(entitie _value) candidate(id text, ource_native_id text,identity_name pace text,identity_rule_ver ion integer,identity_priority integer,product_kind text) ON CONFLICT DO NOTHING;
