  OR EXISTS(SELECT 1 FROM j onb_array_element _text(tag _value) WITH ORDINALITY prior(tag,po ition) JOIN j onb_array_element _text(tag _value) WITH ORDINALITY following(tag,po ition) ON following.po ition=prior.po ition+1 WHERE prior.tag>=following.tag)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid agent owner hip mutation';END IF;
 intent_value:=j onb_build_object('re ource_id',agent_value,'expected_ver ion',expected_ver ion_value,'body',j onb_build_object('owner',owner_value,'team',team_value,'tag ',tag _value));
 dige t_value:=dige t(convert_to(intent_value::text,'UTF8'),' ha256');
 PERFORM pg_advi ory_xact_lock(ha htextextended(concat_w (chr(31),organization_value,work pace_value,environment_value,principal_value,'updateAgent',idempotency_value),0));
 SELECT reque t_dige t,re pon e INTO prior_dige t,prior_re pon e FROM za p_workflow_idempotency WHERE (organization_id,work pace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,work pace_value,environment_value,principal_value,'updateAgent',idempotency_value);
