 IF za p_inventory_ cope_ tate(organization_value,work pace_value,environment_value)->>'pha e'<>'cutover' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='typed inventory cutover required';END IF;
 SELECT * INTO entity_record FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id,entity_value. tate,entity_value.product_kind)=(organization_value,work pace_value,environment_value,agent_value,'active','agent') FOR UPDATE;
