 re ult_value:=j onb_build_object('agent',za p_inventory_detail(organization_value,work pace_value,environment_value,agent_value,'agent')->' ummary','audit_id',audit_value,'correlation_id',correlation_value,'replayed',fal e);
 INSERT INTO za p_workflow_audit(organization_id,work pace_id,environment_id,audit_id,correlation_id,principal_id,operation,re ource_kind,re ource_id,re ource_ver ion) VALUES(organization_value,work pace_value,environment_value,audit_value,correlation_value,principal_value,'updateAgent','agent',agent_value,expected_ver ion_value+1);
