CREATE OR REPLACE FUNCTION public.zasp_security_agent_claim_approval_notification(owner_value text, lease_token_value text, lease_seconds_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE notification zasp_security_agent_approval_notifications%ROWTYPE;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR owner_value IS NULL OR char_length(owner_value) NOT BETWEEN 3 AND 128 OR owner_value<>btrim(owner_value) OR owner_value~E'[\\x00\\r\\n]' OR lease_token_value!~'^[0-9a-f]{64}$' OR lease_seconds_value NOT BETWEEN 15 AND 60 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification claim rejected';END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE state='leased' AND lease_expires_at<=transaction_timestamp() AND attempt>=10;
 SELECT * INTO notification FROM zasp_security_agent_approval_notifications row_value
  WHERE (row_value.state IN('pending','retryable') AND row_value.available_at<=transaction_timestamp()) OR (row_value.state='leased' AND row_value.lease_expires_at<=transaction_timestamp() AND row_value.attempt<10)
  ORDER BY row_value.available_at,row_value.created_at,row_value.delivery_id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false);END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='leased',attempt=attempt+1,lease_owner=owner_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds_value),updated_at=transaction_timestamp()
  WHERE (organization_id,workspace_id,environment_id,delivery_id)=(notification.organization_id,notification.workspace_id,notification.environment_id,notification.delivery_id) RETURNING * INTO notification;
 RETURN jsonb_build_object('found',true,'organization_id',notification.organization_id,'workspace_id',notification.workspace_id,'environment_id',notification.environment_id,'delivery_id',notification.delivery_id,'approval_id',notification.approval_id,'run_id',notification.run_id,'payload',notification.payload::text,'payload_digest','sha256:'||encode(notification.payload_digest,'hex'),'destination_url',notification.destination_url,'secret_reference',notification.secret_reference,'lease_token',notification.lease_token,'lease_expires_at',notification.lease_expires_at,'attempt',notification.attempt);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_complete_approval_notification(organization_value text, workspace_value text, environment_value text, delivery_value text, lease_token_value text, payload_digest_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE changed integer;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(delivery_value) OR lease_token_value!~'^[0-9a-f]{64}$' OR payload_digest_value!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification completion rejected';END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='delivered',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completed_at=transaction_timestamp(),updated_at=transaction_timestamp()
  WHERE (organization_id,workspace_id,environment_id,delivery_id,state,lease_token,payload_digest)=(organization_value,workspace_value,environment_value,delivery_value,'leased',lease_token_value,decode(substr(payload_digest_value,8),'hex')) AND lease_expires_at>transaction_timestamp();
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='approval notification lease lost';END IF;
 RETURN jsonb_build_object('transition','delivered');
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_enqueue_approval_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE webhook_count integer;webhook_body jsonb;configuration_value jsonb;delivery_value text;payload_value jsonb;destination_value text;destination_host text;
BEGIN
 IF NEW.state<>'pending' THEN RETURN NEW;END IF;
 SELECT count(*),(jsonb_agg(record_value.body ORDER BY record_value.id)->0) INTO webhook_count,webhook_body
   FROM zasp_workflow_records record_value
  WHERE (record_value.organization_id,record_value.workspace_id,record_value.environment_id,record_value.kind)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,'integration')
    AND record_value.deleted_at IS NULL AND record_value.body->>'connector_key'='generic-webhook' AND record_value.body->>'status'='configured';
 IF webhook_count<>1 OR jsonb_typeof(webhook_body->'configuration')<>'object' OR (webhook_body->'configuration')-ARRAY['destination_url','signing_secret_reference']<>'{}'::jsonb THEN RETURN NEW;END IF;
 configuration_value:=webhook_body->'configuration';
 destination_value:=configuration_value->>'destination_url';
 destination_host:=split_part(split_part(substr(destination_value,9),'/',1),':',1);
 IF destination_value IS NULL OR char_length(destination_value) NOT BETWEEN 12 AND 2048 OR destination_value!~'^https://[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?(:443)?/[^?#]*$' OR destination_host='' OR destination_host='localhost' OR destination_host LIKE '%.localhost' OR destination_host LIKE '%.local' OR destination_host LIKE '%..%' OR destination_host~'^[0-9.]+$' OR configuration_value->>'signing_secret_reference'!~'^secret_ref_[A-Za-z0-9][A-Za-z0-9._/-]{0,115}$' THEN RETURN NEW;END IF;
 delivery_value:=zasp_discovery_canonical_id(NEW.organization_id,NEW.workspace_id,NEW.environment_id,'security_agent_approval_notification',NEW.approval_id);
 payload_value:=jsonb_build_object('approval',jsonb_build_object('id',NEW.approval_id,'run_id',NEW.run_id),'delivery_id',delivery_value,'event','security_agent.approval_required','scope',jsonb_build_object('environment_id',NEW.environment_id,'organization_id',NEW.organization_id,'workspace_id',NEW.workspace_id),'version',1);
 INSERT INTO zasp_security_agent_approval_notifications(organization_id,workspace_id,environment_id,delivery_id,approval_id,run_id,payload,payload_digest,destination_url,secret_reference)
 VALUES(NEW.organization_id,NEW.workspace_id,NEW.environment_id,delivery_value,NEW.approval_id,NEW.run_id,payload_value,digest(convert_to(payload_value::text,'UTF8'),'sha256'),destination_value,configuration_value->>'signing_secret_reference')
 ON CONFLICT(organization_id,workspace_id,environment_id,approval_id) DO NOTHING;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_fail_approval_notification(organization_value text, workspace_value text, environment_value text, delivery_value text, lease_token_value text, payload_digest_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE notification zasp_security_agent_approval_notifications%ROWTYPE;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(delivery_value) OR lease_token_value!~'^[0-9a-f]{64}$' OR payload_digest_value!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification failure rejected';END IF;
 SELECT * INTO notification FROM zasp_security_agent_approval_notifications row_value WHERE (row_value.organization_id,row_value.workspace_id,row_value.environment_id,row_value.delivery_id)=(organization_value,workspace_value,environment_value,delivery_value) FOR UPDATE;
 IF NOT FOUND OR notification.state<>'leased' OR notification.lease_token<>lease_token_value OR notification.lease_expires_at<=transaction_timestamp() OR notification.payload_digest<>decode(substr(payload_digest_value,8),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='approval notification lease lost';END IF;
 IF notification.attempt>=10 THEN
  UPDATE zasp_security_agent_approval_notifications SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value);
  RETURN jsonb_build_object('transition','exhausted');
 END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='retryable',available_at=transaction_timestamp()+make_interval(secs=>LEAST(60,attempt*attempt)),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value);
 RETURN jsonb_build_object('transition','retryable');
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_execution_integration_setup_status(organization_value text, workspace_value text, environment_value text, integration_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE integration_row zasp_integrations%ROWTYPE;connection_row zasp_integration_connections%ROWTYPE;subject_row zasp_discovery_connection_subjects%ROWTYPE;credential_row zasp_connector_credentials%ROWTYPE;authorization_state text:='pending';scope_kind_value text:='none';scope_label_value text;repository_selection_value text;permissions_value jsonb:='[]'::jsonb;sensor_count_value integer:=0;healthy_count_value integer:=0;missing_count_value integer:=0;unsupported_count_value integer:=0;coverage_state text:='not_applicable';coverage_reason text:='not_applicable';updated_value timestamptz;
BEGIN
  IF NOT zasp_production_integration_setup_readiness(expected_checksum,expected_fingerprint) OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(integration_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration setup status rejected';END IF;
  SELECT * INTO integration_row FROM zasp_integrations integration WHERE (integration.organization_id,integration.workspace_id,integration.environment_id,integration.id)=(organization_value,workspace_value,environment_value,integration_value) AND integration.kind IN('aws','kubernetes','github','okta') AND integration.state<>'deleted';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration setup status missing';END IF;
  updated_value:=integration_row.updated_at;
  IF (SELECT count(*) FROM zasp_integration_connections connection WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.provider,connection.state)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'verified'))=1 THEN
    SELECT * INTO STRICT connection_row FROM zasp_integration_connections connection WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.provider,connection.state)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'verified');
    SELECT * INTO subject_row FROM zasp_discovery_connection_subjects subject WHERE (subject.organization_id,subject.workspace_id,subject.environment_id,subject.integration_id,subject.connection_id,subject.provider,subject.connection_version,subject.configuration_digest)=(organization_value,workspace_value,environment_value,integration_value,connection_row.id,integration_row.kind,connection_row.version,digest(convert_to(integration_row.configuration::text,'UTF8'),'sha256'));
    IF FOUND THEN
      updated_value:=greatest(updated_value,connection_row.updated_at,subject_row.verified_at);
      IF integration_row.kind IN('aws','kubernetes') THEN
        authorization_state:='verified';scope_kind_value:=subject_row.subject_kind;scope_label_value:=subject_row.subject_id;
      ELSIF (SELECT count(*) FROM zasp_connector_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.integration_id,credential.provider,credential.status,credential.credential_reference)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'active',connection_row.connection_reference))=1 THEN
        SELECT * INTO STRICT credential_row FROM zasp_connector_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.integration_id,credential.provider,credential.status,credential.credential_reference)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'active',connection_row.connection_reference);
        updated_value:=greatest(updated_value,credential_row.updated_at);
        IF integration_row.kind='github' AND subject_row.subject_kind='github_installation' AND credential_row.metadata->>'installation_id'=subject_row.subject_id AND credential_row.metadata->>'account_type'='Organization' AND credential_row.metadata->>'account_login'~'^[A-Za-z0-9]([A-Za-z0-9-]{0,37}[A-Za-z0-9])?$' AND credential_row.metadata->>'repository_selection' IN('all','selected') AND credential_row.metadata->'permissions'='{"actions":"read","contents":"read","metadata":"read"}'::jsonb THEN
          authorization_state:='verified';scope_kind_value:='github_organization';scope_label_value:=credential_row.metadata->>'account_login';repository_selection_value:=credential_row.metadata->>'repository_selection';permissions_value:='["actions:read","contents:read","metadata:read"]'::jsonb;
        ELSIF integration_row.kind='okta' AND subject_row.subject_kind='okta_tenant' AND credential_row.metadata->>'tenant'=subject_row.subject_id AND credential_row.metadata->'scopes'='["offline_access","okta.apps.read","okta.groups.read","okta.users.read"]'::jsonb THEN
          authorization_state:='verified';scope_kind_value:='okta_tenant';scope_label_value:=subject_row.subject_id;permissions_value:=credential_row.metadata->'scopes';
        ELSE authorization_state:='degraded';END IF;
      ELSE authorization_state:='degraded';END IF;
    END IF;
  END IF;
  IF integration_row.kind='kubernetes' THEN
    SELECT count(*),count(*) FILTER(WHERE sensor.state='active' AND heartbeat.status='healthy' AND heartbeat.observed_at>=transaction_timestamp()-interval '5 minutes' AND COALESCE((heartbeat.metadata->>'btf')::boolean,false)),count(*) FILTER(WHERE heartbeat.sensor_id IS NULL OR heartbeat.observed_at<transaction_timestamp()-interval '5 minutes'),count(*) FILTER(WHERE heartbeat.observed_at>=transaction_timestamp()-interval '5 minutes' AND NOT COALESCE((heartbeat.metadata->>'btf')::boolean,false)),greatest(updated_value,COALESCE(max(sensor.updated_at),updated_value),COALESCE(max(heartbeat.observed_at),updated_value)) INTO sensor_count_value,healthy_count_value,missing_count_value,unsupported_count_value,updated_value
    FROM zasp_sensors sensor LEFT JOIN zasp_sensor_heartbeats heartbeat ON (heartbeat.organization_id,heartbeat.workspace_id,heartbeat.environment_id,heartbeat.sensor_id)=(sensor.organization_id,sensor.workspace_id,sensor.environment_id,sensor.id)
    WHERE (sensor.organization_id,sensor.workspace_id,sensor.environment_id,sensor.kind)=(organization_value,workspace_value,environment_value,'tetragon') AND sensor.state NOT IN('revoked','deleted');
    IF sensor_count_value=0 THEN coverage_state:='not_enrolled';coverage_reason:='not_enrolled';
    ELSIF missing_count_value>0 THEN coverage_state:='awaiting_heartbeat';coverage_reason:='missing_gateway';
    ELSIF unsupported_count_value>0 THEN coverage_state:='degraded';coverage_reason:='unsupported_kernel';
    ELSIF healthy_count_value=sensor_count_value THEN coverage_state:='healthy';coverage_reason:='verified';
    ELSE coverage_state:='degraded';coverage_reason:='degraded';END IF;
  END IF;
  RETURN jsonb_build_object('integration_id',integration_value,'connector_key',integration_row.kind,'authorization',jsonb_build_object('state',authorization_state,'scope_kind',scope_kind_value,'scope_label',scope_label_value,'repository_selection',repository_selection_value,'permissions',permissions_value),'runtime_coverage',jsonb_build_object('state',coverage_state,'reason',coverage_reason,'sensor_count',sensor_count_value,'healthy_sensor_count',healthy_count_value),'updated_at',to_char(updated_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_integration_webhook_test_complete(organization_value text, workspace_value text, environment_value text, delivery_value text, token_value text, digest_value text, succeeded_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item zasp_integration_webhook_tests%ROWTYPE;next_state text:=CASE WHEN succeeded_value THEN 'succeeded' ELSE 'failed' END;
BEGIN
 IF NOT COALESCE(zasp_production_integration_webhook_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=35),(SELECT value FROM zasp_schema_metadata WHERE key='production_integration_webhook_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration webhook unavailable';END IF;
 SELECT * INTO item FROM zasp_integration_webhook_tests WHERE (organization_id,workspace_id,environment_id,delivery_id,lease_token,payload_digest)=(organization_value,workspace_value,environment_value,delivery_value,token_value,digest_value) FOR UPDATE;
 IF NOT FOUND OR succeeded_value IS NULL OR item.state<>next_state AND (item.state<>'leased' OR item.lease_expires_at<=transaction_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook completion rejected';END IF;
 IF item.state='leased' THEN UPDATE zasp_integration_webhook_tests SET state=next_state,completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value) RETURNING * INTO item;END IF;
 RETURN zasp_integration_webhook_test_public(item);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_integration_webhook_test_reserve(organization_value text, workspace_value text, environment_value text, principal_value text, integration_value text, expected_version bigint, key_value text, audit_value text, correlation_value text, delivery_value text, token_value text, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item zasp_integration_webhook_tests%ROWTYPE;workflow zasp_workflow_records%ROWTYPE;request_digest_value bytea;payload_value text;destination_value text;secret_value text;
BEGIN
 IF NOT COALESCE(zasp_production_integration_webhook_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=35),(SELECT value FROM zasp_schema_metadata WHERE key='production_integration_webhook_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration webhook unavailable';END IF;
 IF NOT COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND zasp_valid_product_id(principal_value) AND zasp_valid_product_id(integration_value) AND zasp_valid_product_id(audit_value) AND zasp_valid_product_id(correlation_value) AND audit_value<>correlation_value AND zasp_valid_product_id(delivery_value) AND expected_version BETWEEN 1 AND 1000000 AND key_value ~ '^[A-Za-z0-9._:-]{16,128}$' AND token_value ~ '^[0-9a-f]{64}$' AND lease_seconds BETWEEN 5 AND 30,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'integration-webhook',organization_value,workspace_value,environment_value,principal_value,key_value),0));
 request_digest_value:=digest(convert_to(jsonb_build_object('integration_id',integration_value,'expected_version',expected_version)::text,'UTF8'),'sha256');
 SELECT * INTO item FROM zasp_integration_webhook_tests WHERE (organization_id,workspace_id,environment_id,principal_id,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,key_value) FOR UPDATE;
 IF FOUND THEN
  IF item.request_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook conflict';END IF;
  IF item.state IN('succeeded','failed') THEN RETURN jsonb_build_object('state',item.state,'delivery_id',item.delivery_id,'status',zasp_integration_webhook_test_public(item));END IF;
  IF item.lease_expires_at>transaction_timestamp() THEN RETURN jsonb_build_object('state','busy','delivery_id',item.delivery_id,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));END IF;
 END IF;
 SELECT * INTO workflow FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=(organization_value,workspace_value,environment_value,'integration',integration_value) AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration webhook missing';END IF;
 IF workflow.version<>expected_version OR workflow.body->>'connector_key' IS DISTINCT FROM 'generic-webhook' OR workflow.body->>'status' IS DISTINCT FROM 'configured' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook configuration changed';END IF;
 destination_value:=workflow.body->'configuration'->>'destination_url';secret_value:=workflow.body->'configuration'->>'signing_secret_reference';
 IF jsonb_typeof(workflow.body->'configuration') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook configuration rejected';END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(workflow.body->'configuration'))<>2 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook configuration rejected';END IF;
 IF NOT COALESCE(length(destination_value)<=2048 AND destination_value ~ '^https://[a-z0-9][a-z0-9.-]*[a-z0-9](:443)?(/[^?#[:cntrl:] ]*)?$' AND position('..' IN destination_value)=0 AND secret_value ~ '^secret_ref_[A-Za-z0-9][A-Za-z0-9._/-]{0,115}$' AND position('..' IN secret_value)=0 AND position('//' IN secret_value)=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook configuration rejected';END IF;
 IF item.delivery_id IS NOT NULL THEN
  IF item.configuration_digest<>digest(convert_to((workflow.body->'configuration')::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook configuration changed';END IF;
  IF item.attempt=3 THEN
   UPDATE zasp_integration_webhook_tests SET state='failed',completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,item.delivery_id) RETURNING * INTO item;
   RETURN jsonb_build_object('state','failed','delivery_id',item.delivery_id,'status',zasp_integration_webhook_test_public(item));
  END IF;
  UPDATE zasp_integration_webhook_tests SET lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),attempt=attempt+1 WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,item.delivery_id) RETURNING * INTO item;
 ELSE
  IF EXISTS(SELECT 1 FROM zasp_integration_webhook_tests WHERE (organization_id,workspace_id,environment_id,integration_id)=(organization_value,workspace_value,environment_value,integration_value) AND attempted_at>transaction_timestamp()-interval '10 seconds') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook test busy';END IF;
  payload_value:=jsonb_build_object('delivery_id',delivery_value,'event','integration.webhook.test','integration',jsonb_build_object('id',integration_value,'version',expected_version),'scope',jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value),'sent_at',to_char(transaction_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'version',1)::text;
  INSERT INTO zasp_integration_webhook_tests(organization_id,workspace_id,environment_id,integration_id,principal_id,idempotency_key,delivery_id,integration_version,request_digest,configuration_digest,destination_url,secret_reference,payload,payload_digest,state,lease_token,lease_expires_at,attempt,audit_id,correlation_id)
  VALUES(organization_value,workspace_value,environment_value,integration_value,principal_value,key_value,delivery_value,expected_version,request_digest_value,digest(convert_to((workflow.body->'configuration')::text,'UTF8'),'sha256'),destination_value,secret_value,payload_value,'sha256:'||encode(digest(convert_to(payload_value,'UTF8'),'sha256'),'hex'),'leased',token_value,transaction_timestamp()+make_interval(secs=>lease_seconds),1,audit_value,correlation_value) RETURNING * INTO item;
  INSERT INTO zasp_workflow_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,principal_id,operation,resource_kind,resource_id,resource_version) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,principal_value,'testIntegrationWebhook','integration',integration_value,expected_version);
 END IF;
 RETURN jsonb_build_object('state','dispatch','delivery_id',item.delivery_id,'payload',item.payload,'payload_digest',item.payload_digest,'destination_url',item.destination_url,'secret_reference',item.secret_reference,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_integration_webhook_test_status(organization_value text, workspace_value text, environment_value text, integration_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item zasp_integration_webhook_tests%ROWTYPE;
BEGIN
 IF NOT COALESCE(zasp_production_integration_webhook_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=35),(SELECT value FROM zasp_schema_metadata WHERE key='production_integration_webhook_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration webhook unavailable';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=(organization_value,workspace_value,environment_value,'integration',integration_value) AND deleted_at IS NULL AND body->>'connector_key'='generic-webhook') THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration webhook missing';END IF;
 SELECT tests.* INTO item FROM zasp_integration_webhook_tests tests JOIN zasp_workflow_records workflow ON (workflow.organization_id,workflow.workspace_id,workflow.environment_id,workflow.kind,workflow.id,workflow.version)=(tests.organization_id,tests.workspace_id,tests.environment_id,'integration',tests.integration_id,tests.integration_version) WHERE (tests.organization_id,tests.workspace_id,tests.environment_id,tests.integration_id)=(organization_value,workspace_value,environment_value,integration_value) AND tests.configuration_digest=digest(convert_to((workflow.body->'configuration')::text,'UTF8'),'sha256') ORDER BY tests.attempted_at DESC,tests.delivery_id LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration webhook test missing';END IF;
 RETURN zasp_integration_webhook_test_public(item);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_connector_claim_reconciliation(owner_value text, lease_seconds integer, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb; available_slots integer;
BEGIN
  IF length(owner_value) NOT BETWEEN 3 AND 128 OR lease_seconds NOT BETWEEN 5 AND 300 OR limit_value NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reconciliation claim'; END IF;
	PERFORM pg_advisory_xact_lock(742516322);
	SELECT GREATEST(0,LEAST(limit_value,100-count(*)::integer)) INTO available_slots FROM zasp_connector_effects WHERE status='unknown' AND lease_expires_at>transaction_timestamp();
	IF available_slots=0 THEN RETURN jsonb_build_object('items','[]'::jsonb); END IF;
  WITH eligible_lanes AS MATERIALIZED (SELECT lane.* FROM zasp_connector_effect_lane_scopes lane WHERE NOT EXISTS(SELECT 1 FROM zasp_connector_effects live WHERE live.provider=lane.provider AND live.operation=lane.operation AND live.status='unknown' AND live.lease_expires_at>transaction_timestamp())), candidates AS (SELECT lane.provider,lane.operation,effect.organization_id,effect.workspace_id,effect.environment_id,effect.id,effect.updated_at FROM eligible_lanes lane CROSS JOIN LATERAL (SELECT candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.id,candidate.updated_at FROM zasp_connector_effects candidate WHERE candidate.provider=lane.provider AND candidate.operation=lane.operation AND candidate.organization_id=lane.organization_id AND candidate.workspace_id=lane.workspace_id AND candidate.environment_id=lane.environment_id AND candidate.status='unknown' AND candidate.attempt<100 AND candidate.available_at<=transaction_timestamp() AND candidate.updated_at<=transaction_timestamp()-interval '15 seconds' AND (candidate.lease_expires_at IS NULL OR candidate.lease_expires_at<=transaction_timestamp()) AND (candidate.operation<>'pkce_cleanup' OR candidate.oauth_attempt_id IS NULL OR NOT EXISTS(SELECT 1 FROM zasp_connector_oauth_attempts attempt WHERE (attempt.organization_id,attempt.workspace_id,attempt.environment_id,attempt.id)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.oauth_attempt_id) AND attempt.status='consuming')) ORDER BY candidate.updated_at,candidate.id LIMIT 1) effect),
  lane_fair AS (SELECT candidates.*,row_number() OVER(PARTITION BY provider,operation ORDER BY updated_at,id) lane_rank FROM candidates),
  fair AS (SELECT lane_fair.*,row_number() OVER(PARTITION BY organization_id,workspace_id,environment_id ORDER BY updated_at,id) organization_rank FROM lane_fair WHERE lane_rank=1),
  selected AS (SELECT effect.organization_id,effect.workspace_id,effect.environment_id,effect.id FROM zasp_connector_effects effect JOIN fair ON (fair.organization_id,fair.workspace_id,fair.environment_id,fair.id)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.id) ORDER BY fair.organization_rank,effect.updated_at,effect.id FOR UPDATE OF effect SKIP LOCKED LIMIT available_slots),
  updated AS (UPDATE zasp_connector_effects effect SET attempt=effect.attempt+1,lease_owner=owner_value,lease_token=encode(gen_random_bytes(32),'hex'),lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),updated_at=transaction_timestamp() FROM selected WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.id)=(selected.organization_id,selected.workspace_id,selected.environment_id,selected.id) RETURNING effect.*)
	  SELECT jsonb_build_object('items',COALESCE(jsonb_agg(jsonb_build_object('organization_id',organization_id,'workspace_id',workspace_id,'environment_id',environment_id,'id',id,'integration_id',integration_id,'oauth_attempt_id',oauth_attempt_id,'principal_id',(SELECT principal_id FROM zasp_connector_oauth_attempts attempt WHERE (attempt.organization_id,attempt.workspace_id,attempt.environment_id,attempt.id)=(updated.organization_id,updated.workspace_id,updated.environment_id,updated.oauth_attempt_id)),'requested_scopes',(SELECT requested_scopes FROM zasp_connector_oauth_attempts attempt WHERE (attempt.organization_id,attempt.workspace_id,attempt.environment_id,attempt.id)=(updated.organization_id,updated.workspace_id,updated.environment_id,updated.oauth_attempt_id)),'provider',provider,'operation',operation,'connection_reference',connection_reference,'idempotency_key',idempotency_key,'request_digest',encode(request_digest,'hex'),'last_error_code',last_error_code,'attempt',attempt,'lease_owner',lease_owner,'lease_token',lease_token,'lease_expires_at',lease_expires_at) ORDER BY updated_at,id),'[]'::jsonb)) INTO result_value FROM updated;
  RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_finish_run(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, token_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint, input_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN PERFORM public.zasp_production_security_agent_existing_tests_legacy_run(organization_value,workspace_value,environment_value,run_value,'zasp_red_team_worker');
 IF NOT zasp_red_team_principal_ready('zasp_red_team_worker') OR NOT zasp_red_team_valid_input_artifact(organization_value,workspace_value,environment_value,input_value) OR input_value->>'reference'=reference_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team input artifact rejected';
 END IF;
 result_value:=zasp_red_team_finish_run_v38(organization_value,workspace_value,environment_value,run_value,worker_value,token_value,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value);
 UPDATE zasp_red_team_attempts SET input_artifact=input_value WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(organization_value,workspace_value,environment_value,run_value,(result_value->>'attempt')::integer) AND input_artifact IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='red team input artifact conflict';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_finish_run_v38(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, token_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_red_team_runs%ROWTYPE;
BEGIN IF NOT zasp_red_team_principal_ready('zasp_red_team_worker') OR octet_length(input_digest_value)<>32 OR verdict_value NOT IN('pass','fail','engine_error') OR verdict_value IN('pass','fail') AND error_value IS NOT NULL OR verdict_value='engine_error' AND error_value NOT IN('denied','malformed','outcome_unknown','exhausted') OR length(objective_value) NOT BETWEEN 1 AND 512 OR objective_value<>btrim(objective_value) OR objective_value~'[[:cntrl:]]' OR length(behavior_value) NOT BETWEEN 1 AND 2048 OR behavior_value<>btrim(behavior_value) OR behavior_value~'[[:cntrl:]]' OR jsonb_typeof(evidence_value)<>'array' OR jsonb_array_length(evidence_value)>64 OR EXISTS(SELECT 1 FROM jsonb_array_elements(evidence_value) evidence_item WHERE jsonb_typeof(evidence_item)<>'string' OR length(evidence_item#>>'{}') NOT BETWEEN 1 AND 512 OR evidence_item#>>'{}'<>btrim(evidence_item#>>'{}') OR evidence_item#>>'{}'~'[[:cntrl:]]') OR reference_value!~'^s3://[a-z0-9][a-z0-9.-]{2,62}/organizations/' OR length(key_value) NOT BETWEEN 1 AND 1024 OR substring(reference_value FROM '^s3://[a-z0-9][a-z0-9.-]{2,62}/(.+)$') IS DISTINCT FROM key_value OR key_value IS DISTINCT FROM 'organizations/'||organization_value||'/workspaces/'||workspace_value||'/environments/'||environment_value||'/artifacts/'||run_value OR length(version_value) NOT BETWEEN 1 AND 512 OR version_value~'[[:space:][:cntrl:]]' OR octet_length(checksum_value)<>32 OR size_value NOT BETWEEN 1 AND 67108864 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team run completion rejected';END IF;
 SELECT * INTO STRICT run_row FROM zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,worker_id,lease_token,input_digest)=(organization_value,workspace_value,environment_value,run_value,'leased',worker_value,token_value,input_digest_value) AND lease_expires_at>transaction_timestamp() FOR UPDATE;
 IF run_row.cancel_requested THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team run cancellation wins';END IF;
 INSERT INTO zasp_red_team_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,verdict,objective,behavior,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size) VALUES(organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value) ON CONFLICT(organization_id,workspace_id,environment_id,run_id,attempt) DO NOTHING;
 IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM zasp_red_team_attempts attempt_value WHERE (attempt_value.organization_id,attempt_value.workspace_id,attempt_value.environment_id,attempt_value.run_id,attempt_value.attempt,attempt_value.input_digest,attempt_value.verdict,attempt_value.objective,attempt_value.behavior,attempt_value.error_code,attempt_value.evidence,attempt_value.evidence_reference,attempt_value.evidence_key,attempt_value.evidence_version_id,attempt_value.evidence_checksum,attempt_value.evidence_size) IS NOT DISTINCT FROM (organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='red team attempt conflict';END IF;
 UPDATE zasp_red_team_runs SET version=version+1,state='complete',verdict=verdict_value,error_code=error_value,evidence_reference=reference_value,evidence_key=key_value,evidence_version_id=version_value,evidence_checksum=checksum_value,evidence_size=size_value,completed_at=transaction_timestamp(),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;RETURN zasp_red_team_run_json(run_row);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team run lease rejected';END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_valid_input_artifact(organization_value text, workspace_value text, environment_value text, input_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE reference_value text; key_value text; prefix_value text;
BEGIN
 IF input_value IS NULL OR jsonb_typeof(input_value)<>'object' THEN RETURN false;END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(input_value))<>4 OR NOT input_value ?& ARRAY['reference','version_id','sha256','size_bytes']
 OR jsonb_typeof(input_value->'reference')<>'string' OR jsonb_typeof(input_value->'version_id')<>'string' OR jsonb_typeof(input_value->'sha256')<>'string' OR jsonb_typeof(input_value->'size_bytes')<>'number'
 OR input_value->>'sha256' !~ '^[a-f0-9]{64}$' OR input_value->>'sha256'=repeat('0',64)
 OR length(input_value->>'version_id') NOT BETWEEN 1 AND 512 OR input_value->>'version_id' ~ '[[:space:][:cntrl:]]'
 OR input_value->>'size_bytes' !~ '^[1-9][0-9]{0,4}$' THEN RETURN false;END IF;
 IF (input_value->>'size_bytes')::bigint>65536 THEN RETURN false;END IF;
 reference_value:=input_value->>'reference';
 IF NOT zasp_discovery_s3_object_reference(reference_value) THEN RETURN false;END IF;
 key_value:=substring(reference_value FROM '^s3://[^/]+/(.+)$');
 prefix_value:='organizations/'||organization_value||'/workspaces/'||workspace_value||'/environments/'||environment_value||'/artifacts/';
 RETURN COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND left(key_value,length(prefix_value))=prefix_value AND zasp_valid_product_id(substring(key_value FROM length(prefix_value)+1)),false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">60)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 60
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_ack_outbox(organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, token_value bytea, ack_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE requested_value bytea;result_value jsonb;published_value timestamptz;remaining_count integer;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_outbox_worker') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(outbox_value) OR length(worker_value) NOT BETWEEN 3 AND 128 OR worker_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR ack_value!~'^sha256:[a-f0-9]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab outbox acknowledgement rejected';END IF;
 requested_value:=digest(convert_to(concat_ws(chr(31),outbox_value,worker_value,encode(token_value,'hex'),ack_value),'UTF8'),'sha256');
 SELECT completion_result INTO result_value FROM zasp_attack_lab_outbox WHERE (organization_id,workspace_id,environment_id,outbox_id,topic,state,completion_digest)=(organization_value,workspace_value,environment_value,outbox_value,'attack-lab-jobs','published',requested_value) FOR UPDATE;
 IF FOUND THEN SELECT count(*) INTO remaining_count FROM zasp_attack_lab_outbox WHERE topic='attack-lab-jobs' AND state='leased' AND worker_id=worker_value AND lease_token=token_value AND lease_expires_at>transaction_timestamp();RETURN result_value||jsonb_build_object('remaining_count',remaining_count,'replayed',true);END IF;
 IF EXISTS(SELECT 1 FROM zasp_attack_lab_outbox WHERE (organization_id,workspace_id,environment_id,outbox_id,topic,state)=(organization_value,workspace_value,environment_value,outbox_value,'attack-lab-jobs','published')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='attack lab outbox acknowledgement conflict';END IF;
 UPDATE zasp_attack_lab_outbox SET state='published',provider_ack=ack_value,published_at=transaction_timestamp(),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,last_error=NULL,completion_digest=requested_value,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,outbox_id,topic,state,worker_id,lease_token)=(organization_value,workspace_value,environment_value,outbox_value,'attack-lab-jobs','leased',worker_value,token_value) AND lease_expires_at>transaction_timestamp() RETURNING published_at INTO published_value;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab outbox lease rejected';END IF;
 result_value:=jsonb_build_object('outbox_id',outbox_value,'state','published','provider_ack',ack_value,'published_at',to_char(published_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));UPDATE zasp_attack_lab_outbox SET completion_result=result_value WHERE (organization_id,workspace_id,environment_id,outbox_id)=(organization_value,workspace_value,environment_value,outbox_value);
 SELECT count(*) INTO remaining_count FROM zasp_attack_lab_outbox WHERE topic='attack-lab-jobs' AND state='leased' AND worker_id=worker_value AND lease_token=token_value AND lease_expires_at>transaction_timestamp();RETURN result_value||jsonb_build_object('remaining_count',remaining_count,'replayed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_begin_cleanup(organization_value text, workspace_value text, environment_value text, run_value text, controller_value text, token_value bytea, input_digest_value bytea, sandbox_value text, verdict_value text, criterion_value boolean, canary_value boolean, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_attack_lab_runs%ROWTYPE;checkpoint_row zasp_attack_lab_cleanup_checkpoints%ROWTYPE;evidence_state_value text;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_controller') OR octet_length(input_digest_value)<>32 OR sandbox_value!~'^k8s://attack-lab/jobs/zasp-attack-lab-[a-z0-9-]{8,64}@[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' OR verdict_value NOT IN('verified','not_reproduced','inconclusive') OR verdict_value='verified' AND (NOT criterion_value OR NOT canary_value) OR verdict_value='not_reproduced' AND (criterion_value OR canary_value) OR verdict_value IN('verified','not_reproduced') AND error_value IS NOT NULL OR verdict_value='inconclusive' AND error_value NOT IN('denied','malformed','outcome_unknown','exhausted','cancelled') OR jsonb_typeof(evidence_value)<>'array' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab cleanup checkpoint rejected';END IF;
 evidence_state_value:=CASE WHEN reference_value='' THEN 'unavailable' ELSE 'complete' END;
 IF evidence_state_value='complete' AND (jsonb_array_length(evidence_value)<>5 OR evidence_value->>0 NOT LIKE 'semantic:%' OR evidence_value->>1 NOT LIKE 'gateway:%' OR evidence_value->>2 NOT LIKE 'egress:%' OR evidence_value->>3 NOT LIKE 'kubernetes:%' OR evidence_value->>4 NOT LIKE 'cloud:%' OR EXISTS(SELECT 1 FROM jsonb_array_elements(evidence_value) item WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}') NOT BETWEEN 1 AND 512 OR item#>>'{}'<>btrim(item#>>'{}') OR item#>>'{}'~'[[:cntrl:]]') OR reference_value!~'^s3://[a-z0-9][a-z0-9.-]{2,62}/organizations/' OR key_value IS DISTINCT FROM 'organizations/'||organization_value||'/workspaces/'||workspace_value||'/environments/'||environment_value||'/artifacts/'||zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'attack_lab_evidence',run_value||chr(31)||(SELECT attempt::text FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value))) OR substring(reference_value FROM '^s3://[a-z0-9][a-z0-9.-]{2,62}/(.+)$') IS DISTINCT FROM key_value OR length(version_value) NOT BETWEEN 1 AND 512 OR version_value~'[[:space:][:cntrl:]]' OR octet_length(checksum_value)<>32 OR size_value NOT BETWEEN 1 AND 67108864) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab cleanup evidence rejected';END IF;
 IF evidence_state_value='unavailable' AND (verdict_value<>'inconclusive' OR criterion_value OR canary_value OR error_value NOT IN('outcome_unknown','cancelled') OR evidence_value<>'[]'::jsonb OR key_value<>'' OR version_value<>'' OR octet_length(checksum_value)<>0 OR size_value<>0) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab unavailable evidence rejected';END IF;
 SELECT * INTO STRICT run_row FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id,controller_id,lease_token,input_digest,sandbox_reference)=(organization_value,workspace_value,environment_value,run_value,controller_value,token_value,input_digest_value,sandbox_value) AND state IN('running','cleanup') AND lease_expires_at>transaction_timestamp() FOR UPDATE;
 SELECT * INTO STRICT checkpoint_row FROM zasp_attack_lab_cleanup_checkpoints WHERE (organization_id,workspace_id,environment_id,run_id,attempt,input_digest,sandbox_reference)=(organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,sandbox_value) FOR UPDATE;
 IF checkpoint_row.evidence_state<>'pending' THEN
  IF (checkpoint_row.evidence_state,checkpoint_row.verdict,checkpoint_row.criterion_observed,checkpoint_row.canary_touched,checkpoint_row.error_code,checkpoint_row.evidence,checkpoint_row.evidence_reference,checkpoint_row.evidence_key,checkpoint_row.evidence_version_id,checkpoint_row.evidence_checksum,checkpoint_row.evidence_size) IS DISTINCT FROM (evidence_state_value,verdict_value,criterion_value,canary_value,error_value,evidence_value,NULLIF(reference_value,''),NULLIF(key_value,''),NULLIF(version_value,''),NULLIF(checksum_value,''::bytea),NULLIF(size_value,0)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='attack lab cleanup checkpoint conflict';END IF;
  IF run_row.state<>'cleanup' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab cleanup state missing';END IF;
  RETURN zasp_attack_lab_run_json(run_row)||jsonb_build_object('replayed',true);
 END IF;
 IF run_row.state<>'running' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab cleanup evidence missing';END IF;
 UPDATE zasp_attack_lab_cleanup_checkpoints SET evidence_state=evidence_state_value,verdict=verdict_value,criterion_observed=criterion_value,canary_touched=canary_value,error_code=error_value,evidence=evidence_value,evidence_reference=NULLIF(reference_value,''),evidence_key=NULLIF(key_value,''),evidence_version_id=NULLIF(version_value,''),evidence_checksum=NULLIF(checksum_value,''::bytea),evidence_size=NULLIF(size_value,0),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(organization_value,workspace_value,environment_value,run_value,run_row.attempt);
 UPDATE zasp_attack_lab_runs SET version=version+1,state='cleanup',cleanup_state='in_progress',updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;RETURN zasp_attack_lab_run_json(run_row)||jsonb_build_object('replayed',false);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab cleanup lease rejected';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_begin_provisioning(organization_value text, workspace_value text, environment_value text, run_value text, controller_value text, token_value bytea, input_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_attack_lab_runs%ROWTYPE;name_value text;replayed_value boolean:=false;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_controller') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) OR length(controller_value) NOT BETWEEN 3 AND 128 OR controller_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR octet_length(input_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab provisioning intent rejected';END IF;
 name_value:='zasp-attack-lab-'||substring(encode(digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,run_value),'UTF8'),'sha256'),'hex') FROM 1 FOR 32);
 IF name_value!~'^zasp-attack-lab-[a-f0-9]{32}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab provisioning identity rejected';END IF;
 SELECT * INTO run_row FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,controller_id,lease_token,input_digest)=(organization_value,workspace_value,environment_value,run_value,'leased',controller_value,token_value,input_digest_value) AND lease_expires_at>transaction_timestamp() AND preflight IS NOT NULL AND sandbox_reference IS NULL FOR UPDATE;
 IF NOT FOUND OR run_row.sandbox_name IS NOT NULL AND run_row.sandbox_name<>name_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab provisioning lease rejected';END IF;
 IF run_row.sandbox_name=name_value THEN replayed_value:=true;ELSE UPDATE zasp_attack_lab_runs SET sandbox_name=name_value,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;END IF;
 RETURN zasp_attack_lab_run_json(run_row)||jsonb_build_object('replayed',replayed_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_claim_outbox(worker_value text, token_value bytea, lease_seconds integer, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;last_organization text;claimed_last_organization text;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_outbox_worker') OR length(worker_value) NOT BETWEEN 3 AND 128 OR worker_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR lease_seconds NOT BETWEEN 5 AND 900 OR limit_value NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab outbox claim rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp_attack_lab_outbox:attack-lab-jobs',0));
 INSERT INTO zasp_attack_lab_outbox_fairness(topic) VALUES('attack-lab-jobs') ON CONFLICT(topic) DO NOTHING;
 SELECT last_organization_id INTO last_organization FROM zasp_attack_lab_outbox_fairness WHERE topic='attack-lab-jobs' FOR UPDATE;
 UPDATE zasp_attack_lab_outbox SET state='failed',worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,last_error=COALESCE(last_error,'queue_publish_unknown'),updated_at=transaction_timestamp() WHERE topic='attack-lab-jobs' AND state='leased' AND attempt>=100 AND lease_expires_at<=transaction_timestamp();
 WITH organizations AS (
  SELECT candidate.organization_id,min(candidate.available_at) due FROM zasp_attack_lab_outbox candidate
  WHERE candidate.topic='attack-lab-jobs' AND candidate.attempt<100 AND (candidate.state='pending' OR candidate.state='leased' AND candidate.lease_expires_at<=transaction_timestamp()) AND candidate.available_at<=transaction_timestamp()
   AND NOT EXISTS(SELECT 1 FROM zasp_attack_lab_outbox live WHERE live.organization_id=candidate.organization_id AND live.topic='attack-lab-jobs' AND live.state='leased' AND live.lease_expires_at>transaction_timestamp())
  GROUP BY candidate.organization_id
 ),ordered_organizations AS (
  SELECT organization_id,due,row_number() OVER(ORDER BY CASE WHEN last_organization IS NULL OR organization_id>last_organization THEN 0 ELSE 1 END,organization_id) fair_order FROM organizations ORDER BY fair_order LIMIT limit_value
 ),picked AS (
  SELECT chosen.ctid,chosen.organization_id,chosen.available_at,chosen.created_at,chosen.outbox_id,organization.fair_order FROM ordered_organizations organization
  CROSS JOIN LATERAL (SELECT outbox.ctid,outbox.organization_id,outbox.available_at,outbox.created_at,outbox.outbox_id FROM zasp_attack_lab_outbox outbox WHERE outbox.organization_id=organization.organization_id AND outbox.topic='attack-lab-jobs' AND outbox.attempt<100 AND (outbox.state='pending' OR outbox.state='leased' AND outbox.lease_expires_at<=transaction_timestamp()) AND outbox.available_at<=transaction_timestamp() ORDER BY outbox.available_at,outbox.created_at,outbox.outbox_id LIMIT 1 FOR UPDATE SKIP LOCKED) chosen
 ),leased AS (
  UPDATE zasp_attack_lab_outbox outbox SET state='leased',attempt=attempt+1,worker_id=worker_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),provider_ack=NULL,published_at=NULL,last_error=NULL,completion_digest=NULL,completion_result=NULL,updated_at=transaction_timestamp() FROM (SELECT * FROM picked ORDER BY fair_order) candidate WHERE outbox.ctid=candidate.ctid RETURNING outbox.*,candidate.fair_order
 ) SELECT jsonb_build_object('items',COALESCE(jsonb_agg(jsonb_build_object('organization_id',organization_id,'workspace_id',workspace_id,'environment_id',environment_id,'outbox_id',outbox_id,'topic',topic,'payload',payload::text,'payload_digest',encode(payload_digest,'hex'),'attempt',attempt,'lease_expires_at',to_char(lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY fair_order),'[]'::jsonb)),(array_agg(organization_id ORDER BY fair_order DESC))[1] INTO result_value,claimed_last_organization FROM leased;
 IF claimed_last_organization IS NOT NULL THEN UPDATE zasp_attack_lab_outbox_fairness SET last_organization_id=claimed_last_organization,updated_at=transaction_timestamp() WHERE topic='attack-lab-jobs';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_claim_run(organization_value text, workspace_value text, environment_value text, run_value text, controller_value text, token_value bytea, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_attack_lab_runs%ROWTYPE;definition_row zasp_red_team_definitions%ROWTYPE;target_row zasp_inventory_entities%ROWTYPE;binding_row zasp_attack_lab_credential_bindings%ROWTYPE;source_row zasp_red_team_runs%ROWTYPE;source_attempt zasp_red_team_attempts%ROWTYPE;checkpoint_row zasp_attack_lab_cleanup_checkpoints%ROWTYPE;destination_value text;environment_class_value text;preflight_value jsonb;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_controller') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) OR length(controller_value) NOT BETWEEN 3 AND 128 OR controller_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR lease_seconds NOT BETWEEN 30 AND 900 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab run claim rejected';END IF;
 SELECT * INTO run_row FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab run not found';END IF;
 IF run_row.state IN('complete','failed','cancelled') THEN RETURN jsonb_build_object('disposition','ack_terminal');END IF;
 IF run_row.state IN('leased','running','cleanup') AND run_row.lease_expires_at>transaction_timestamp() OR run_row.next_attempt_at>transaction_timestamp() THEN RETURN jsonb_build_object('disposition','retry_later');END IF;
 IF run_row.state='running' AND run_row.attempt_started_at+interval '300 seconds'<=transaction_timestamp() THEN
  UPDATE zasp_attack_lab_cleanup_checkpoints SET evidence_state='unavailable',verdict='inconclusive',criterion_observed=false,canary_touched=false,error_code='outcome_unknown',evidence='[]'::jsonb,evidence_reference=NULL,evidence_key=NULL,evidence_version_id=NULL,evidence_checksum=NULL,evidence_size=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,attempt,input_digest,evidence_state)=(organization_value,workspace_value,environment_value,run_value,run_row.attempt,run_row.input_digest,'pending');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab expired attempt cleanup intent missing';END IF;
  UPDATE zasp_attack_lab_runs SET version=version+1,state='cleanup',cleanup_state='in_progress',controller_id=controller_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),error_code='outcome_unknown',updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,state)=(organization_value,workspace_value,environment_value,run_value,'running') RETURNING * INTO run_row;
 END IF;
	 IF run_row.state='cleanup' THEN UPDATE zasp_attack_lab_runs SET controller_id=controller_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;SELECT * INTO STRICT checkpoint_row FROM zasp_attack_lab_cleanup_checkpoints WHERE (organization_id,workspace_id,environment_id,run_id,attempt,input_digest)=(organization_value,workspace_value,environment_value,run_value,run_row.attempt,run_row.input_digest);RETURN jsonb_build_object('disposition','cleanup','run',zasp_attack_lab_run_json(run_row),'checkpoint',jsonb_strip_nulls(jsonb_build_object('attempt',checkpoint_row.attempt,'sandbox_reference',checkpoint_row.sandbox_reference,'evidence_state',checkpoint_row.evidence_state,'verdict',checkpoint_row.verdict,'criterion_observed',checkpoint_row.criterion_observed,'canary_touched',checkpoint_row.canary_touched,'error_code',checkpoint_row.error_code,'evidence',checkpoint_row.evidence,'evidence_reference',checkpoint_row.evidence_reference,'evidence_key',checkpoint_row.evidence_key,'evidence_version_id',checkpoint_row.evidence_version_id,'evidence_checksum',encode(checkpoint_row.evidence_checksum,'hex'),'evidence_size',checkpoint_row.evidence_size)),'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',to_char(run_row.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));END IF;
	 IF run_row.state='leased' AND run_row.sandbox_name IS NOT NULL THEN
	  UPDATE zasp_attack_lab_runs SET controller_id=controller_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,state)=(organization_value,workspace_value,environment_value,run_value,'leased') AND preflight IS NOT NULL AND sandbox_reference IS NULL RETURNING * INTO run_row;
	  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab provisioning intent missing';END IF;
	  RETURN jsonb_build_object('disposition','provisioning','run',zasp_attack_lab_run_json(run_row),'preflight',run_row.preflight,'sandbox_name',run_row.sandbox_name,'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',to_char(run_row.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
	 END IF;
	 IF run_row.state='running' THEN
  UPDATE zasp_attack_lab_runs SET controller_id=controller_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,state)=(organization_value,workspace_value,environment_value,run_value,'running') AND sandbox_reference IS NOT NULL RETURNING * INTO run_row;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab running checkpoint missing';END IF;
	  RETURN jsonb_build_object('disposition','running','run',zasp_attack_lab_run_json(run_row),'preflight',run_row.preflight,'sandbox_reference',run_row.sandbox_reference,'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',to_char(run_row.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 END IF;
 IF run_row.state IN('queued','retryable') AND run_row.attempt>=5 THEN UPDATE zasp_attack_lab_runs SET version=version+1,state='failed',cleanup_state='complete',error_code='exhausted',completed_at=transaction_timestamp(),controller_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;RETURN jsonb_build_object('disposition','ack_terminal');END IF;
 SELECT * INTO STRICT source_row FROM zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,verdict)=(organization_value,workspace_value,environment_value,run_row.source_run_id,'complete','fail') FOR SHARE;
 SELECT * INTO STRICT source_attempt FROM zasp_red_team_attempts WHERE (organization_id,workspace_id,environment_id,run_id,attempt,verdict)=(organization_value,workspace_value,environment_value,run_row.source_run_id,source_row.attempt,'fail') FOR SHARE;
 SELECT * INTO STRICT definition_row FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled,target_id,target_kind)=(organization_value,workspace_value,environment_value,run_row.definition_id,run_row.definition_version,true,run_row.target_id,run_row.target_kind) FOR SHARE;
 SELECT environment_class INTO STRICT environment_class_value FROM zasp_environments WHERE (organization_id,workspace_id,id)=(organization_value,workspace_value,environment_value);
 SELECT * INTO STRICT target_row FROM zasp_inventory_entities WHERE (organization_id,workspace_id,environment_id,id,state)=(organization_value,workspace_value,environment_value,run_row.target_id,'active') AND fresh_until>transaction_timestamp() AND zasp_red_team_target_binding_valid(winning_attributes->'red_team',run_row.target_kind) FOR SHARE;
 SELECT * INTO STRICT binding_row FROM zasp_attack_lab_credential_bindings WHERE (organization_id,workspace_id,environment_id,binding_id,target_id,credential_reference,credential_class,version,reference_digest,state)=(organization_value,workspace_value,environment_value,run_row.credential_binding_id,run_row.target_id,target_row.winning_attributes->'red_team'->>'credential_reference',run_row.credential_class,run_row.credential_binding_version,run_row.credential_binding_digest,'active') AND valid_until>transaction_timestamp() FOR SHARE;
 destination_value:=substring(target_row.winning_attributes->'red_team'->>'endpoint' FROM '^https://([^/]+)/v1/evaluate$');
 IF environment_class_value='production' OR environment_class_value<>run_row.environment OR destination_value IS NULL OR destination_value<>run_row.destination OR definition_row.safety->>'environment'<>run_row.environment OR definition_row.safety->>'credential_class'<>run_row.credential_class THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab run authority drift';END IF;
	 preflight_value:=jsonb_build_object('environment',run_row.environment,'credential_class',run_row.credential_class,'destination',run_row.destination,'allowed_destinations',jsonb_build_array(run_row.destination),'success_criterion',source_attempt.objective,'expected_side_effects',definition_row.safety->'expected_side_effects');
	 UPDATE zasp_attack_lab_runs SET version=version+1,state='leased',attempt=CASE WHEN state IN('queued','retryable') THEN attempt+1 ELSE attempt END,attempt_started_at=transaction_timestamp(),preflight=preflight_value,sandbox_name=NULL,controller_id=controller_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),started_at=COALESCE(started_at,transaction_timestamp()),error_code=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;
	 RETURN jsonb_build_object('disposition','claimed','run',zasp_attack_lab_run_json(run_row),'preflight',run_row.preflight,'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',to_char(run_row.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab run authority unavailable';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_finish_cleanup(organization_value text, workspace_value text, environment_value text, run_value text, controller_value text, token_value bytea, input_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_attack_lab_runs%ROWTYPE;checkpoint_row zasp_attack_lab_cleanup_checkpoints%ROWTYPE;requested_value bytea;result_value jsonb;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_controller') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) OR length(controller_value) NOT BETWEEN 3 AND 128 OR controller_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR octet_length(input_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab cleanup completion rejected';END IF;
 requested_value:=digest(convert_to(concat_ws(chr(31),run_value,controller_value,encode(token_value,'hex'),encode(input_digest_value,'hex')),'UTF8'),'sha256');SELECT * INTO checkpoint_row FROM zasp_attack_lab_cleanup_checkpoints WHERE (organization_id,workspace_id,environment_id,run_id,input_digest)=(organization_value,workspace_value,environment_value,run_value,input_digest_value) ORDER BY attempt DESC LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab cleanup checkpoint missing';END IF;
 IF checkpoint_row.finish_digest=requested_value THEN RETURN checkpoint_row.finish_result||jsonb_build_object('replayed',true);ELSIF checkpoint_row.finish_digest IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='attack lab cleanup completion conflict';END IF;
 SELECT * INTO STRICT run_row FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,controller_id,lease_token,input_digest,attempt)=(organization_value,workspace_value,environment_value,run_value,'cleanup',controller_value,token_value,input_digest_value,checkpoint_row.attempt) AND lease_expires_at>transaction_timestamp() FOR UPDATE;
 IF run_row.cancel_requested THEN
  INSERT INTO zasp_attack_lab_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,evidence_state,verdict,criterion_observed,canary_touched,cleanup_completed,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size) VALUES(organization_value,workspace_value,environment_value,run_value,checkpoint_row.attempt,input_digest_value,checkpoint_row.evidence_state,NULL,false,false,true,'cancelled',checkpoint_row.evidence,checkpoint_row.evidence_reference,checkpoint_row.evidence_key,checkpoint_row.evidence_version_id,checkpoint_row.evidence_checksum,checkpoint_row.evidence_size);
  UPDATE zasp_attack_lab_runs SET version=version+1,state='cancelled',cleanup_state='complete',verdict=NULL,error_code='cancelled',evidence_reference=checkpoint_row.evidence_reference,evidence_key=checkpoint_row.evidence_key,evidence_version_id=checkpoint_row.evidence_version_id,evidence_checksum=checkpoint_row.evidence_checksum,evidence_size=checkpoint_row.evidence_size,completed_at=transaction_timestamp(),controller_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;
 ELSE
  INSERT INTO zasp_attack_lab_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,evidence_state,verdict,criterion_observed,canary_touched,cleanup_completed,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size) VALUES(organization_value,workspace_value,environment_value,run_value,checkpoint_row.attempt,input_digest_value,checkpoint_row.evidence_state,checkpoint_row.verdict,checkpoint_row.criterion_observed,checkpoint_row.canary_touched,true,checkpoint_row.error_code,checkpoint_row.evidence,checkpoint_row.evidence_reference,checkpoint_row.evidence_key,checkpoint_row.evidence_version_id,checkpoint_row.evidence_checksum,checkpoint_row.evidence_size);
  UPDATE zasp_attack_lab_runs SET version=version+1,state='complete',cleanup_state='complete',verdict=checkpoint_row.verdict,error_code=CASE WHEN checkpoint_row.evidence_state='unavailable' THEN checkpoint_row.error_code END,evidence_reference=checkpoint_row.evidence_reference,evidence_key=checkpoint_row.evidence_key,evidence_version_id=checkpoint_row.evidence_version_id,evidence_checksum=checkpoint_row.evidence_checksum,evidence_size=checkpoint_row.evidence_size,completed_at=transaction_timestamp(),controller_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;
 END IF;
 result_value:=zasp_attack_lab_run_json(run_row);UPDATE zasp_attack_lab_cleanup_checkpoints SET finish_digest=requested_value,finish_result=result_value,finished_at=transaction_timestamp(),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(organization_value,workspace_value,environment_value,run_value,checkpoint_row.attempt);RETURN result_value||jsonb_build_object('replayed',false);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab cleanup lease rejected';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_get_run(organization_value text, workspace_value text, environment_value text, run_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE row_value zasp_attack_lab_runs%ROWTYPE;attempt_value jsonb;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab run rejected';END IF;
 SELECT * INTO STRICT row_value FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);
 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('attempt',attempt,'evidence_state',evidence_state,'verdict',verdict,'criterion_observed',criterion_observed,'canary_touched',canary_touched,'cleanup_completed',cleanup_completed,'error_code',error_code,'evidence',evidence,'evidence_reference',evidence_reference,'evidence_version_id',evidence_version_id,'evidence_checksum',encode(evidence_checksum,'hex'),'evidence_size',evidence_size,'completed_at',to_char(completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))) ORDER BY attempt) INTO attempt_value FROM zasp_attack_lab_attempts WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);
 RETURN zasp_attack_lab_run_json(row_value)||jsonb_build_object('attempts',COALESCE(attempt_value,'[]'::jsonb));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab run not found';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_heartbeat_outbox(worker_value text, token_value bytea, lease_seconds integer, expected_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE expiration_value timestamptz;updated_count integer;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_outbox_worker') OR length(worker_value) NOT BETWEEN 3 AND 128 OR worker_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR lease_seconds NOT BETWEEN 5 AND 900 OR expected_count NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab outbox heartbeat rejected';END IF;
 expiration_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);
 UPDATE zasp_attack_lab_outbox SET lease_expires_at=expiration_value,updated_at=transaction_timestamp() WHERE topic='attack-lab-jobs' AND state='leased' AND worker_id=worker_value AND lease_token=token_value AND lease_expires_at>transaction_timestamp();GET DIAGNOSTICS updated_count=ROW_COUNT;
 IF updated_count<>expected_count THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab outbox lease set conflict';END IF;
 RETURN jsonb_build_object('topic','attack-lab-jobs','lease_expires_at',to_char(expiration_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'remaining_count',updated_count);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_heartbeat_run(organization_value text, workspace_value text, environment_value text, run_value text, controller_value text, token_value bytea, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cancel_value boolean;expiration_value timestamptz;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_controller') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) OR length(controller_value) NOT BETWEEN 3 AND 128 OR controller_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR lease_seconds NOT BETWEEN 30 AND 900 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab run heartbeat rejected';END IF;
 expiration_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);UPDATE zasp_attack_lab_runs SET lease_expires_at=expiration_value,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,controller_id,lease_token)=(organization_value,workspace_value,environment_value,run_value,controller_value,token_value) AND state IN('leased','running','cleanup') AND lease_expires_at>transaction_timestamp() RETURNING cancel_requested INTO cancel_value;
 RETURN jsonb_build_object('renewed',FOUND,'cancel_requested',COALESCE(cancel_value,false),'lease_expires_at',CASE WHEN FOUND THEN to_char(expiration_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_mark_running(organization_value text, workspace_value text, environment_value text, run_value text, controller_value text, token_value bytea, input_digest_value bytea, sandbox_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_attack_lab_runs%ROWTYPE;
BEGIN
 IF NOT zasp_attack_lab_principal_ready('zasp_attack_lab_controller') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) OR length(controller_value) NOT BETWEEN 3 AND 128 OR controller_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR octet_length(input_digest_value)<>32 OR sandbox_value!~'^k8s://attack-lab/jobs/zasp-attack-lab-[a-z0-9-]{8,64}@[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab running transition rejected';END IF;
 SELECT * INTO run_row FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,controller_id,lease_token,input_digest,sandbox_reference)=(organization_value,workspace_value,environment_value,run_value,'running',controller_value,token_value,input_digest_value,sandbox_value) AND lease_expires_at>transaction_timestamp() FOR UPDATE;
 IF FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM zasp_attack_lab_cleanup_checkpoints WHERE (organization_id,workspace_id,environment_id,run_id,attempt,input_digest,sandbox_reference,evidence_state)=(organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,sandbox_value,'pending')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab cleanup intent missing';END IF;
  RETURN zasp_attack_lab_run_json(run_row)||jsonb_build_object('replayed',true);
 END IF;
	 UPDATE zasp_attack_lab_runs SET version=version+1,state='running',sandbox_reference=sandbox_value,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,state,controller_id,lease_token,input_digest)=(organization_value,workspace_value,environment_value,run_value,'leased',controller_value,token_value,input_digest_value) AND lease_expires_at>transaction_timestamp() AND preflight IS NOT NULL AND sandbox_name=substring(sandbox_value FROM '^k8s://attack-lab/jobs/([^@]+)@') AND sandbox_reference IS NULL RETURNING * INTO run_row;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab running lease rejected';END IF;
 INSERT INTO zasp_attack_lab_cleanup_checkpoints(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,sandbox_reference) VALUES(organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,sandbox_value);
 RETURN zasp_attack_lab_run_json(run_row)||jsonb_build_object('replayed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_mutation_result(organization_value text, workspace_value text, environment_value text, actor_value text, operation_value text, resource_value text, correlation_value text, idempotency_value text, body_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE audit_value text;receipt_value text;event_value text;result_value jsonb;
BEGIN
 IF operation_value NOT IN('createAttackLabRun','cancelAttackLabRun','rerunAttackLabRun') OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(resource_value) OR NOT zasp_valid_product_id(correlation_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR jsonb_typeof(body_value)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab mutation result rejected';END IF;
 audit_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'attack_lab_audit',actor_value||chr(31)||operation_value||chr(31)||idempotency_value);
 receipt_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'attack_lab_receipt',actor_value||chr(31)||operation_value||chr(31)||idempotency_value);
 event_value:=CASE operation_value WHEN 'createAttackLabRun' THEN 'attack_lab_run_queued' WHEN 'cancelAttackLabRun' THEN 'attack_lab_run_cancelled' ELSE 'attack_lab_run_rerun' END;
 result_value:=jsonb_build_object('body',body_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
 INSERT INTO zasp_attack_lab_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,receipt_id,actor_id,event_kind,resource_id,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,receipt_value,actor_value,event_value,resource_value,digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_preflight(organization_value text, workspace_value text, environment_value text, source_run_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source_row zasp_red_team_runs%ROWTYPE;source_attempt zasp_red_team_attempts%ROWTYPE;definition_row zasp_red_team_definitions%ROWTYPE;target_row zasp_inventory_entities%ROWTYPE;binding_row zasp_attack_lab_credential_bindings%ROWTYPE;environment_class_value text;destination_value text;decision_expires_value timestamptz;decision_value jsonb;authority_value jsonb;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(source_run_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab preflight rejected';END IF;
 SELECT * INTO STRICT source_row FROM zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,verdict)=(organization_value,workspace_value,environment_value,source_run_value,'complete','fail');
 SELECT * INTO STRICT source_attempt FROM zasp_red_team_attempts WHERE (organization_id,workspace_id,environment_id,run_id,attempt,verdict)=(organization_value,workspace_value,environment_value,source_run_value,source_row.attempt,'fail');
 SELECT * INTO STRICT definition_row FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled)=(organization_value,workspace_value,environment_value,source_row.definition_id,source_row.definition_version,true);
 SELECT environment_class INTO STRICT environment_class_value FROM zasp_environments WHERE (organization_id,workspace_id,id)=(organization_value,workspace_value,environment_value);
 IF environment_class_value='production' OR environment_class_value<>definition_row.safety->>'environment' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab preflight environment rejected';END IF;
 SELECT * INTO STRICT target_row FROM zasp_inventory_entities WHERE (organization_id,workspace_id,environment_id,id,state)=(organization_value,workspace_value,environment_value,definition_row.target_id,'active') AND fresh_until>transaction_timestamp() AND zasp_red_team_target_binding_valid(winning_attributes->'red_team',definition_row.target_kind);
 SELECT * INTO STRICT binding_row FROM zasp_attack_lab_credential_bindings WHERE (organization_id,workspace_id,environment_id,target_id,credential_reference,credential_class,state)=(organization_value,workspace_value,environment_value,definition_row.target_id,target_row.winning_attributes->'red_team'->>'credential_reference',definition_row.safety->>'credential_class','active') AND valid_until>transaction_timestamp();
 destination_value:=substring(target_row.winning_attributes->'red_team'->>'endpoint' FROM '^https://([^/]+)/v1/evaluate$');IF destination_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab preflight destination rejected';END IF;
 decision_expires_value:=LEAST(target_row.fresh_until,binding_row.valid_until);
 decision_value:=jsonb_build_object('source_run_id',source_row.run_id,'definition_id',definition_row.definition_id,'definition_version',definition_row.version,'target_id',definition_row.target_id,'target_kind',definition_row.target_kind,'environment',environment_class_value,'credential_class',binding_row.credential_class,'destination',destination_value,'allowed_destinations',jsonb_build_array(destination_value),'success_criterion',source_attempt.objective,'expected_side_effects',definition_row.safety->'expected_side_effects','decision_expires_at',to_char(decision_expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'limits',jsonb_build_object('cpu','500m','memory','1Gi','ephemeral_storage','2Gi','timeout_seconds',300));
 authority_value:=decision_value||jsonb_build_object('credential_binding_id',binding_row.binding_id,'credential_binding_version',binding_row.version,'credential_binding_digest',encode(binding_row.reference_digest,'hex'),'credential_binding_valid_until',to_char(binding_row.valid_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'target_attributes_digest',encode(digest(convert_to(target_row.winning_attributes::text,'UTF8'),'sha256'),'hex'),'target_fresh_until',to_char(target_row.fresh_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 RETURN decision_value||jsonb_build_object('decision_digest',encode(digest(convert_to(authority_value::text,'UTF8'),'sha256'),'hex'));
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab preflight unavailable';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_register_credential_binding(organization_value text, workspace_value text, environment_value text, binding_value text, target_value text, reference_value text, class_value text, version_value bigint, digest_value bytea, valid_until_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE target_row zasp_inventory_entities%ROWTYPE;binding_row zasp_attack_lab_credential_bindings%ROWTYPE;replayed_value boolean:=false;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(binding_value) OR NOT zasp_valid_product_id(target_value) OR reference_value!~'^ref:red-team/[a-z][a-z0-9_-]{7,127}$' OR class_value NOT IN('read_only','test_write') OR version_value NOT BETWEEN 1 AND 1000000 OR octet_length(digest_value)<>32 OR valid_until_value IS NULL OR valid_until_value<=transaction_timestamp() OR valid_until_value>transaction_timestamp()+interval '90 days' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab credential binding rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,target_value,reference_value),0));
 SELECT * INTO STRICT target_row FROM zasp_inventory_entities WHERE (organization_id,workspace_id,environment_id,id,state)=(organization_value,workspace_value,environment_value,target_value,'active') AND fresh_until>transaction_timestamp() AND (zasp_red_team_target_binding_valid(winning_attributes->'red_team','agent_endpoint') OR zasp_red_team_target_binding_valid(winning_attributes->'red_team','mcp_server') OR zasp_red_team_target_binding_valid(winning_attributes->'red_team','coding_agent'));
 IF target_row.winning_attributes->'red_team'->>'credential_reference'<>reference_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab credential target rejected';END IF;
 SELECT * INTO binding_row FROM zasp_attack_lab_credential_bindings WHERE (organization_id,workspace_id,environment_id,binding_id)=(organization_value,workspace_value,environment_value,binding_value) FOR UPDATE;
 IF FOUND THEN
  IF (binding_row.target_id,binding_row.credential_reference,binding_row.credential_class,binding_row.version,binding_row.reference_digest,binding_row.state,binding_row.valid_until)=(target_value,reference_value,class_value,version_value,digest_value,'active',valid_until_value) THEN replayed_value:=true;
  ELSIF binding_row.target_id<>target_value OR binding_row.credential_reference<>reference_value OR version_value<>binding_row.version+1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab credential binding conflict';
  ELSE UPDATE zasp_attack_lab_credential_bindings SET credential_class=class_value,version=version_value,reference_digest=digest_value,state='active',valid_until=valid_until_value,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,binding_id)=(organization_value,workspace_value,environment_value,binding_value) RETURNING * INTO binding_row;
  END IF;
 ELSE
  INSERT INTO zasp_attack_lab_credential_bindings(organization_id,workspace_id,environment_id,binding_id,target_id,credential_reference,credential_class,version,reference_digest,state,valid_until) VALUES(organization_value,workspace_value,environment_value,binding_value,target_value,reference_value,class_value,version_value,digest_value,'active',valid_until_value) RETURNING * INTO binding_row;
 END IF;
 RETURN jsonb_build_object('organization_id',binding_row.organization_id,'workspace_id',binding_row.workspace_id,'environment_id',binding_row.environment_id,'binding_id',binding_row.binding_id,'target_id',binding_row.target_id,'credential_reference',binding_row.credential_reference,'credential_class',binding_row.credential_class,'version',binding_row.version,'reference_digest',encode(binding_row.reference_digest,'hex'),'state',binding_row.state,'valid_until',binding_row.valid_until,'replayed',replayed_value);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='attack lab credential target unavailable';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_register_principals(migration_principal text, controller_principal text, outbox_principal text, proxy_principal text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE principals text[]:=ARRAY[controller_principal,outbox_principal,proxy_principal];authorities text[]:=ARRAY['zasp_attack_lab_controller','zasp_attack_lab_outbox_worker','zasp_attack_lab_proxy'];index_value integer;role_value record;
BEGIN
 IF migration_principal<>session_user OR cardinality(ARRAY(SELECT DISTINCT unnest(ARRAY[migration_principal,controller_principal,outbox_principal,proxy_principal])))<>4 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab principals rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-attack-lab-principal-registration',0));
 FOR index_value IN 1..3 LOOP
  SELECT role_row.oid,role_row.rolcanlogin,role_row.rolsuper,role_row.rolcreatedb,role_row.rolcreaterole,role_row.rolreplication,role_row.rolinherit,role_row.rolbypassrls INTO role_value FROM pg_roles role_row WHERE role_row.rolname=principals[index_value];
  IF NOT FOUND OR NOT role_value.rolcanlogin OR role_value.rolsuper OR role_value.rolcreatedb OR role_value.rolcreaterole OR role_value.rolreplication OR NOT role_value.rolinherit OR role_value.rolbypassrls OR EXISTS(SELECT 1 FROM pg_auth_members membership JOIN pg_roles granted ON granted.oid=membership.roleid WHERE membership.member=role_value.oid AND granted.rolname LIKE 'zasp_%' AND granted.rolname<>authorities[index_value]) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='attack lab principal rejected';END IF;
  EXECUTE format('GRANT %I TO %I',authorities[index_value],principals[index_value]);
  INSERT INTO zasp_attack_lab_principal_bindings(principal_name,authority_role) VALUES(principals[index_value],authorities[index_value]) ON CONFLICT(principal_name) DO UPDATE SET authority_role=excluded.authority_role WHERE zasp_attack_lab_principal_bindings.authority_role=excluded.authority_role;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='attack lab principal conflict';END IF;
 END LOOP;
 RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_attack_lab_rerun(organization_value text, workspace_value text, environment_value text, actor_value text, idempotency_value text, source_value text, expected_version_value bigint, run_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source_row zasp_attack_lab_runs%ROWTYPE;definition_row zasp_red_team_definitions%ROWTYPE;target_row zasp_inventory_entities%ROWTYPE;binding_row zasp_attack_lab_credential_bindings%ROWTYPE;intent_value jsonb;digest_value bytea;receipt_row zasp_attack_lab_request_receipts%ROWTYPE;run_row zasp_attack_lab_runs%ROWTYPE;payload_value jsonb;result_value jsonb;destination_value text;environment_class_value text;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(source_value) OR NOT zasp_valid_product_id(run_value) OR source_value=run_value OR expected_version_value NOT BETWEEN 1 AND 1000000 OR NOT zasp_valid_product_id(correlation_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab rerun rejected';END IF;
 intent_value:=jsonb_build_object('run_id',run_value,'source_attack_lab_run_id',source_value,'expected_version',expected_version_value);digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'rerunAttackLabRun',idempotency_value),0));
 SELECT * INTO receipt_row FROM zasp_attack_lab_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'rerunAttackLabRun',idempotency_value);IF FOUND THEN IF receipt_row.resource_id<>run_value OR receipt_row.expected_version<>expected_version_value OR receipt_row.intent_digest<>digest_value OR receipt_row.expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='attack lab rerun replay rejected';END IF;RETURN receipt_row.result||jsonb_build_object('replayed',true);END IF;
 SELECT * INTO STRICT source_row FROM zasp_attack_lab_runs WHERE (organization_id,workspace_id,environment_id,run_id,version)=(organization_value,workspace_value,environment_value,source_value,expected_version_value) AND state IN('complete','failed','cancelled') FOR UPDATE;
 SELECT * INTO STRICT definition_row FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled,target_id,target_kind)=(organization_value,workspace_value,environment_value,source_row.definition_id,source_row.definition_version,true,source_row.target_id,source_row.target_kind) FOR SHARE;
 SELECT environment_class INTO STRICT environment_class_value FROM zasp_environments WHERE (organization_id,workspace_id,id)=(organization_value,workspace_value,environment_value);
 IF environment_class_value='production' OR environment_class_value<>definition_row.safety->>'environment' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab environment rejected';END IF;
 SELECT * INTO STRICT target_row FROM zasp_inventory_entities WHERE (organization_id,workspace_id,environment_id,id,state)=(organization_value,workspace_value,environment_value,source_row.target_id,'active') AND fresh_until>transaction_timestamp() AND zasp_red_team_target_binding_valid(winning_attributes->'red_team',source_row.target_kind) FOR SHARE;
 SELECT * INTO STRICT binding_row FROM zasp_attack_lab_credential_bindings WHERE (organization_id,workspace_id,environment_id,target_id,credential_reference,credential_class,state)=(organization_value,workspace_value,environment_value,source_row.target_id,target_row.winning_attributes->'red_team'->>'credential_reference',definition_row.safety->>'credential_class','active') AND valid_until>transaction_timestamp() FOR SHARE;
 destination_value:=substring(target_row.winning_attributes->'red_team'->>'endpoint' FROM '^https://([^/]+)/v1/evaluate$');IF destination_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack lab destination rejected';END IF;
 INSERT INTO zasp_attack_lab_runs(organization_id,workspace_id,environment_id,run_id,source_run_id,definition_id,definition_version,target_id,target_kind,environment,credential_class,destination,credential_binding_id,credential_binding_version,credential_binding_digest,requested_by,input_digest)
 VALUES(organization_value,workspace_value,environment_value,run_value,source_row.source_run_id,definition_row.definition_id,definition_row.version,definition_row.target_id,definition_row.target_kind,environment_class_value,binding_row.credential_class,destination_value,binding_row.binding_id,binding_row.version,binding_row.reference_digest,actor_value,digest_value) RETURNING * INTO run_row;
 payload_value:=jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'run_id',run_value,'source_run_id',source_row.source_run_id,'definition_id',source_row.definition_id,'definition_version',source_row.definition_version,'target_id',source_row.target_id,'target_kind',source_row.target_kind,'input_digest',encode(digest_value,'hex'));
