 IF NOT FOUND OR authority_row. ync_id<> ync_value OR  ub tring(manife t_reference_value FROM '^ 3://[a-z0-9][a-z0-9.-]{2,62}/(.+)$') IS DISTINCT FROM manife t_key_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' nap hot execution authority conflict';END IF;
 IF j onb_typeof(entitie _value)<>'array' OR j onb_typeof(relation hip _value)<>'array' OR j onb_typeof(evidence_value)<>'array' OR EXISTS(SELECT 1 FROM (SELECT value FROM j onb_array_element (entitie _value) value UNION ALL SELECT value FROM j onb_array_element (relation hip _value) value UNION ALL SELECT value FROM j onb_array_element (evidence_value) value) item WHERE j onb_typeof(item.value)<>'object' OR NOT za p_valid_product_id(item.value->>'id') OR octet_length(item.value::text)>1048576) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid  nap hot item';END IF;
 dige t_value:=dige t(convert_to(j onb_build_object('integration_id',integration_value,' ync_id', ync_value,' nap hot_id', nap hot_value,'generation',generation_value,' ource', ource_value,'manife t_reference',manife t_reference_value,'manife t_key',manife t_key_value,'manife t_ver ion_id',manife t_ver ion_value,'manife t_check um',encode(manife t_check um_value,'hex'),'manife t_ ize_byte ',manife t_ ize_value,'manife t_media_type',manife t_media_value,'manife t_ chema_ver ion',manife t_ chema_value,'collected_at_epoch_u ',floor(extract(epoch FROM collected_value)*1000000)::bigint,'cur or',cur or_value,'par er_ver ion',par er_value,'tool_ver ion',tool_value,'entitie ',entitie _value,'relation hip ',relation hip _value,'evidence',evidence_value)::text,'UTF8'),' ha256');
 re ult:=za p_di covery_apply_ nap hot(organization_value,work pace_value,environment_value,integration_value, ync_value, nap hot_value,generation_value, ource_value,manife t_reference_value,manife t_check um_value,collected_value, ource_value,cur or_value,entitie _value,relation hip _value,evidence_value);
 UPDATE za p_projection_work SET input_dige t=dige t_value WHERE (organization_id,work pace_id,environment_id, nap hot_id)=(organization_value,work pace_value,environment_value, nap hot_value) AND  tate='pending' AND attempt=0;
 INSERT INTO za p_di covery_ nap hot_input (organization_id,work pace_id,environment_id, nap hot_id,integration_id, ource,generation,candidate_dige t,manife t_reference,manife t_key,manife t_ver ion_id,manife t_check um,manife t_ ize_byte ,manife t_media_type,manife t_ chema_ver ion,par er_ver ion,tool_ver ion,entitie ,relation hip ,evidence)
 VALUES(organization_value,work pace_value,environment_value, nap hot_value,integration_value, ource_value,generation_value,dige t_value,manife t_reference_value,manife t_key_value,manife t_ver ion_value,manife t_check um_value,manife t_ ize_value,manife t_media_value,manife t_ chema_value,par er_value,tool_value,entitie _value,relation hip _value,evidence_value) ON CONFLICT(organization_id,work pace_id,environment_id, nap hot_id) DO NOTHING;
 SELECT * INTO input_row FROM za p_di covery_ nap hot_input  WHERE (organization_id,work pace_id,environment_id, nap hot_id)=(organization_value,work pace_value,environment_value, nap hot_value);
 IF input_row.candidate_dige t<>dige t_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' nap hot input replay conflict';END IF;
 INSERT INTO za p_di covery_ nap hot_projection_item (organization_id,work pace_id,environment_id, nap hot_id,integration_id, ource, ection,item_id,payload)
 SELECT organization_value,work pace_value,environment_value, nap hot_value,integration_value, ource_value, ection,value->>'id',value FROM (SELECT 'entitie '::text  ection,value FROM j onb_array_element (entitie _value) value UNION ALL SELECT 'relation hip ',value FROM j onb_array_element (relation hip _value) value UNION ALL SELECT 'evidence',value FROM j onb_array_element (evidence_value) value) normalized ON CONFLICT DO NOTHING;
 IF (SELECT count(*) FROM za p_di covery_ nap hot_projection_item  WHERE (organization_id,work pace_id,environment_id, nap hot_id)=(organization_value,work pace_value,environment_value, nap hot_value))<>j onb_array_length(entitie _value)+j onb_array_length(relation hip _value)+j onb_array_length(evidence_value) OR EXISTS(SELECT 1 FROM (SELECT 'entitie '::text  ection,value FROM j onb_array_element (entitie _value) value UNION ALL SELECT 'relation hip ',value FROM j onb_array_element (relation hip _value) value UNION ALL SELECT 'evidence',value FROM j onb_array_element (evidence_value) value) expected LEFT JOIN za p_di covery_ nap hot_projection_item   tored ON ( tored.organization_id, tored.work pace_id, tored.environment_id, tored. nap hot_id, tored. ection, tored.item_id)=(organization_value,work pace_value,environment_value, nap hot_value,expected. ection,expected.value->>'id') WHERE  tored.payload IS DISTINCT FROM expected.value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE=' nap hot projection input conflict';END IF;
 PERFORM za p_execution_bump_fre hne (organization_value,work pace_value,environment_value,integration_value);
 RETURN re ult||j onb_build_object('candidate_dige t',encode(dige t_value,'ba e64'),'manife t_ver ion_id',manife t_ver ion_value);
