CREATE OR REPLACE FUNCTION zasp_temporal70.body26(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, lease_token_value text, attempt_value bigint, reservation_value text, input_digest_value bytea, model_value text, cost_policy_value text, cost_unit_value text, maximum_tokens_value bigint, maximum_cost_value bigint)
