CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_freeze_precise_candidates(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, implementation_value text, input_digest_value bytea, index_receipt_value bytea, archive_value bytea)
