CREATE OR REPLACE FUNCTION public.zasp_runtime_gateway_record_event_v27(credential_value text, event_value text, expected_floor_value bigint, next_floor_value bigint, request_digest_value bytea, policy_version_value bigint, decision_value text, action_kind_value text, classification_value jsonb, policy_ids_value jsonb, occurred_value timestamp with time zone)
