DECLARE definition_row public.zasp_security_agent_definitions%ROWTYPE;prior public.zasp_security_agent_trigger_receipts%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
 binding_value jsonb;trigger_value jsonb;created_value boolean:=false;action_value text;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(t) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND v BETWEEN 1 AND 1000000 AND tv>=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test admission rejected';END IF;
 -- The same organization guard used by budget claim precedes all work rows.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR definition_row.body->>'trigger_kind' IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission definition changed';END IF;
 action_value:=definition_row.body->'allowed_actions'->>0;
 binding_value:=zasp_temporal75.binding(o,w,e,d,v);
 IF action_value NOT IN('run_test','rerun_test','start_attack_lab') OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(action_value) OR definition_row.body->>'verification_kind' IS DISTINCT FROM (CASE action_value WHEN 'start_attack_lab' THEN 'attack_lab_run' ELSE 'test_run' END) OR NOT (definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$') OR (definition_row.body->>'max_ai_cost_nano_credits')::bigint NOT BETWEEN 1 AND 1000000000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission configuration changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,action_value);
 trigger_value:=zasp_authorization80_worker.runtime_trigger(o,w,e,d,v,r,k,t,definition_row.body->>'trigger_source',tv);
 SELECT * INTO prior FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_version)=(o,w,e,d,t,(trigger_value->>'version')::bigint) FOR SHARE;
 IF FOUND THEN
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,prior.run_id) FOR SHARE;
  IF NOT FOUND OR run_row.definition_id<>d OR run_row.definition_version<>v OR prior.trigger_kind<>k OR prior.trigger_digest IS DISTINCT FROM decode(trigger_value->>'digest','hex') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test trigger intent conflict';END IF;
 ELSE
  IF zasp_temporal73.active_count(o,w,e,d) >= (definition_row.body->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test concurrency unavailable';END IF;
  -- Every prerequisite lock has completed before this final wall-clock check.
  IF zasp_temporal75.binding(o,w,e,d,v) IS DISTINCT FROM binding_value OR zasp_authorization80_worker.runtime_trigger(o,w,e,d,v,r,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission authority changed';END IF;
  INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d,t,k,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),r);
  INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d,v,t,actor_value,'queued') RETURNING * INTO run_row;

  INSERT INTO zasp_temporal73.admissions VALUES(o,w,e,r,d,v,t,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),'retained_single_action');
  INSERT INTO zasp_temporal73.commands VALUES(o,w,e,r,1,'start');

  INSERT INTO zasp_temporal75.admissions SELECT o,w,e,r,revision FROM zasp_temporal75.configuration ORDER BY revision DESC LIMIT 1;
  created_value:=true;
 END IF;
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
 VALUES(o,w,e,audit_value,correlation_value,run_row.run_id,actor_value,CASE WHEN created_value THEN 'run_queued' ELSE 'run_deduplicated' END,decode(trigger_value->>'digest','hex'),jsonb_build_object('run_id',run_row.run_id,'definition_id',d,'definition_version',v,'trigger_kind',k,'trigger_id',t,'trigger_version',trigger_value->'version','automatic',automatic_value,'action',action_value));
 PERFORM zasp_temporal75.binding(o,w,e,d,v);
 IF zasp_authorization80_worker.runtime_trigger(o,w,e,d,v,r,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired';END IF;
 UPDATE public.zasp_security_agent_execution_state SET used_at=coalesce(used_at,clock_timestamp()) WHERE singleton;
 IF zasp_temporal75.binding(o,w,e,d,v) IS DISTINCT FROM binding_value OR zasp_authorization80_worker.runtime_trigger(o,w,e,d,v,r,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired after final write';END IF;
 RETURN jsonb_build_object('id',run_row.run_id,'agent_id',d,'state',run_row.state,'evidence_ids',jsonb_build_array(t),'definition_version',v,'version',run_row.version,'created',created_value,'replayed',NOT created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.runtime_capture(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a zasp_authorization80_worker.runtime_associations%ROWTYPE;BEGIN
 SELECT * INTO STRICT a FROM zasp_authorization80_worker.runtime_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF a.digest IS DISTINCT FROM encode(digest(convert_to(a.body::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime captured ancestry changed';END IF;
 RETURN a.body||jsonb_build_object('runtime_digest',a.digest);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime captured ancestry absent';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.runtime_occurrence_match(o text, w text, e text, event_value text, b jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE before_value jsonb;after_value jsonb;BEGIN
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal74.current_ready()
 OR b->>'trigger_kind' IS DISTINCT FROM 'runtime_decision' OR b->'trigger_rules'->>'mode' IS DISTINCT FROM 'automatic'
 OR NOT zasp_temporal77.rules_valid(b) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime occurrence contract rejected';END IF;
 -- Callers take the authorization organization lock before any source lock.
 before_value:=zasp_temporal77.source_match(o,w,e,event_value,b,clock_timestamp());
 IF before_value IS NULL THEN
  IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime occurrence catalog changed';END IF;
  RETURN NULL;
 END IF;
 IF before_value->>'kind'<>'runtime_decision' OR jsonb_array_length(before_value#>'{evidence,events}') NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime occurrence evidence changed';END IF;
 PERFORM 1 FROM public.zasp_gateway_devices d WHERE(d.organization_id,d.workspace_id,d.environment_id)=(o,w,e)
 AND d.id IN(SELECT x->>'device_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,device_id}') ORDER BY d.id FOR SHARE;
 PERFORM 1 FROM public.zasp_gateway_credentials c JOIN public.zasp_runtime_gateway_events v
 ON(v.organization_id,v.workspace_id,v.environment_id,v.device_id,v.credential_id)=(c.organization_id,c.workspace_id,c.environment_id,c.device_id,c.id)
 WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e)
 AND v.event_id IN(SELECT x->>'event_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,event_id}')
 ORDER BY c.device_id,c.id FOR SHARE OF c;
 PERFORM 1 FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e)
 AND v.event_id IN(SELECT x->>'event_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,event_id}') ORDER BY v.event_id FOR SHARE;
 PERFORM 1 FROM zasp_temporal77.runtime_evaluations a WHERE(a.organization_id,a.workspace_id,a.environment_id)=(o,w,e)
 AND a.event_id IN(SELECT x->>'event_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,event_id}') ORDER BY a.event_id FOR SHARE;
 after_value:=zasp_temporal77.source_match(o,w,e,event_value,b,clock_timestamp());
 IF after_value IS DISTINCT FROM before_value OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal74.current_ready()
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime occurrence changed under lock';END IF;
 RETURN after_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.runtime_occurrence_match_inner(o text, w text, e text, event_value text, b jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE before_value jsonb;after_value jsonb;BEGIN
 IF b->>'trigger_kind' IS DISTINCT FROM 'runtime_decision' OR b->'trigger_rules'->>'mode' IS DISTINCT FROM 'automatic'
 OR NOT zasp_temporal77.rules_valid(b) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime occurrence contract rejected';END IF;
 -- Callers take the authorization organization lock before any source lock.
 before_value:=zasp_temporal77.source_match(o,w,e,event_value,b,clock_timestamp());
 IF before_value IS NULL THEN

  RETURN NULL;
 END IF;
 IF before_value->>'kind'<>'runtime_decision' OR jsonb_array_length(before_value#>'{evidence,events}') NOT BETWEEN 1 AND 100
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime occurrence evidence changed';END IF;
 PERFORM 1 FROM public.zasp_gateway_devices d WHERE(d.organization_id,d.workspace_id,d.environment_id)=(o,w,e)
 AND d.id IN(SELECT x->>'device_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,device_id}') ORDER BY d.id FOR SHARE;
 PERFORM 1 FROM public.zasp_gateway_credentials c JOIN public.zasp_runtime_gateway_events v
 ON(v.organization_id,v.workspace_id,v.environment_id,v.device_id,v.credential_id)=(c.organization_id,c.workspace_id,c.environment_id,c.device_id,c.id)
 WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e)
 AND v.event_id IN(SELECT x->>'event_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,event_id}')
 ORDER BY c.device_id,c.id FOR SHARE OF c;
 PERFORM 1 FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e)
 AND v.event_id IN(SELECT x->>'event_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,event_id}') ORDER BY v.event_id FOR SHARE;
 PERFORM 1 FROM zasp_temporal77.runtime_evaluations a WHERE(a.organization_id,a.workspace_id,a.environment_id)=(o,w,e)
 AND a.event_id IN(SELECT x->>'event_id' FROM jsonb_array_elements(before_value#>'{evidence,events}') x UNION SELECT before_value#>>'{evidence,anchor,event_id}') ORDER BY a.event_id FOR SHARE;
 after_value:=zasp_temporal77.source_match(o,w,e,event_value,b,clock_timestamp());
 IF after_value IS DISTINCT FROM before_value
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime occurrence changed under lock';END IF;
 RETURN after_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.runtime_source(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;t public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;
 a zasp_temporal77.occurrences%ROWTYPE;summary public.zasp_runtime_session_summaries%ROWTYPE;agent public.zasp_inventory_entities%ROWTYPE;
 event_value public.zasp_runtime_gateway_events%ROWTYPE;credential public.zasp_gateway_credentials%ROWTYPE;device public.zasp_gateway_devices%ROWTYPE;
 protocol text;session_value text;agent_value text;ids text[];device_ids text[];item text;native_value jsonb;matched jsonb;events_value jsonb:='[]'::jsonb;body_value jsonb;
 expiry timestamptz;window_seconds integer;event_digest text;credential_digest text;device_digest text;
BEGIN
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime ancestry unavailable';END IF;
 SELECT * INTO STRICT x FROM zasp_temporal74.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO STRICT t FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 SELECT * INTO STRICT h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,x.definition_id,x.definition_version) FOR SHARE;
 IF t.trigger_kind<>'runtime_decision' OR(x.trigger_id,x.trigger_version,x.input_digest) IS DISTINCT FROM(t.trigger_id,t.trigger_version,encode(t.trigger_digest,'hex'))
 OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime original ownership changed';END IF;
 native_value:=zasp_authorization80_worker.runtime_trigger_inner(o,w,e,x.definition_id,x.definition_version,r,t.trigger_kind,t.trigger_id,h.definition->>'trigger_source',t.trigger_version);
 IF native_value->>'digest' IS DISTINCT FROM x.input_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime trigger proof changed';END IF;
 IF h.definition->'trigger_rules'->>'mode'='automatic' THEN
  protocol:='configured77-event-occurrence';
  SELECT * INTO STRICT a FROM zasp_temporal77.occurrences WHERE(organization_id,workspace_id,environment_id,definition_id,definition_version,run_id,disposition)=(o,w,e,x.definition_id,x.definition_version,r,'admitted') FOR SHARE;
  matched:=zasp_authorization80_worker.runtime_occurrence_match_inner(o,w,e,a.event_id,h.definition);
  IF matched IS NULL OR matched->'evidence' IS DISTINCT FROM a.snapshot OR decode(matched->>'digest','hex') IS DISTINCT FROM a.snapshot_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime occurrence ancestry changed';END IF;
  session_value:=a.snapshot#>>'{anchor,evaluation,session_id}';agent_value:=a.snapshot#>>'{anchor,evaluation,agent_id}';
  window_seconds:=(h.definition#>>'{trigger_rules,runtime,window_seconds}')::integer;
  SELECT array_agg(id ORDER BY id) INTO ids FROM(SELECT DISTINCT value->>'event_id' id FROM jsonb_array_elements(a.snapshot->'events') UNION SELECT a.snapshot#>>'{anchor,event_id}') selected;
  IF cardinality(ids) NOT BETWEEN 1 AND 101 OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.snapshot->'events') v WHERE(v#>>'{evaluation,session_id}',v#>>'{evaluation,agent_id}') IS DISTINCT FROM(session_value,agent_value)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime configured ancestry ambiguous';END IF;
 ELSE
  protocol:='retained74-session-latest';session_value:=t.trigger_id;window_seconds:=300;
  SELECT event.* INTO STRICT event_value FROM public.zasp_runtime_gateway_events event
  WHERE(event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.decision,event.classification->>'outcome')=(o,w,e,t.trigger_id,'block',h.definition->>'trigger_source')
   AND event.occurred_at<=clock_timestamp() ORDER BY event.occurred_at DESC,event.sequence DESC,event.event_id DESC LIMIT 1 FOR SHARE;
  IF event_value.sequence<>t.trigger_version OR encode(digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',t.trigger_id,'device_id',event_value.device_id,'event_id',event_value.event_id,'sequence',event_value.sequence,'request_digest','sha256:'||encode(event_value.request_digest,'hex'))::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM x.input_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime retained ancestry changed';END IF;
  ids:=ARRAY[event_value.event_id];
 END IF;
 SELECT * INTO STRICT summary FROM public.zasp_runtime_session_summaries WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,session_value) FOR SHARE;
 IF summary.id='unattributed' OR summary.minimum_agent_id IS NULL OR summary.minimum_agent_id IS DISTINCT FROM summary.maximum_agent_id
 OR summary.probable_count<>0 OR summary.unattributed_count<>0 OR agent_value IS NOT NULL AND agent_value IS DISTINCT FROM summary.minimum_agent_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session attribution unavailable';END IF;
 agent_value:=summary.minimum_agent_id;
 SELECT * INTO STRICT agent FROM public.zasp_inventory_entities WHERE(organization_id,workspace_id,environment_id,id,product_kind,state)=(o,w,e,agent_value,'agent','active') FOR SHARE;
 IF agent.fresh_until IS NULL OR agent.fresh_until<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source agent expired';END IF;
 expiry:=agent.fresh_until;
 -- Identity ordering is deterministic. All supported source writers acquire
 -- the organization lock before their first device or source-row lock.
 PERFORM 1 FROM public.zasp_gateway_devices d WHERE(d.organization_id,d.workspace_id,d.environment_id)=(o,w,e) AND d.id IN(SELECT v.device_id FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e) AND v.event_id=ANY(ids)) ORDER BY d.id FOR SHARE;
 PERFORM 1 FROM public.zasp_gateway_credentials c WHERE(c.organization_id,c.workspace_id,c.environment_id)=(o,w,e) AND c.id IN(SELECT v.credential_id FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e) AND v.event_id=ANY(ids)) ORDER BY c.device_id,c.id FOR SHARE;
 FOREACH item IN ARRAY ids LOOP
  SELECT * INTO STRICT event_value FROM public.zasp_runtime_gateway_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,item) FOR SHARE;
  SELECT * INTO STRICT device FROM public.zasp_gateway_devices WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,event_value.device_id);
  SELECT * INTO STRICT credential FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id,id)=(o,w,e,event_value.device_id,event_value.credential_id);
  IF device.state<>'active' OR credential.revoked_at IS NOT NULL OR credential.expires_at<=clock_timestamp() OR event_value.occurred_at>clock_timestamp()
   OR event_value.occurred_at+make_interval(secs=>window_seconds)<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source authority expired';END IF;
  -- Full event and credential bodies are hashed privately; no endpoint, key
  -- reference, classification or evaluation body leaves this metadata reader.
  event_digest:=encode(digest(convert_to(to_jsonb(event_value)::text,'UTF8'),'sha256'),'hex');
  credential_digest:=encode(digest(convert_to(to_jsonb(credential)::text,'UTF8'),'sha256'),'hex');
  device_digest:=encode(digest(convert_to(jsonb_build_array(o,w,e,device.id,device.state,device.revoked_at)::text,'UTF8'),'sha256'),'hex');
  events_value:=events_value||jsonb_build_array(jsonb_build_object('event_id',item,'sequence',event_value.sequence,'event_digest',event_digest,'device_id',device.id,'device_digest',device_digest,'credential_id',credential.id,'credential_digest',credential_digest));
  device_ids:=array_append(device_ids,device.id);
  expiry:=least(expiry,credential.expires_at,event_value.occurred_at+make_interval(secs=>window_seconds));
 END LOOP;
 SELECT array_agg(id ORDER BY id) INTO device_ids FROM(SELECT DISTINCT unnest(device_ids) id) d;
 IF cardinality(device_ids) NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime source device count rejected';END IF;
 IF zasp_authorization80_worker.runtime_trigger_inner(o,w,e,x.definition_id,x.definition_version,r,t.trigger_kind,t.trigger_id,h.definition->>'trigger_source',t.trigger_version) IS DISTINCT FROM native_value
 OR expiry<=clock_timestamp() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime ancestry changed after locks';END IF;
 body_value:=jsonb_build_object('runtime_protocol',protocol,'source_session_id',session_value,'source_agent_id',agent_value,'source_device_ids',to_jsonb(device_ids),
 'match',CASE WHEN protocol='configured77-event-occurrence' THEN h.definition#>'{trigger_rules,runtime}' ELSE jsonb_build_object('outcome',h.definition->>'trigger_source') END,
 'definition_digest',encode(h.definition_digest,'hex'),'trigger_digest',x.input_digest,'source_events',events_value,
 'session_digest',encode(digest(convert_to(to_jsonb(summary)::text,'UTF8'),'sha256'),'hex'),'source_agent_digest',encode(digest(convert_to(to_jsonb(agent)::text,'UTF8'),'sha256'),'hex'),
 'fresh_until_ms',floor(extract(epoch FROM expiry)*1000)::bigint);
 RETURN body_value||jsonb_build_object('runtime_digest',encode(digest(convert_to(body_value::text,'UTF8'),'sha256'),'hex'));
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source ancestry unavailable';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.runtime_source_after_entry(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;t public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;
 a zasp_temporal77.occurrences%ROWTYPE;summary public.zasp_runtime_session_summaries%ROWTYPE;agent public.zasp_inventory_entities%ROWTYPE;
 event_value public.zasp_runtime_gateway_events%ROWTYPE;credential public.zasp_gateway_credentials%ROWTYPE;device public.zasp_gateway_devices%ROWTYPE;
 protocol text;session_value text;agent_value text;ids text[];device_ids text[];item text;native_value jsonb;matched jsonb;events_value jsonb:='[]'::jsonb;body_value jsonb;
 expiry timestamptz;window_seconds integer;event_digest text;credential_digest text;device_digest text;
BEGIN

 SELECT * INTO STRICT x FROM zasp_temporal74.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO STRICT t FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 SELECT * INTO STRICT h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,x.definition_id,x.definition_version) FOR SHARE;
 IF t.trigger_kind<>'runtime_decision' OR(x.trigger_id,x.trigger_version,x.input_digest) IS DISTINCT FROM(t.trigger_id,t.trigger_version,encode(t.trigger_digest,'hex'))
 OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime original ownership changed';END IF;
 native_value:=zasp_authorization80_worker.runtime_trigger_inner(o,w,e,x.definition_id,x.definition_version,r,t.trigger_kind,t.trigger_id,h.definition->>'trigger_source',t.trigger_version);
 IF native_value->>'digest' IS DISTINCT FROM x.input_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime trigger proof changed';END IF;
 IF h.definition->'trigger_rules'->>'mode'='automatic' THEN
  protocol:='configured77-event-occurrence';
  SELECT * INTO STRICT a FROM zasp_temporal77.occurrences WHERE(organization_id,workspace_id,environment_id,definition_id,definition_version,run_id,disposition)=(o,w,e,x.definition_id,x.definition_version,r,'admitted') FOR SHARE;
  matched:=zasp_authorization80_worker.runtime_occurrence_match_inner(o,w,e,a.event_id,h.definition);
  IF matched IS NULL OR matched->'evidence' IS DISTINCT FROM a.snapshot OR decode(matched->>'digest','hex') IS DISTINCT FROM a.snapshot_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime occurrence ancestry changed';END IF;
  session_value:=a.snapshot#>>'{anchor,evaluation,session_id}';agent_value:=a.snapshot#>>'{anchor,evaluation,agent_id}';
  window_seconds:=(h.definition#>>'{trigger_rules,runtime,window_seconds}')::integer;
  SELECT array_agg(id ORDER BY id) INTO ids FROM(SELECT DISTINCT value->>'event_id' id FROM jsonb_array_elements(a.snapshot->'events') UNION SELECT a.snapshot#>>'{anchor,event_id}') selected;
  IF cardinality(ids) NOT BETWEEN 1 AND 101 OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.snapshot->'events') v WHERE(v#>>'{evaluation,session_id}',v#>>'{evaluation,agent_id}') IS DISTINCT FROM(session_value,agent_value)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime configured ancestry ambiguous';END IF;
 ELSE
  protocol:='retained74-session-latest';session_value:=t.trigger_id;window_seconds:=300;
  SELECT event.* INTO STRICT event_value FROM public.zasp_runtime_gateway_events event
  WHERE(event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.decision,event.classification->>'outcome')=(o,w,e,t.trigger_id,'block',h.definition->>'trigger_source')
   AND event.occurred_at<=clock_timestamp() ORDER BY event.occurred_at DESC,event.sequence DESC,event.event_id DESC LIMIT 1 FOR SHARE;
  IF event_value.sequence<>t.trigger_version OR encode(digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',t.trigger_id,'device_id',event_value.device_id,'event_id',event_value.event_id,'sequence',event_value.sequence,'request_digest','sha256:'||encode(event_value.request_digest,'hex'))::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM x.input_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime retained ancestry changed';END IF;
  ids:=ARRAY[event_value.event_id];
 END IF;
 SELECT * INTO STRICT summary FROM public.zasp_runtime_session_summaries WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,session_value) FOR SHARE;
 IF summary.id='unattributed' OR summary.minimum_agent_id IS NULL OR summary.minimum_agent_id IS DISTINCT FROM summary.maximum_agent_id
 OR summary.probable_count<>0 OR summary.unattributed_count<>0 OR agent_value IS NOT NULL AND agent_value IS DISTINCT FROM summary.minimum_agent_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session attribution unavailable';END IF;
 agent_value:=summary.minimum_agent_id;
 SELECT * INTO STRICT agent FROM public.zasp_inventory_entities WHERE(organization_id,workspace_id,environment_id,id,product_kind,state)=(o,w,e,agent_value,'agent','active') FOR SHARE;
 IF agent.fresh_until IS NULL OR agent.fresh_until<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source agent expired';END IF;
 expiry:=agent.fresh_until;
 -- Identity ordering is deterministic. All supported source writers acquire
 -- the organization lock before their first device or source-row lock.
 PERFORM 1 FROM public.zasp_gateway_devices d WHERE(d.organization_id,d.workspace_id,d.environment_id)=(o,w,e) AND d.id IN(SELECT v.device_id FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e) AND v.event_id=ANY(ids)) ORDER BY d.id FOR SHARE;
 PERFORM 1 FROM public.zasp_gateway_credentials c WHERE(c.organization_id,c.workspace_id,c.environment_id)=(o,w,e) AND c.id IN(SELECT v.credential_id FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e) AND v.event_id=ANY(ids)) ORDER BY c.device_id,c.id FOR SHARE;
 FOREACH item IN ARRAY ids LOOP
  SELECT * INTO STRICT event_value FROM public.zasp_runtime_gateway_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,item) FOR SHARE;
  SELECT * INTO STRICT device FROM public.zasp_gateway_devices WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,event_value.device_id);
  SELECT * INTO STRICT credential FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id,id)=(o,w,e,event_value.device_id,event_value.credential_id);
  IF device.state<>'active' OR credential.revoked_at IS NOT NULL OR credential.expires_at<=clock_timestamp() OR event_value.occurred_at>clock_timestamp()
   OR event_value.occurred_at+make_interval(secs=>window_seconds)<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source authority expired';END IF;
  -- Full event and credential bodies are hashed privately; no endpoint, key
  -- reference, classification or evaluation body leaves this metadata reader.
  event_digest:=encode(digest(convert_to(to_jsonb(event_value)::text,'UTF8'),'sha256'),'hex');
  credential_digest:=encode(digest(convert_to(to_jsonb(credential)::text,'UTF8'),'sha256'),'hex');
  device_digest:=encode(digest(convert_to(jsonb_build_array(o,w,e,device.id,device.state,device.revoked_at)::text,'UTF8'),'sha256'),'hex');
  events_value:=events_value||jsonb_build_array(jsonb_build_object('event_id',item,'sequence',event_value.sequence,'event_digest',event_digest,'device_id',device.id,'device_digest',device_digest,'credential_id',credential.id,'credential_digest',credential_digest));
  device_ids:=array_append(device_ids,device.id);
  expiry:=least(expiry,credential.expires_at,event_value.occurred_at+make_interval(secs=>window_seconds));
 END LOOP;
 SELECT array_agg(id ORDER BY id) INTO device_ids FROM(SELECT DISTINCT unnest(device_ids) id) d;
 IF cardinality(device_ids) NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime source device count rejected';END IF;
 IF zasp_authorization80_worker.runtime_trigger_inner(o,w,e,x.definition_id,x.definition_version,r,t.trigger_kind,t.trigger_id,h.definition->>'trigger_source',t.trigger_version) IS DISTINCT FROM native_value
 OR expiry<=clock_timestamp() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime ancestry changed after locks';END IF;
 body_value:=jsonb_build_object('runtime_protocol',protocol,'source_session_id',session_value,'source_agent_id',agent_value,'source_device_ids',to_jsonb(device_ids),
 'match',CASE WHEN protocol='configured77-event-occurrence' THEN h.definition#>'{trigger_rules,runtime}' ELSE jsonb_build_object('outcome',h.definition->>'trigger_source') END,
 'definition_digest',encode(h.definition_digest,'hex'),'trigger_digest',x.input_digest,'source_events',events_value,
 'session_digest',encode(digest(convert_to(to_jsonb(summary)::text,'UTF8'),'sha256'),'hex'),'source_agent_digest',encode(digest(convert_to(to_jsonb(agent)::text,'UTF8'),'sha256'),'hex'),
 'fresh_until_ms',floor(extract(epoch FROM expiry)*1000)::bigint);
 RETURN body_value||jsonb_build_object('runtime_digest',encode(digest(convert_to(body_value::text,'UTF8'),'sha256'),'hex'));
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source ancestry unavailable';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.runtime_trigger(o text, w text, e text, d text, v bigint, r text, k text, t text, s text, tv bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_temporal77.occurrences%ROWTYPE;source_value zasp_temporal77.source_events%ROWTYPE;matched jsonb;BEGIN
 SELECT * INTO STRICT h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) FOR SHARE;
 IF h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime historical definition changed';END IF;
 IF h.definition->>'trigger_kind'<>'runtime_decision' OR h.definition->'trigger_rules'->>'mode' IS DISTINCT FROM 'automatic' THEN
  RETURN public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,s,tv);
 END IF;
 -- A configured source never falls back to session/latest-event semantics.
 IF k<>'runtime_decision' OR h.definition->>'trigger_source' IS DISTINCT FROM s
 OR h.definition->'allowed_actions' NOT IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='configured runtime identity rejected';END IF;
 SELECT occurrence.* INTO STRICT a FROM zasp_temporal77.occurrences occurrence JOIN zasp_temporal77.source_events src USING(organization_id,workspace_id,environment_id,event_id)
 WHERE(occurrence.organization_id,occurrence.workspace_id,occurrence.environment_id,occurrence.definition_id,occurrence.definition_version,occurrence.run_id,occurrence.disposition,src.source_kind,src.source_id,src.source_version)=(o,w,e,d,v,r,'admitted',k,t,tv) FOR SHARE OF occurrence,src;
 SELECT * INTO STRICT source_value FROM zasp_temporal77.source_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,a.event_id);
 IF a.definition_digest IS DISTINCT FROM h.definition_digest OR a.snapshot_digest IS DISTINCT FROM digest(convert_to(a.snapshot::text,'UTF8'),'sha256')
 OR r IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',concat_ws(chr(31),d,v,k,t,tv))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='configured runtime capture changed';END IF;
 matched:=zasp_authorization80_worker.runtime_occurrence_match(o,w,e,a.event_id,h.definition);
 IF matched IS NULL OR matched->'evidence' IS DISTINCT FROM a.snapshot OR decode(matched->>'digest','hex') IS DISTINCT FROM a.snapshot_digest
 OR(matched->>'trigger_id',(matched->>'version')::bigint) IS DISTINCT FROM(t,tv)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='configured runtime source changed';END IF;
 RETURN jsonb_build_object('version',tv,'digest',encode(a.snapshot_digest,'hex'));
EXCEPTION WHEN no_data_found OR too_many_rows THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='configured runtime provenance missing';
END $function$

