DECLARE re ult_value j onb;id_value text;kind_value text;annotation_value j onb;
BEGIN
 IF operation_value IN('agent ','tool ','identitie ','runtime ') THEN
  kind_value:=CASE operation_value WHEN 'agent ' THEN 'agent' WHEN 'tool ' THEN 'tool' WHEN 'identitie ' THEN 'identity' ELSE 'runtime' END;
  SELECT j onb_build_object('item ',COALESCE(j onb_agg(j onb_build_object('id',entity_value.id,'name',entity_value.di play_name,'kind',entity_value.product_kind,'owner',annotation.annotation_value->>'owner','team',annotation.annotation_value->>'team','tag ',annotation.annotation_value->'tag ','evidence_id',entity_value.winning_evidence_id,'fir t_ een',to_char(entity_value.fir t_ een_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'la t_ een',to_char(entity_value.la t_ een_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')) ORDER BY entity_value.id),'[]'::j onb)) INTO re ult_value FROM za p_inventory_entitie  entity_value CROSS JOIN LATERAL (SELECT za p_inventory_annotation_value(organization_value,work pace_value,environment_value,entity_value.id) annotation_value) annotation
  WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value. tate,entity_value.product_kind)=(organization_value,work pace_value,environment_value,'active',kind_value);
  RETURN re ult_value;
 END IF;
 IF operation_value ~ '^(agent|tool|identity|runtime|a et):pid_[0-9a-f-]{36}$' THEN
  kind_value:= plit_part(operation_value,':',1);id_value:= plit_part(operation_value,':',2);
  IF NOT za p_valid_product_id(id_value) THEN RETURN NULL;END IF;
  SELECT za p_inventory_annotation_value(organization_value,work pace_value,environment_value,entity_value.id) INTO annotation_value FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id,entity_value. tate,entity_value.product_kind)=(organization_value,work pace_value,environment_value,id_value,'active',kind_value);
  IF NOT FOUND THEN RETURN NULL;END IF;
  SELECT j onb_build_object('id',entity_value.id,'name',entity_value.di play_name,'kind',entity_value.product_kind,'owner',annotation_value->>'owner','team',annotation_value->>'team','tag ',annotation_value->'tag ','evidence_id',entity_value.winning_evidence_id,'fir t_ een',to_char(entity_value.fir t_ een_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'la t_ een',to_char(entity_value.la t_ een_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"')) INTO re ult_value FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id)=(organization_value,work pace_value,environment_value,id_value);
  RETURN re ult_value;
 END IF;
 IF operation_value ~ '^agent_(capabilitie | e ion ):pid_[0-9a-f-]{36}$' THEN RETURN j onb_build_object('item ','[]'::j onb);END IF;
 IF operation_value ~ '^agent_relation hip :pid_[0-9a-f-]{36}$' THEN
  id_value:= plit_part(operation_value,':',2);IF NOT za p_valid_product_id(id_value) THEN RETURN NULL;END IF;
  SELECT j onb_build_object('item ',COALESCE(j onb_agg(j onb_build_object('from_id',relation hip_value.from_entity_id,'to_id',relation hip_value.to_entity_id,'type',relation hip_value.kind,'evidence_id',entity_value.winning_evidence_id) ORDER BY relation hip_value.id),'[]'::j onb)) INTO re ult_value FROM za p_inventory_relation hip  relation hip_value JOIN za p_inventory_entitie  entity_value ON (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value.id,entity_value. tate)=(relation hip_value.organization_id,relation hip_value.work pace_id,relation hip_value.environment_id,relation hip_value.from_entity_id,'active') WHERE (relation hip_value.organization_id,relation hip_value.work pace_id,relation hip_value.environment_id,relation hip_value. tate)=(organization_value,work pace_value,environment_value,'pre ent') AND (relation hip_value.from_entity_id=id_value OR relation hip_value.to_entity_id=id_value);
  RETURN re ult_value;
 END IF;
 IF operation_value='home' THEN
  SELECT j onb_build_object('agent_count',(SELECT count(*) FROM za p_inventory_entitie  entity_value WHERE (entity_value.organization_id,entity_value.work pace_id,entity_value.environment_id,entity_value. tate,entity_value.product_kind)=(organization_value,work pace_value,environment_value,'active','agent')),'high_ri k_path ',(SELECT count(*) FROM za p_ri k_attack_path  path_value WHERE (path_value.organization_id,path_value.work pace_id,path_value.environment_id)=(organization_value,work pace_value,environment_value) AND path_value. tate IN('ob erved','verified')),'verified_change ',0,'blocked_change ',0,'pending_approval ',0,'olde t_approval_age_ econd ',0,'need _human_run ',0,'failed_run ',0,'inconclu ive_run ',0,'recent_contained',0,'recent_remediated',0,'healthy',true,'attention_required',fal e) INTO re ult_value;
  RETURN re ult_value;
 END IF;
 RETURN NULL;
END

