     WHEN 'aw ' THEN  ubject. ubject_kind='aw _account' AND  ubject. ubject_id= ub tring(integration.configuration->>'role_arn' FROM '^arn:aw :iam::([0-9]{12}):role/')
     WHEN 'github' THEN  ubject. ubject_kind='github_in tallation' AND EXISTS(SELECT 1 FROM za p_connector_credential  credential WHERE (credential.organization_id,credential.work pace_id,credential.environment_id,credential.integration_id,credential.provider,credential.credential_reference)=(connection.organization_id,connection.work pace_id,connection.environment_id,connection.integration_id,'github',connection.connection_reference) AND credential. tatu ='active' AND credential.metadata->>'in tallation_id'= ubject. ubject_id)
     WHEN 'okta' THEN  ubject. ubject_kind='okta_tenant' AND EXISTS(SELECT 1 FROM za p_connector_credential  credential WHERE (credential.organization_id,credential.work pace_id,credential.environment_id,credential.integration_id,credential.provider,credential.credential_reference)=(connection.organization_id,connection.work pace_id,connection.environment_id,connection.integration_id,'okta',connection.connection_reference) AND credential. tatu ='active' AND credential.metadata->>'tenant'= ubject. ubject_id)
