BEGIN
 IF outcome NOT IN(' ucceeded','retryable','failed','cancelled') OR retry_after_ econd  NOT BETWEEN 0 AND 3600 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid job outcome';END IF;
 reque ted:=dige t(convert_to(concat_w (chr(31),$4,$5,$6,$7,COALESCE(encode($8,'hex'),''),COALESCE($9,''),$10::text),'UTF8'),' ha256');
