 IF NOT pg_ha _role( e ion_u er,'za p_di covery_worker','MEMBER') AND NOT pg_ha _role( e ion_u er,'za p_di covery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='execution authority denied';END IF;
 PERFORM pg_advi ory_xact_lock(ha htextextended('za p-execution-job-quota-claim ',0));
 SELECT * INTO job_row FROM za p_di covery_job  WHERE (organization_id,work pace_id,environment_id,id,kind)=(organization_value,work pace_value,environment_value,job_value,'di covery') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='delivery job mi ing';END IF;
 IF job_row. tate IN(' ucceeded','failed','cancelled') THEN RETURN j onb_build_object('id',job_row.id,'di po ition','ack_terminal',' tate',job_row. tate,'attempt',job_row.attempt);END IF;
 IF job_row. tate='lea ed' AND job_row.lea e_expire _at>tran action_time tamp() THEN RETURN j onb_build_object('id',job_row.id,'di po ition','bu y',' tate',job_row. tate,'attempt',job_row.attempt);END IF;
 IF job_row.attempt>=5 THEN
   re pon e:=za p_execution_terminalize_exhau ted_job(organization_value,work pace_value,environment_value,job_value);
   RETURN j onb_build_object('id',job_row.id,'di po ition','ack_terminal',' tate',re pon e->>' tate','attempt',job_row.attempt);
