 WITH organization  AS (SELECT projection.organization_id,min(projection. nap hot_id) fir t_ nap hot FROM za p_projection_work projection WHERE projection.kind=kind_value AND projection.attempt<5 AND projection.available_at<=tran action_time tamp() AND (projection. tate IN('pending','retryable') OR projection. tate='lea ed' AND projection.lea e_expire _at<=tran action_time tamp()) AND EXISTS(SELECT 1 FROM za p_di covery_ nap hot_input  input WHERE (input.organization_id,input.work pace_id,input.environment_id,input. nap hot_id)=(projection.organization_id,projection.work pace_id,projection.environment_id,projection. nap hot_id)) GROUP BY projection.organization_id ORDER BY fir t_ nap hot,projection.organization_id LIMIT claim_limit),
