END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_sensor_heartbeat(locator_value bytea, secret_value bytea, audience_value text, sequence_value bigint, status_value text, capabilities_value jsonb, kernel_value text, btf_value boolean, event_rate_value bigint, drops_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;sensor_value text;metadata_value jsonb;request_digest_value bytea;prior_digest bytea;prior_sequence bigint;observed_value timestamptz;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 IF sequence_value<0 OR status_value NOT IN('healthy','degraded') OR jsonb_typeof(capabilities_value)<>'array' OR jsonb_array_length(capabilities_value) NOT BETWEEN 1 AND 32
  OR length(kernel_value) NOT BETWEEN 1 AND 128 OR kernel_value<>btrim(kernel_value) OR kernel_value ~ '[[:cntrl:]]' OR event_rate_value NOT BETWEEN 0 AND 1000000000 OR drops_value NOT BETWEEN 0 AND 1000000000
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(capabilities_value) item WHERE jsonb_typeof(item)<>'string' OR item#>>'{}' !~ '^[a-z0-9][a-z0-9_.-]{0,95}$')
  OR (SELECT count(*) FROM jsonb_array_elements_text(capabilities_value))<>(SELECT count(DISTINCT item) FROM jsonb_array_elements_text(capabilities_value) item)
  OR capabilities_value<>(SELECT jsonb_agg(item ORDER BY item) FROM jsonb_array_elements_text(capabilities_value) item)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor heartbeat rejected';END IF;
 authority_value:=zasp_authorization80_runtime.inner_authenticate_sensor(locator_value,secret_value,audience_value);
 organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';sensor_value:=authority_value->>'sensor_id';
 metadata_value:=jsonb_build_object('capabilities',capabilities_value,'kernel',kernel_value,'btf',btf_value,'event_rate',event_rate_value,'drops',drops_value,'schema_version','sensor-heartbeat-v1');
 request_digest_value:=digest(convert_to(jsonb_build_object('sensor_id',sensor_value,'sequence',sequence_value,'status',status_value,'dropped_events',drops_value,'metadata',metadata_value)::text,'UTF8'),'sha256');
 SELECT heartbeat.request_digest,heartbeat.sequence,heartbeat.observed_at INTO prior_digest,prior_sequence,observed_value FROM zasp_sensor_heartbeats heartbeat WHERE (heartbeat.organization_id,heartbeat.workspace_id,heartbeat.environment_id,heartbeat.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value);
 IF FOUND AND prior_sequence=sequence_value THEN IF prior_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='sensor heartbeat conflict';END IF; PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('sensor_id',sensor_value,'sequence',sequence_value,'observed_at',observed_value);ELSIF FOUND AND prior_sequence>sequence_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='sensor heartbeat conflict';END IF;
 INSERT INTO zasp_sensor_heartbeats(organization_id,workspace_id,environment_id,sensor_id,sequence,request_digest,status,dropped_events,metadata)
 VALUES(organization_value,workspace_value,environment_value,sensor_value,sequence_value,request_digest_value,status_value,drops_value,metadata_value)
 ON CONFLICT(organization_id,workspace_id,environment_id,sensor_id) DO UPDATE SET sequence=excluded.sequence,request_digest=excluded.request_digest,status=excluded.status,dropped_events=excluded.dropped_events,metadata=excluded.metadata,observed_at=transaction_timestamp() RETURNING observed_at INTO observed_value;
 UPDATE zasp_sensors sensor_row SET state=CASE WHEN status_value='healthy' THEN 'active' ELSE 'degraded' END,updated_at=transaction_timestamp() WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)=(organization_value,workspace_value,environment_value,sensor_value) AND sensor_row.state IN('pending','active','degraded');
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('sensor_id',sensor_value,'sequence',sequence_value,'observed_at',observed_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_execution_record_public_mutation(organization_value text, workspace_value text, environment_value text, principal_value text, operation_value text, idempotency_value text, intent_value jsonb, body_value jsonb, resource_kind_value text, resource_value text, version_value bigint, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;
BEGIN
 IF operation_value NOT IN('syncIntegration','putIntegrationSchedule','deleteIntegrationSchedule') OR resource_kind_value NOT IN('integration_sync','integration_schedule')
    OR NOT zasp_valid_product_id(principal_value) OR NOT zasp_valid_product_id(resource_value) OR NOT zasp_valid_product_id(audit_value)
    OR NOT zasp_valid_product_id(correlation_value) OR (receipt_value<>'' AND NOT zasp_valid_product_id(receipt_value)) OR length(idempotency_value) NOT BETWEEN 16 AND 128
    OR jsonb_typeof(intent_value)<>'object' OR jsonb_typeof(body_value)<>'object' OR version_value<1 THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid public execution mutation';
 END IF;
 response:=jsonb_build_object('body',body_value,'version',version_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
 INSERT INTO zasp_workflow_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,principal_id,operation,resource_kind,resource_id,resource_version)
 VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,principal_value,operation_value,resource_kind_value,resource_value,version_value);
 INSERT INTO zasp_workflow_idempotency(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,request_digest,response)
 VALUES(organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value,digest(convert_to(intent_value::text,'UTF8'),'sha256'),response-'replayed');
 IF receipt_value<>'' THEN
   INSERT INTO zasp_workflow_receipts(organization_id,workspace_id,environment_id,principal_id,receipt_id,operation,idempotency_key,intent,result,resource_kind,resource_id,resource_version,audit_id,correlation_id)
   VALUES(organization_value,workspace_value,environment_value,principal_value,receipt_value,operation_value,idempotency_value,intent_value,body_value,resource_kind_value,resource_value,version_value,audit_value,correlation_value);
 END IF;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_policy_deployment_store_temporary_source(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, device_value text, credential_value text, sequence_value bigint, policy_version_value bigint, key_value text, issued_value timestamp with time zone, expires_value timestamp with time zone, failure_mode_value text, payload_digest_value bytea, policies_value jsonb, signature_value bytea, envelope_digest_value bytea)
