   response_value:=jsonb_build_object('run_id',r,'state','failed','version',run_row.version+1,'error_code',error_value,'replayed',false);
  END IF;
  INSERT INTO public.zasp_security_agent_planner_receipts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,output_digest,outcome,model,policy_version,response)
  VALUES(o,w,e,r,run_row.attempt,input_value,output_value,outcome_value,model_value,policy_value,response_value);
  IF outcome_value='budget_stopped' THEN RETURN response_value;END IF;
  event_value:=jsonb_build_object('run_id',r,'attempt',run_row.attempt,'error_code',error_value,'input_digest','sha256:'||encode(input_value,'hex'),
   'output_digest',CASE WHEN output_value IS NULL THEN NULL ELSE 'sha256:'||encode(output_value,'hex') END,'model',model_value,'policy_version',policy_value);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
  VALUES(o,w,e,audit_value,correlation_value,r,worker_value,'planner_failed',digest(convert_to(event_value::text,'UTF8'),'sha256'),event_value);
  -- Retain the exact lease through receipt/audit waits; failure is a terminal
  -- transition only after all current context and clock authority is rechecked.
  context_value:=public.zasp_sa_attack_lab_planner_context(o,w,e,r,worker_value,lease_value);
  IF context_value ? 'budget_stop' THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test failure budget stopped';END IF;
  IF context_value->>'input_digest' IS DISTINCT FROM 'sha256:'||encode(input_value,'hex') THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test failure context changed';
  END IF;
  UPDATE public.zasp_security_agent_runs SET state='failed',last_error_code=error_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,
   version=version+1,updated_at=clock_timestamp(),completed_at=clock_timestamp()
  WHERE (organization_id,workspace_id,environment_id,run_id,state,lease_owner,lease_token,version)=(o,w,e,r,'planning',worker_value,lease_value,run_row.version)
   AND lease_expires_at>clock_timestamp();
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test failure lease lost';END IF;
  RETURN response_value;
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN
  IF public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test failure stop changed';END IF;
  response_value:=public.zasp_security_agent_budget_context_stop(o,w,e,r);
  INSERT INTO public.zasp_security_agent_planner_receipts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,output_digest,outcome,model,policy_version,response)
  VALUES(o,w,e,r,run_row.attempt,input_value,output_value,'budget_stopped',model_value,policy_value,response_value);
  RETURN response_value;
 END;
END
$function$

CREATE OR REPLACE FUNCTION zasp_sa_export_prior.accounting_9(o text, w text, e text, r text, worker_value text, lease_value text, input_value bytea, output_value bytea, model_value text, policy_value text, candidate_value jsonb, approval_value text, expires_value timestamp with time zone, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context_value jsonb;prepared_value jsonb;response_value jsonb;run_row public.zasp_security_agent_runs%ROWTYPE;
 prior public.zasp_security_agent_planner_receipts%ROWTYPE;summary_value text;outcome_value text;
BEGIN
 IF NOT COALESCE(public.zasp_sa_export_principal_ready('zasp_security_agent_worker') AND public.zasp_valid_product_id(o)
  AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND length(worker_value) BETWEEN 1 AND 128 AND length(lease_value) BETWEEN 16 AND 128,false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='existing test acceptance principal rejected';
 END IF;
 IF NOT public.zasp_sa_export_guard() THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test acceptance release unavailable';
 END IF;
 IF NOT COALESCE(octet_length(input_value)=32 AND octet_length(output_value)=32 AND length(model_value) BETWEEN 1 AND 128 AND length(policy_value) BETWEEN 1 AND 64,false)
  OR jsonb_typeof(candidate_value) IS DISTINCT FROM 'object'
  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(candidate_value) key) IS DISTINCT FROM ARRAY['steps','summary','version']::text[]
  OR candidate_value->'version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(candidate_value->'summary') IS DISTINCT FROM 'string'
  OR jsonb_typeof(candidate_value->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(candidate_value->'steps')<>1
  OR jsonb_typeof(candidate_value->'steps'->0) IS DISTINCT FROM 'object'
  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(candidate_value->'steps'->0) key) IS DISTINCT FROM ARRAY['action','evidence_ids','index','target_id']::text[]
  OR candidate_value->'steps'->0->'index' IS DISTINCT FROM '0'::jsonb
  OR jsonb_typeof(candidate_value->'steps'->0->'action') IS DISTINCT FROM 'string'
  OR jsonb_typeof(candidate_value->'steps'->0->'target_id') IS DISTINCT FROM 'string' THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test acceptance candidate rejected';
 END IF;
 PERFORM public.zasp_sa_export_selection(candidate_value->'steps'->0->'evidence_ids');
 summary_value:=candidate_value->>'summary';
 IF length(summary_value) NOT BETWEEN 1 AND 500 OR summary_value~'[[:cntrl:]]' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test acceptance summary rejected';END IF;
 -- Replay is serialized before inspecting the receipt and does not require or
 -- mutate a new lease. Fresh writes still use the exact lease/context guard.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test acceptance run changed';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_planner_receipts WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,run_row.attempt);
 IF FOUND THEN
  IF prior.input_digest IS DISTINCT FROM input_value OR prior.output_digest IS DISTINCT FROM output_value OR prior.model IS DISTINCT FROM model_value
   OR prior.policy_version IS DISTINCT FROM policy_value OR prior.outcome NOT IN('accepted','budget_stopped')
   OR prior.response->>'planner_summary' IS DISTINCT FROM summary_value THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test acceptance replay conflict';
  END IF;
  IF prior.outcome='accepted' AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)
   AND plan->'steps'->0->>'action'=candidate_value->'steps'->0->>'action' AND plan->'steps'->0->>'target_id'=candidate_value->'steps'->0->>'target_id' AND plan->'steps'->0->'evidence_ids'=candidate_value->'steps'->0->'evidence_ids') THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test acceptance replay candidate changed';
  END IF;
  RETURN prior.response||jsonb_build_object('replayed',true);
 END IF;
 context_value:=public.zasp_sa_export_planner_context(o,w,e,r,worker_value,lease_value);

 BEGIN
  IF context_value ? 'budget_stop' THEN
   response_value:=public.zasp_security_agent_budget_stop_result(o,w,e,r,'prepare');
  ELSE
   IF context_value->>'input_digest' IS DISTINCT FROM 'sha256:'||encode(input_value,'hex')
    OR candidate_value->'steps'->0->>'action' IS DISTINCT FROM context_value->'context'->'allowed_actions'->>0
    OR candidate_value->'steps'->0->>'target_id' IS DISTINCT FROM context_value->'context'->'allowed_targets'->>0 THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test acceptance authority changed';
   END IF;
   prepared_value:=public.zasp_sa_export_prepare_core(o,w,e,r,worker_value,lease_value,approval_value,expires_value,audit_value,correlation_value,candidate_value->'steps'->0->'evidence_ids');
   response_value:=prepared_value->'result';
  END IF;
  outcome_value:=CASE WHEN response_value->>'state'='needs_human' THEN 'budget_stopped' ELSE 'accepted' END;
  response_value:=response_value||jsonb_build_object('planner_outcome',outcome_value,'planner_summary',summary_value,'replayed',false);
  INSERT INTO public.zasp_security_agent_planner_receipts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,output_digest,outcome,model,policy_version,response)
  VALUES(o,w,e,r,run_row.attempt,input_value,output_value,outcome_value,model_value,policy_value,response_value);
  IF outcome_value='accepted' THEN PERFORM public.zasp_sa_export_finish_prepare(o,w,e,r,worker_value,lease_value,prepared_value);END IF;
  RETURN response_value;
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN
  IF public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test acceptance stop changed';END IF;
  response_value:=public.zasp_security_agent_budget_stop_result(o,w,e,r,'prepare')||jsonb_build_object('planner_outcome','budget_stopped','planner_summary',summary_value,'replayed',false);
  INSERT INTO public.zasp_security_agent_planner_receipts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,output_digest,outcome,model,policy_version,response)
  VALUES(o,w,e,r,run_row.attempt,input_value,output_value,'budget_stopped',model_value,policy_value,response_value);
  RETURN response_value;
 END;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_sa_export_reserve_core(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, lease_token_value text, attempt_value bigint, reservation_value text, input_digest_value bytea, model_value text, cost_policy_value text, cost_unit_value text, maximum_tokens_value bigint, maximum_cost_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_security_agent_runs%ROWTYPE;budget_row zasp_security_agent_run_budgets%ROWTYPE;
 context_value jsonb;reason_value text;used_tokens numeric;used_cost numeric;
BEGIN
 -- Acquire organization, run, budget in that order and validate the live
 -- principal/lease before inspecting any tenant authority.
 IF NOT zasp_security_agent_budget_can_start(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value) THEN
  RETURN zasp_security_agent_budget_context_stop(organization_value,workspace_value,environment_value,run_value);
 END IF;
 SELECT * INTO STRICT run_row FROM zasp_security_agent_runs
  WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);
 IF attempt_value IS DISTINCT FROM run_row.attempt OR input_digest_value IS NULL OR octet_length(input_digest_value)<>32
 OR reservation_value IS NULL OR length(reservation_value) NOT BETWEEN 1 AND 128 THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent planner reservation identity changed';
 END IF;
 -- Recompute canonical context, including current definition and prerequisites.
 -- Its final clock guard propagates a committed stop after any prerequisite wait.
 context_value:=public.zasp_sa_export_planner_context(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value);
 IF context_value ? 'budget_stop' THEN RETURN context_value;END IF;
 IF context_value->>'input_digest' IS DISTINCT FROM 'sha256:'||encode(input_digest_value,'hex') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent planner reservation input changed';
 END IF;
 SELECT * INTO STRICT budget_row FROM zasp_security_agent_run_budgets
  WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);
 IF NOT COALESCE(budget_row.max_tokens BETWEEN 1 AND 12000
  AND budget_row.max_cost_nano_credits BETWEEN 1 AND 1000000000000
  AND maximum_tokens_value BETWEEN 1 AND 12000 AND maximum_cost_value BETWEEN 1 AND 1000000000000
  AND length(model_value) BETWEEN 1 AND 256 AND length(cost_policy_value) BETWEEN 1 AND 256
  AND cost_unit_value=budget_row.cost_unit,false) THEN
  reason_value:='budget_usage_unknown';
 ELSIF EXISTS(SELECT 1 FROM zasp_security_agent_provider_reservations p
  WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(organization_value,workspace_value,environment_value,run_value)
   AND (p.settled_at IS NULL OR p.attempt=attempt_value OR p.reservation_id=reservation_value)) THEN
  -- A response lost after commit is not a reusable dispatch permit. Retain all
  -- prior reservations, including unknown outcomes across lease loss/restart.
  reason_value:='budget_usage_unknown';
 ELSE
  SELECT coalesce(sum(CASE WHEN settled_at IS NULL THEN maximum_tokens ELSE total_tokens END),0),
   coalesce(sum(CASE WHEN settled_at IS NULL THEN maximum_cost_nano_credits ELSE cost_nano_credits END),0)
   INTO used_tokens,used_cost FROM zasp_security_agent_provider_reservations
   WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF used_tokens+maximum_tokens_value>budget_row.max_tokens THEN reason_value:='budget_tokens_exceeded';
  ELSIF used_cost+maximum_cost_value>budget_row.max_cost_nano_credits THEN reason_value:='budget_cost_exceeded';END IF;
 END IF;
 IF reason_value IS NOT NULL THEN
  UPDATE zasp_security_agent_run_budgets SET stop_reason=reason_value
   WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);
  PERFORM zasp_security_agent_budget_can_start(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value);
  RETURN zasp_security_agent_budget_context_stop(organization_value,workspace_value,environment_value,run_value);
 END IF;
 -- No exception follows a persisted budget stop. Recheck clock/lease just
 -- before creating authority; the caller receives one permit only on commit.
 IF NOT zasp_security_agent_budget_can_start(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value) THEN
  RETURN zasp_security_agent_budget_context_stop(organization_value,workspace_value,environment_value,run_value);
 END IF;
 INSERT INTO zasp_security_agent_provider_reservations(organization_id,workspace_id,environment_id,run_id,attempt,reservation_id,input_digest,model,cost_policy_version,cost_unit,maximum_tokens,maximum_cost_nano_credits,worker_id,lease_token_digest)
 VALUES(organization_value,workspace_value,environment_value,run_value,attempt_value,reservation_value,input_digest_value,model_value,cost_policy_value,cost_unit_value,maximum_tokens_value,maximum_cost_value,worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'));
 RETURN jsonb_build_object('budget_permit',jsonb_build_object(
  'organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'run_id',run_value,
  'attempt',attempt_value,'version',run_row.version,'reservation_id',reservation_value,'input_digest','sha256:'||encode(input_digest_value,'hex'),
  'model',model_value,'cost_policy_version',cost_policy_value,'cost_unit',cost_unit_value,
  'maximum_tokens',maximum_tokens_value,'maximum_cost_nano_credits',maximum_cost_value,
  'expires_at',least(run_row.lease_expires_at,budget_row.deadline_at)));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_sa_export_reserve_planner(o text, w text, e text, r text, worker_value text, lease_value text, attempt_value bigint, reservation_value text, input_digest_value bytea, model_value text, cost_policy_value text, cost_unit_value text, maximum_tokens_value bigint, maximum_cost_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;context_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_sa_export_principal_ready('zasp_security_agent_worker'),false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='existing test reservation principal unavailable';
 END IF;
 IF NOT public.zasp_sa_export_guard() THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test reservation release unavailable';
 END IF;
 BEGIN
  result_value:=public.zasp_sa_export_reserve_core(o,w,e,r,worker_value,lease_value,attempt_value,reservation_value,input_digest_value,model_value,cost_policy_value,cost_unit_value,maximum_tokens_value,maximum_cost_value);
  -- A core stop can carry a newly discovered reason. Never roll it back merely
  -- to re-evaluate can_start, which would no longer have that reason to retain.
  IF result_value ? 'budget_stop' THEN RETURN result_value;END IF;
  -- The INSERT may have waited after its pre-write clock check. Recompute all
  -- authority after that wait while the organization/run/prerequisite locks
  -- are still held. An expired permit must never leave a durable reservation.
  context_value:=public.zasp_sa_export_planner_context(o,w,e,r,worker_value,lease_value);
  IF context_value ? 'budget_stop' THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test reservation deadline stopped';END IF;
  IF context_value->>'input_digest' IS DISTINCT FROM 'sha256:'||encode(input_digest_value,'hex') THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test reservation context changed';
  END IF;
  RETURN result_value;
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN
  -- Undo the just-created permit and its inner stop. Persist the deadline stop
  -- outside the savepoint. A lease error still aborts rather than grants work.
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN
   RETURN public.zasp_security_agent_budget_context_stop(o,w,e,r);
  END IF;
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test reservation stop changed';
 END;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_sa_export_run_kind(o text, w text, e text, r text, worker_value text, lease_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;l public.zasp_sa_export_links%ROWTYPE;prior public.zasp_sa_attack_lab_links%ROWTYPE;p public.zasp_security_agent_plans%ROWTYPE;d public.zasp_security_agent_definition_versions%ROWTYPE;is_export boolean;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR NOT public.zasp_sa_export_principal_ready('zasp_security_agent_worker') OR NOT public.zasp_sa_export_guard() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='export route authority unavailable';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[o,w,e,r]) id WHERE NOT COALESCE(public.zasp_valid_product_id(id),false)) OR NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND length(lease_value) BETWEEN 16 AND 128,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='export route identity rejected';END IF;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='export route parent unavailable';END IF;
 SELECT * INTO l FROM public.zasp_sa_export_links WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF FOUND THEN
  IF (l.dispatch_worker,l.dispatch_token_digest) IS DISTINCT FROM (worker_value,digest(lease_value,'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route replay identity changed';END IF;
  PERFORM public.zasp_sa_export_authorize(o,w,e,r,l.step_id,'retrieve');RETURN jsonb_build_object('export',true);
 END IF;
 SELECT * INTO prior FROM public.zasp_sa_attack_lab_links WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF FOUND THEN
  IF prior.dispatch_worker IS DISTINCT FROM worker_value OR prior.dispatch_lease_digest IS DISTINCT FROM digest(convert_to(lease_value,'UTF8'),'sha256')
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_plans replay_plan JOIN public.zasp_security_agent_steps s USING(organization_id,workspace_id,environment_id,run_id) JOIN public.zasp_security_agent_approvals a USING(organization_id,workspace_id,environment_id,run_id,step_id)
    WHERE (replay_plan.organization_id,replay_plan.workspace_id,replay_plan.environment_id,replay_plan.run_id,s.step_id)=(o,w,e,r,prior.step_id) AND replay_plan.plan_hash=prior.plan_hash AND digest(convert_to(replay_plan.plan::text,'UTF8'),'sha256')=prior.plan_hash AND s.input_digest=prior.input_digest AND replay_plan.plan->'steps'->0=prior.intent->'step' AND a.approval_id=prior.approval_id AND a.version=(prior.intent->>'approval_version')::bigint AND a.approver_id=prior.approver_id AND a.requester_id=prior.requester_id AND a.plan_hash=prior.plan_hash AND to_jsonb(a.fresh_auth_at)=prior.intent->'fresh_auth_at' AND a.state='approved') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route attack lab replay changed';END IF;
  RETURN jsonb_build_object('export',false);
 END IF;
 IF rr.state IS DISTINCT FROM 'planning' OR (rr.lease_owner,rr.lease_token) IS DISTINCT FROM (worker_value,lease_value) OR rr.lease_expires_at IS NULL OR rr.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route lease lost';END IF;
 SELECT * INTO STRICT d FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,rr.definition_id,rr.definition_version);
 IF d.definition_digest IS DISTINCT FROM digest(convert_to(d.definition::text,'UTF8'),'sha256') OR jsonb_typeof(d.definition->'allowed_actions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route definition changed';END IF;
 SELECT * INTO p FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF FOUND THEN
  IF (p.plan_hash,p.definition_id,p.definition_version) IS DISTINCT FROM (rr.plan_hash,rr.definition_id,rr.definition_version) OR p.plan_hash IS DISTINCT FROM digest(convert_to(p.plan::text,'UTF8'),'sha256') OR jsonb_typeof(p.plan->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(p.plan->'steps')=0 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route plan changed';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.plan->'steps') WITH ORDINALITY item(value,position) WHERE NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_steps s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_index)=(o,w,e,r,item.position-1) AND s.step_id=item.value->>'step_id' AND s.action_key=item.value->>'action' AND s.input_digest=digest(convert_to(item.value::text,'UTF8'),'sha256'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route step changed';END IF;
  is_export:=EXISTS(SELECT 1 FROM jsonb_array_elements(p.plan->'steps') item WHERE item->>'action'='create_evidence_export');
 ELSE
  IF rr.plan_hash IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export route plan unavailable';END IF;
  is_export:=d.definition->'allowed_actions' ? 'create_evidence_export';
 END IF;
 RETURN jsonb_build_object('export',is_export);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_sa_export_settle(o text, w text, e text, r text, worker_value text, lease_value text, audit_value text, correlation_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;l public.zasp_sa_export_links%ROWTYPE;j public.zasp_compliance_export_jobs%ROWTYPE;result_value jsonb;facts jsonb;reason_value text;stopped boolean;deadline timestamptz;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR NOT public.zasp_sa_export_principal_ready('zasp_security_agent_worker') OR NOT public.zasp_sa_export_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='export settlement authority rejected';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[o,w,e,r,audit_value,correlation_value]) id WHERE NOT COALESCE(public.zasp_valid_product_id(id),false)) OR NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND length(lease_value) BETWEEN 16 AND 128,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='export settlement identity rejected';END IF;
 -- Common order is parent, link, job. Claim takes only the link lock and
 -- cannot authorize storage. Cleanup never needs this parent lease.
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='export settlement parent unavailable';END IF;
 SELECT * INTO l FROM public.zasp_sa_export_links WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR (l.settlement_worker,l.settlement_token_digest) IS DISTINCT FROM (worker_value,digest(lease_value,'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export settlement lease rejected';END IF;
 IF l.settled_at IS NOT NULL THEN
  IF (l.settlement_audit_id,l.settlement_correlation_id) IS DISTINCT FROM (audit_value,correlation_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export settlement replay rejected';END IF;
  RETURN l.settlement_result||jsonb_build_object('replayed',true);
 END IF;
 deadline:=l.settlement_lease_expires_at;
 IF NOT COALESCE(deadline>clock_timestamp(),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export settlement lease expired';END IF;
 PERFORM public.zasp_sa_export_authorize(o,w,e,r,l.step_id,'retrieve');
 PERFORM 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,outcome_id)=(o,w,e,r,l.step_id,'create_evidence_export',l.input_digest,l.export_id) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export settlement effect changed';END IF;
 SELECT * INTO STRICT j FROM public.zasp_compliance_export_jobs WHERE (organization_id,workspace_id,environment_id,export_id,job_origin,agent_run_id,agent_step_id)=(o,w,e,l.export_id,'agent_run',r,l.step_id) FOR UPDATE;
 stopped:=rr.state NOT IN('queued','planning','waiting_approval','running','verifying');
 IF NOT stopped AND j.state='pending' THEN RETURN jsonb_build_object('run_id',r,'run_version',rr.version,'step_id',l.step_id,'export_id',l.export_id,'state','verifying','reason','export_pending','settled',false,'replayed',false);END IF;
 IF stopped THEN
  reason_value:=CASE WHEN rr.state='cancelled' THEN 'export_cancelled' ELSE 'export_parent_stopped' END;
  -- Intent permits an in-flight provider call. Retain bytes and the obligation
  -- to reconcile; no failed/stopped parent can publish or authorize a new PUT.
  UPDATE public.zasp_compliance_export_jobs SET state=CASE WHEN state='pending' THEN 'failed' ELSE state END,phase='terminal',failure_code=CASE WHEN state='pending' THEN reason_value ELSE failure_code END,
   storage_state=CASE WHEN package IS NOT NULL AND receipt_version IS NULL THEN 'reconcile_required' ELSE storage_state END,
   retrieval_expires_at=least(retrieval_expires_at,clock_timestamp()),lease_expires_at=NULL,lease_digest=NULL,next_attempt_at=clock_timestamp()
   WHERE (organization_id,workspace_id,environment_id,export_id)=(o,w,e,l.export_id) RETURNING * INTO j;
 ELSE
  reason_value:=CASE WHEN j.state='completed' AND j.storage_state='verified' AND j.receipt_version IS NOT NULL AND j.artifact_digest IS NOT NULL AND j.artifact_size>0 AND j.renderer_revision='security-agent-evidence-envelope-v1' AND digest(j.package,'sha256')=j.artifact_digest THEN 'export_available' ELSE 'export_failed' END;
  UPDATE public.zasp_security_agent_runs SET state='needs_human',last_error_code=reason_value,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO rr;
  UPDATE public.zasp_security_agent_steps SET state=CASE WHEN reason_value='export_available' THEN 'succeeded' ELSE 'failed' END,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,l.step_id);
 END IF;
 facts:=jsonb_build_object('export_id',j.export_id,'state',j.state,'storage_state',j.storage_state,'sha256',encode(j.artifact_digest,'hex'),'version',j.receipt_version,'size',j.artifact_size,'retained_bytes',j.retained_bytes,'retrieval_expires_at',j.retrieval_expires_at);
 result_value:=jsonb_build_object('run_id',r,'run_version',rr.version,'step_id',l.step_id,'export_id',l.export_id,'state',rr.state,'reason',reason_value,'settled',true,'replayed',false);
 UPDATE public.zasp_security_agent_effects SET state=CASE WHEN reason_value='export_available' THEN 'succeeded' WHEN j.storage_state IN('intent','unknown','reconcile_required','delete_pending') THEN 'cleanup_pending' ELSE 'known_failure' END,result_digest=digest(convert_to(facts::text,'UTF8'),'sha256'),version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,l.step_id,'create_evidence_export');
 UPDATE public.zasp_sa_export_links SET settled_at=clock_timestamp(),settlement_result=result_value,settlement_snapshot=facts,settlement_audit_id=audit_value,settlement_correlation_id=correlation_value WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,l.step_id);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,correlation_value,r,l.step_id,worker_value,'export_settled',digest(convert_to(facts::text,'UTF8'),'sha256'),result_value);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='export settlement lease expired';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_sa_export_settlement_claim(worker_value text, lease_value text, lease_seconds integer, claim_limit integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE l public.zasp_sa_export_links%ROWTYPE;result_value jsonb:='[]';rv bigint;expiry timestamptz;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR NOT public.zasp_sa_export_principal_ready('zasp_security_agent_worker') OR NOT public.zasp_sa_export_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='export settlement authority rejected';END IF;
 IF NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND length(lease_value) BETWEEN 16 AND 128 AND lease_seconds BETWEEN 30 AND 300 AND claim_limit BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='export settlement claim rejected';END IF;
 FOR l IN
  WITH due AS (SELECT x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.settlement_last_claimed_at,x.created_at,row_number() OVER(PARTITION BY x.organization_id,x.workspace_id,x.environment_id ORDER BY x.settlement_last_claimed_at,x.created_at,x.run_id,x.step_id) ordinal
   FROM public.zasp_sa_export_links x JOIN public.zasp_security_agent_runs r USING(organization_id,workspace_id,environment_id,run_id) JOIN public.zasp_compliance_export_jobs j USING(organization_id,workspace_id,environment_id,export_id)
   WHERE x.settled_at IS NULL AND (x.settlement_lease_expires_at IS NULL OR x.settlement_lease_expires_at<=clock_timestamp()) AND (j.state IN('completed','failed') OR r.state NOT IN('queued','planning','waiting_approval','running','verifying')))
  SELECT x.* FROM due d JOIN public.zasp_sa_export_links x USING(organization_id,workspace_id,environment_id,run_id,step_id)
  ORDER BY d.ordinal,d.settlement_last_claimed_at,d.created_at,d.organization_id,d.workspace_id,d.environment_id,d.run_id,d.step_id LIMIT claim_limit FOR UPDATE OF x SKIP LOCKED
 LOOP
  -- The due alias can retain an older READ COMMITTED candidate after another
  -- claimant commits. Recheck the current locked tuple before replacing a lease.
  CONTINUE WHEN l.settled_at IS NOT NULL OR (l.settlement_lease_expires_at IS NOT NULL AND l.settlement_lease_expires_at>clock_timestamp());
  -- No parent lease, budget reservation, actor permission or upload authority.
  expiry:=clock_timestamp()+make_interval(secs=>lease_seconds);
  UPDATE public.zasp_sa_export_links SET settlement_worker=worker_value,settlement_token_digest=digest(lease_value,'sha256'),settlement_lease_expires_at=expiry,settlement_last_claimed_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(l.organization_id,l.workspace_id,l.environment_id,l.run_id,l.step_id);
  SELECT version INTO STRICT rv FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(l.organization_id,l.workspace_id,l.environment_id,l.run_id);
  result_value:=result_value||jsonb_build_array(jsonb_build_object('organization_id',l.organization_id,'workspace_id',l.workspace_id,'environment_id',l.environment_id,'run_id',l.run_id,'step_id',l.step_id,'export_id',l.export_id,'run_version',rv,'lease_expires_at',expiry));
 END LOOP;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_sa_manual_authority(o text, w text, e text, d text, v bigint, actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE current_row public.zasp_security_agent_definitions%ROWTYPE;original public.zasp_security_agent_definition_versions%ROWTYPE;action_value text;binding_value jsonb:='{}';
BEGIN
 SELECT * INTO current_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR current_row.activation NOT IN('supervised','autonomous') OR current_row.body->>'autonomy' IS DISTINCT FROM current_row.activation OR current_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR NOT COALESCE(current_row.body->'environment_ids' ? e,false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='manual definition unavailable';END IF;
 SELECT * INTO original FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) FOR SHARE;
 IF NOT FOUND OR (original.activation,original.definition) IS DISTINCT FROM (current_row.activation,current_row.body) OR original.definition_digest IS DISTINCT FROM digest(convert_to(original.definition::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='manual original definition changed';END IF;
 PERFORM public.zasp_sa_export_principal(o,w,e,original.actor_id);
 PERFORM public.zasp_sa_export_principal(o,w,e,actor);
 IF jsonb_typeof(current_row.body->'allowed_actions') IS DISTINCT FROM 'array' OR jsonb_array_length(current_row.body->'allowed_actions')=0 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='manual actions unavailable';END IF;
 FOR action_value IN SELECT jsonb_array_elements_text(current_row.body->'allowed_actions') LOOP
  PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,action_value);
  CASE action_value
  WHEN 'run_test','rerun_test' THEN binding_value:=binding_value||jsonb_build_object(action_value,public.zasp_production_security_agent_run_context_test_binding(o,w,e,d,v));
  WHEN 'start_attack_lab' THEN binding_value:=binding_value||jsonb_build_object(action_value,public.zasp_sa_attack_lab_planner_binding(o,w,e,d,v));
  WHEN 'create_evidence_export' THEN IF current_row.body->>'verification_kind' IS DISTINCT FROM 'export' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='manual export verification unavailable';END IF;
  WHEN 'send_response_webhook' THEN PERFORM public.zasp_sa_webhook_destination(o,w,e,current_row.body->'response_webhook_destination');
  ELSE RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='manual action source prerequisite unavailable';
  END CASE;
 END LOOP;
 -- Re-read effective scope after all prerequisite waits, including group grants.
 PERFORM public.zasp_sa_export_principal(o,w,e,original.actor_id);PERFORM public.zasp_sa_export_principal(o,w,e,actor);
 RETURN jsonb_build_object('definition',current_row.body,'definition_digest',encode(original.definition_digest,'hex'),'bindings',binding_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_sa_manual_recheck(o text, w text, e text, r text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;
BEGIN
 IF public.zasp_sa_manual_provenance(o,w,e,r) IS NULL THEN RETURN;END IF;
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 PERFORM public.zasp_sa_manual_authority(o,w,e,rr.definition_id,rr.definition_version,rr.requested_by);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_claim_budgeted_runs(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE manual_check_active boolean:=false;organization_value text;run_row zasp_security_agent_runs%ROWTYPE;
 definition_row zasp_security_agent_definitions%ROWTYPE;budget_row zasp_security_agent_run_budgets%ROWTYPE;
 result_value jsonb:='[]'::jsonb;active_count bigint;active_limit integer;incoming_limit integer;
 start_value timestamptz;now_value timestamptz;duration_value integer;has_budget boolean;
BEGIN
 IF NOT COALESCE(zasp_security_agent_principal_ready('zasp_security_agent_worker'),false)
 OR worker_value IS NULL OR length(worker_value) NOT BETWEEN 1 AND 128
 OR lease_token_value IS NULL OR length(lease_token_value) NOT BETWEEN 16 AND 128
 OR lease_seconds IS NULL OR lease_seconds NOT BETWEEN 30 AND 300
 OR claim_limit IS NULL OR claim_limit NOT BETWEEN 1 AND 25 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent claim rejected';
 END IF;
 -- Oldest eligible organization first; do not wait for another tenant's
 -- admission or work-row locks while holding an organization guard.
 FOR organization_value IN SELECT r.organization_id FROM zasp_security_agent_runs r
  WHERE r.state='queued' AND r.available_at<=clock_timestamp()
   OR r.state IN('planning','running','verifying') AND r.lease_expires_at<=clock_timestamp()
  GROUP BY r.organization_id ORDER BY min(r.available_at),r.organization_id
 LOOP
  -- Serialize first creation too: INSERT ON CONFLICT alone can wait on an
  -- uncommitted insertion even when the subsequent row lock uses SKIP LOCKED.
  CONTINUE WHEN NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||organization_value,0));
  INSERT INTO zasp_security_agent_org_admissions(organization_id) VALUES(organization_value) ON CONFLICT DO NOTHING;
  PERFORM 1 FROM zasp_security_agent_org_admissions a WHERE a.organization_id=organization_value FOR UPDATE SKIP LOCKED;
  CONTINUE WHEN NOT FOUND;
  now_value:=clock_timestamp();
  -- Lock run then budget before expiry writes. Bulk UPDATE would wait on an
  -- old worker holding a run or settlement row, blocking unrelated tenants.
  FOR run_row IN SELECT r.* FROM zasp_security_agent_runs r
   JOIN zasp_security_agent_run_budgets b USING(organization_id,workspace_id,environment_id,run_id)
   WHERE r.organization_id=organization_value AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_webhook_deliveries wh WHERE (wh.organization_id,wh.workspace_id,wh.environment_id,wh.run_id)=(r.organization_id,r.workspace_id,r.environment_id,r.run_id)) AND (b.stop_reason IS NOT NULL OR b.deadline_at<=now_value)
    AND r.state IN('queued','planning','waiting_approval','running','verifying')
   ORDER BY r.workspace_id,r.environment_id,r.run_id FOR UPDATE OF r SKIP LOCKED
  LOOP
   SELECT * INTO budget_row FROM zasp_security_agent_run_budgets b
    WHERE (b.organization_id,b.workspace_id,b.environment_id,b.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)
    FOR UPDATE SKIP LOCKED;
   CONTINUE WHEN NOT FOUND;
   UPDATE zasp_security_agent_run_budgets SET stop_reason=coalesce(stop_reason,'budget_deadline_exceeded')
    WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
   UPDATE zasp_security_agent_runs SET state='needs_human',last_error_code=coalesce(budget_row.stop_reason,'budget_deadline_exceeded'),
    lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=now_value
    WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
  END LOOP;
  FOR run_row IN SELECT r.* FROM zasp_security_agent_runs r WHERE r.organization_id=organization_value AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_webhook_deliveries wh WHERE (wh.organization_id,wh.workspace_id,wh.environment_id,wh.run_id)=(r.organization_id,r.workspace_id,r.environment_id,r.run_id))
   AND (r.state='queued' AND r.available_at<=clock_timestamp()
    OR r.state IN('planning','running','verifying') AND r.lease_expires_at<=clock_timestamp())
   ORDER BY r.available_at,r.workspace_id,r.environment_id,r.run_id FOR UPDATE SKIP LOCKED
  LOOP
   BEGIN
   manual_check_active:=true;
   PERFORM public.zasp_sa_manual_recheck(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
   manual_check_active:=false;
   now_value:=clock_timestamp();
   SELECT * INTO budget_row FROM zasp_security_agent_run_budgets b
    WHERE (b.organization_id,b.workspace_id,b.environment_id,b.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)
    FOR UPDATE SKIP LOCKED;
   has_budget:=FOUND;
   IF NOT has_budget THEN
    -- A locked snapshot is not an absent snapshot and must never be replaced.
    CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_run_budgets b
     WHERE (b.organization_id,b.workspace_id,b.environment_id,b.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id));
    SELECT * INTO definition_row FROM zasp_security_agent_definitions d
     WHERE (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.definition_id,run_row.definition_version)
     AND d.deleted_at IS NULL FOR SHARE SKIP LOCKED;
    IF NOT FOUND THEN
     CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_definitions d
      WHERE (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.definition_id,run_row.definition_version) AND d.deleted_at IS NULL);
     UPDATE zasp_security_agent_runs SET state='needs_human',last_error_code='budget_definition_unavailable',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=now_value
      WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
     CONTINUE;
    END IF;
    incoming_limit:=(definition_row.body->>'concurrency_limit')::integer;
    SELECT zasp_temporal68.active_count(organization_value,'budget',NULL),
      (SELECT min(v) FROM generate_series(1,10) v WHERE zasp_temporal68.active_count(organization_value,'budget',v)>0) INTO active_count,active_limit;
    CONTINUE WHEN active_count>=least(incoming_limit,coalesce(active_limit,incoming_limit));
    duration_value:=(definition_row.body->>'max_duration_seconds')::integer;
    IF duration_value NOT BETWEEN 1 AND 86400 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent duration rejected';END IF;
    start_value:=CASE WHEN run_row.attempt>0 THEN run_row.created_at ELSE now_value END;
    INSERT INTO zasp_security_agent_run_budgets(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,started_at,deadline_at,max_steps,max_tokens,max_cost_nano_credits,concurrency_limit)
     VALUES(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id,run_row.definition_id,run_row.definition_version,start_value,start_value+make_interval(secs=>duration_value),
      (definition_row.body->>'max_steps')::integer,(definition_row.body->>'ai_token_budget')::bigint,(definition_row.body->>'max_ai_cost_nano_credits')::bigint,incoming_limit)
     RETURNING * INTO budget_row;
   END IF;
   IF budget_row.stop_reason IS NOT NULL OR budget_row.deadline_at<=clock_timestamp() THEN
    UPDATE zasp_security_agent_run_budgets SET stop_reason=coalesce(stop_reason,'budget_deadline_exceeded')
     WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
    UPDATE zasp_security_agent_runs SET state='needs_human',last_error_code=coalesce(budget_row.stop_reason,'budget_deadline_exceeded'),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp()
     WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
    CONTINUE;
   END IF;
   UPDATE zasp_security_agent_runs SET state='planning',attempt=attempt+1,lease_owner=worker_value,lease_token=lease_token_value,
    lease_expires_at=clock_timestamp()+make_interval(secs=>lease_seconds),version=version+1,updated_at=clock_timestamp()
    WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)
    RETURNING * INTO run_row;
   manual_check_active:=true;
   PERFORM public.zasp_sa_manual_recheck(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
   manual_check_active:=false;
result_value:=result_value||jsonb_build_array(jsonb_build_object('organization_id',run_row.organization_id,'workspace_id',run_row.workspace_id,'environment_id',run_row.environment_id,'run_id',run_row.run_id,'definition_id',run_row.definition_id,'definition_version',run_row.definition_version,'trigger_id',run_row.trigger_id,'state',run_row.state,'version',run_row.version,'attempt',run_row.attempt,'lease_expires_at',to_char(run_row.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'prepared',EXISTS(SELECT 1 FROM zasp_security_agent_plans p WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)))||public.zasp_sa_manual_fields(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id));
   EXCEPTION WHEN insufficient_privilege OR serialization_failure OR object_not_in_prerequisite_state OR no_data_found THEN
    -- Only domain refusals from the marked check are candidate-local. Role,
    -- catalog, infrastructure and actual serialization failures still abort.
    IF NOT manual_check_active OR NOT (
     SQLSTATE='42501' AND SQLERRM IN('export actor rejected','export membership rejected','export source permission rejected')
     OR SQLSTATE='40001' AND SQLERRM IN('manual definition unavailable','manual original definition changed','manual actions unavailable','manual export verification unavailable','manual action source prerequisite unavailable','run original trigger unavailable','run original trigger malformed','manual original trigger malformed','manual original intent changed','security agent test binding unavailable','attack lab planner reference changed','attack lab source changed','attack lab safety unavailable','attack lab safety expired')
     OR SQLSTATE='55000' AND SQLERRM='existing test execution disabled'
     OR SQLSTATE='P0002' AND SQLERRM IN('attack lab preflight unavailable','query returned no rows')
    ) THEN RAISE;END IF;
    manual_check_active:=false;
    UPDATE public.zasp_security_agent_runs SET state='needs_human',last_error_code='manual_authority_unavailable',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp()
     WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
    CONTINUE;
   END;
   EXIT WHEN jsonb_array_length(result_value)>=claim_limit;
  END LOOP;
  EXIT WHEN jsonb_array_length(result_value)>=claim_limit;
 END LOOP;
 RETURN jsonb_build_object('items',result_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_test_dispatch(o text, w text, e text, r text, worker_value text, lease_value text, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_security_agent_runs%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;
 plan_row public.zasp_security_agent_plans%ROWTYPE;definition_row public.zasp_security_agent_definitions%ROWTYPE;
 trigger_row public.zasp_security_agent_trigger_receipts%ROWTYPE;control_row record;control_count integer:=0;
 link_value jsonb;step_value jsonb;outcome_value text;result_digest_value bytea;response_value jsonb;runtime_expires timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test dispatch input rejected';END IF;
 -- The existing guard establishes principal, full scope, organization-before-
 -- run lock order, current lease and authoritative budget/stop state.
 IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RETURN public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');END IF;
 SELECT * INTO STRICT run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO plan_row FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) FOR SHARE;
 IF NOT FOUND OR plan_row.plan_hash IS DISTINCT FROM run_row.plan_hash OR plan_row.plan_hash IS DISTINCT FROM digest(convert_to(plan_row.plan::text,'UTF8'),'sha256') OR plan_row.expires_at<=clock_timestamp()
  OR jsonb_typeof(plan_row.plan->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(plan_row.plan->'steps')<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test plan changed';END IF;
 SELECT * INTO step_row FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index,state)=(o,w,e,r,0,'authorized') FOR UPDATE;
 IF NOT FOUND OR step_row.action_key NOT IN('run_test','rerun_test') OR step_row.input_digest IS DISTINCT FROM digest(convert_to((plan_row.plan->'steps'->0)::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test step changed';END IF;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb
  OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(step_row.action_key) OR definition_row.body->>'verification_kind' IS DISTINCT FROM 'test_run' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test definition changed';END IF;
 step_value:=plan_row.plan->'steps'->0;
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,step_row.step_id);
 SELECT * INTO trigger_row FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id,trigger_digest)=(o,w,e,r,run_row.definition_id,run_row.trigger_id,plan_row.trigger_digest) FOR SHARE;
 IF NOT FOUND OR trigger_row.trigger_kind<>'manual' AND trigger_row.trigger_kind IS DISTINCT FROM definition_row.body->>'trigger_kind' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test trigger changed';END IF;
 IF trigger_row.trigger_kind='manual' THEN PERFORM public.zasp_sa_manual_recheck(o,w,e,r); PERFORM 1; ELSIF trigger_row.trigger_kind='finding' THEN
  PERFORM 1 FROM public.zasp_risk_findings WHERE (organization_id,workspace_id,environment_id,id,version,status,rule)=(o,w,e,trigger_row.trigger_id,trigger_row.trigger_version,'open',definition_row.body->>'trigger_source') FOR SHARE;
 ELSIF trigger_row.trigger_kind='attack_path' THEN
  PERFORM 1 FROM public.zasp_risk_attack_paths p WHERE (organization_id,workspace_id,environment_id,id,version,state)=(o,w,e,trigger_row.trigger_id,trigger_row.trigger_version,definition_row.body->>'trigger_source') AND state IN('observed','verified') AND public.zasp_risk_attack_path_valid(p) FOR SHARE;
 ELSIF trigger_row.trigger_kind='runtime_decision' THEN
  SELECT credential.expires_at INTO runtime_expires FROM public.zasp_runtime_gateway_events event
  JOIN public.zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active')
  JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id)
  WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.sequence,event.decision,event.classification->>'outcome')=(o,w,e,trigger_row.trigger_id,trigger_row.trigger_version,'block',definition_row.body->>'trigger_source')
   AND credential.revoked_at IS NULL AND credential.expires_at>clock_timestamp()
   AND digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',trigger_row.trigger_id,'device_id',event.device_id,'event_id',event.event_id,'sequence',event.sequence,'request_digest','sha256:'||encode(event.request_digest,'hex'))::text,'UTF8'),'sha256')=trigger_row.trigger_digest
  FOR SHARE OF event,device,credential;
 ELSE RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test trigger unsupported';
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test evidence changed';END IF;
 FOR control_row IN SELECT * FROM public.zasp_security_agent_kill_switches
  WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*',step_row.action_key)
  ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE LOOP
  control_count:=control_count+1;
  IF NOT control_row.execution_enabled THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test execution disabled';END IF;
 END LOOP;
 IF control_count<>3 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test execution disabled';END IF;
 BEGIN
  IF NOT public.zasp_security_agent_budget_reserve_step(o,w,e,r,worker_value,lease_value,step_row.step_id) THEN RETURN public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');END IF;
  INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state) VALUES(o,w,e,r,step_row.step_id,step_row.action_key,step_row.input_digest,'pending');
  link_value:=public.zasp_security_agent_test_link_enqueue(o,w,e,r,step_row.step_id,correlation_value);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id,target_id,target_kind)=(o,w,e,r,step_row.step_id,step_value->>'test_target_id',step_value->>'test_target_kind')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test target changed';END IF;
  IF plan_row.expires_at<=clock_timestamp() OR runtime_expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test authority expired';END IF;
  PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,step_row.step_id);
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test budget stopped';END IF;
  outcome_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_effect',r||chr(31)||step_row.step_id||chr(31)||step_row.action_key);
  result_digest_value:=digest(convert_to(link_value::text,'UTF8'),'sha256');
  UPDATE public.zasp_security_agent_effects SET outcome_id=outcome_value,result_digest=result_digest_value WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,step_row.step_id,step_row.action_key);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,correlation_value,r,step_row.step_id,worker_value,'effect_dispatched',result_digest_value,jsonb_build_object('run_id',r,'step_id',step_row.step_id,'action',step_row.action_key,'test_run_id',link_value->>'test_run_id','test_definition_id',link_value->>'definition_id','outcome_id',outcome_value));
  -- Audit relation/index waits can outlive any earlier check. Keep the lease
  -- until all potentially blocking writes finish, then recheck held authority.
  PERFORM public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
  PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,step_row.step_id);
  IF plan_row.expires_at<=clock_timestamp() OR runtime_expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test authority expired';END IF;
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test budget stopped';END IF;
  UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,step_row.step_id);
  UPDATE public.zasp_security_agent_runs SET state='running',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  response_value:=jsonb_build_object('run_id',r,'state','running','version',run_row.version+1,'step_id',step_row.step_id,'effect_state','pending','outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex'));
  RETURN response_value;
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN
  -- Roll back reservation, effect, link and enqueue, then persist the stop
  -- outside that subtransaction. Never return a stop alongside hidden work.
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RETURN public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');END IF;
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test budget changed';
 END;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_test_link_enqueue(o text, w text, e text, r text, s text, c text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_security_agent_runs%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;
 prior public.zasp_security_agent_test_links%ROWTYPE;body_value jsonb;binding jsonb;actor_value text;test_run text;result_value jsonb;baseline_value jsonb;baseline_cutoff timestamptz;categories_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s) AND public.zasp_valid_product_id(c),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test link input rejected';
 END IF;
 SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link intent changed';END IF;
 SELECT * INTO step_row FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 IF NOT FOUND OR step_row.action_key NOT IN('run_test','rerun_test') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link intent changed';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF FOUND THEN
  IF prior.action_key IS DISTINCT FROM step_row.action_key OR prior.input_digest IS DISTINCT FROM step_row.input_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link replay conflict';END IF;
  RETURN prior.result||jsonb_build_object('replayed',true);
 END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,s);
 PERFORM 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state)=(o,w,e,r,s,step_row.action_key,step_row.input_digest,'pending') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link effect missing';END IF;
 SELECT body INTO body_value FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR body_value->'allowed_actions' IS DISTINCT FROM jsonb_build_array(step_row.action_key) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link definition changed';END IF;
 SELECT actor_id INTO actor_value FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) FOR SHARE;
 IF NOT FOUND OR NOT COALESCE(public.zasp_valid_product_id(actor_value),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link actor unavailable';END IF;
 test_run:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_run',r||chr(31)||s||chr(31)||step_row.action_key);
 -- Match the shared human/API core's advisory-before-test-definition order.
 -- Take all such blocking locks before the resolver's wall-clock checks.
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,actor_value,'runTest','agent-step:'||test_run),0));
 -- Enqueue's existing core takes a write lock on the definition. Take that
 -- lock before the resolver's SHARE lock, avoiding concurrent lock upgrades.
 PERFORM 1 FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,body_value->'existing_test'->>'definition_id') FOR UPDATE;
 binding:=public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
 SELECT categories INTO STRICT categories_value FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,binding->>'definition_id',(binding->>'definition_version')::bigint);
 -- queued_at defaults to transaction start and can predate lock waits. Use
 -- the wall-clock pre-enqueue boundary and snapshot before creating new work.
 baseline_cutoff:=clock_timestamp();
 -- Snapshot committed completion receipts visible at enqueue. Do not lock old
 -- runs here: completion locks run before definition, and we own definition.
 -- This is a candidate, not remediation proof. Settlement must retrieve both
 -- immutable objects and validate their full comparison/evaluation identities.
 -- A legacy candidate lacking comparison data must not be replaced by an older
 -- comparable result merely to manufacture a fail-to-pass claim.
 SELECT jsonb_build_object('schema_version','security-agent-test-baseline-v1',
  'run_id',a.run_id,'attempt',a.attempt,'input_digest',encode(a.input_digest,'hex'),
  'completed_at',to_char(a.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'input_artifact',a.input_artifact,
  'output_artifact',jsonb_build_object('reference',a.evidence_reference,'key',a.evidence_key,
   'version_id',a.evidence_version_id,'sha256',encode(a.evidence_checksum,'hex'),'size_bytes',a.evidence_size))
 INTO baseline_value
 FROM public.zasp_red_team_runs b
 JOIN public.zasp_red_team_attempts a ON (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.attempt)=(b.organization_id,b.workspace_id,b.environment_id,b.run_id,b.attempt)
 WHERE (b.organization_id,b.workspace_id,b.environment_id,b.definition_id,b.definition_version,b.state,b.verdict)=
  (o,w,e,binding->>'definition_id',(binding->>'definition_version')::bigint,'complete','fail')
 AND b.run_id<>test_run AND b.completed_at<baseline_cutoff AND a.completed_at=b.completed_at
 AND b.error_code IS NULL AND a.error_code IS NULL
 AND (a.input_digest,a.verdict,a.evidence_reference,a.evidence_key,a.evidence_version_id,a.evidence_checksum,a.evidence_size)=
  (b.input_digest,b.verdict,b.evidence_reference,b.evidence_key,b.evidence_version_id,b.evidence_checksum,b.evidence_size)
 AND public.zasp_red_team_valid_input_artifact(o,w,e,a.input_artifact)
 AND a.evidence_checksum<>decode(repeat('00',32),'hex')
 AND public.zasp_discovery_s3_object_reference(a.evidence_reference)
 AND a.evidence_key='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||b.run_id
 AND substring(a.evidence_reference FROM '^s3://[^/]+/(.+)$')=a.evidence_key
 AND a.input_artifact->>'reference'<>a.evidence_reference
 AND length(a.evidence_version_id) BETWEEN 1 AND 512 AND a.evidence_version_id!~'[[:space:][:cntrl:]]'
 ORDER BY b.completed_at DESC,b.run_id DESC,a.attempt DESC LIMIT 1;
 result_value:=public.zasp_security_agent_test_enqueue_core(o,w,e,actor_value,'agent-step:'||test_run,binding->>'definition_id',(binding->>'definition_version')::bigint,test_run,c);
 -- Only an existing agent link can authorize replay. A colliding human/API
 -- receipt must not be adopted as new Security Agent provenance.
 IF result_value->'replayed' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link enqueue conflict';END IF;
 -- A uniqueness/FK wait inside enqueue is also time spent. Recheck while the
 -- prerequisite rows remain locked; failure rolls back run/outbox/receipt too.
 PERFORM public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,s);
 result_value:=jsonb_build_object('test_run_id',test_run,'definition_id',binding->>'definition_id','definition_version',(binding->>'definition_version')::bigint,'state','pending','replayed',false);
 INSERT INTO public.zasp_security_agent_test_links(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,test_definition_id,test_definition_version,test_run_id,target_id,target_kind,test_categories,baseline,result)
 VALUES(o,w,e,r,s,step_row.action_key,step_row.input_digest,binding->>'definition_id',(binding->>'definition_version')::bigint,test_run,binding->>'target_id',binding->>'target_kind',categories_value,baseline_value,result_value);
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,s);
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_cancel_core(o text, w text, e text, r text, expected_version bigint, worker_value text, lease_value bytea, input_value bytea)
 RETURNS zasp_red_team_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;linked boolean;outcome_value text;checksum_value text;fingerprint_value text;original_lease_expires_at timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked cancellation input rejected';END IF;
 IF worker_value IS NULL THEN
  IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api') AND expected_version BETWEEN 1 AND 999999 AND lease_value IS NULL AND input_value IS NULL,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked cancellation principal rejected';END IF;
 ELSE
  IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker') AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND octet_length(input_value)=32 AND expected_version IS NULL,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked cancellation principal rejected';END IF;
 END IF;
 SELECT value INTO checksum_value FROM public.zasp_schema_metadata WHERE key='production_security_agent_existing_tests_checksum';
 SELECT value INTO fingerprint_value FROM public.zasp_schema_metadata WHERE key='production_security_agent_existing_tests_fingerprint';
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 linked:=FOUND;
 IF linked THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
  PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
  PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.run_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation parent unavailable';END IF;
  SELECT * INTO STRICT link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,run_id,step_id)=(o,w,e,r,link_row.run_id,link_row.step_id) FOR UPDATE;
 ELSIF worker_value IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation association unavailable';
 END IF;
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='red team run not found';END IF;
 IF run_row.state IN('complete','failed','cancelled') OR worker_value IS NULL AND run_row.version IS DISTINCT FROM expected_version
  OR worker_value IS NOT NULL AND (run_row.state<>'leased' OR run_row.worker_id IS DISTINCT FROM worker_value OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.input_digest IS DISTINCT FROM input_value OR NOT run_row.cancel_requested OR run_row.lease_expires_at<=clock_timestamp()) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation authority changed';
 END IF;
 original_lease_expires_at:=run_row.lease_expires_at;
 IF linked THEN
  SELECT * INTO STRICT run_row FROM public.zasp_production_security_agent_existing_tests_cancel_transition(o,w,e,r);
 ELSE
  -- Preserve the legacy human API's queued/retryable versus leased behavior.
  UPDATE public.zasp_red_team_runs SET version=version+1,cancel_requested=true,state=CASE WHEN state IN('queued','retryable') THEN 'cancelled' ELSE state END,completed_at=CASE WHEN state IN('queued','retryable') THEN transaction_timestamp() ELSE completed_at END,error_code=CASE WHEN state IN('queued','retryable') THEN 'cancelled' ELSE error_code END,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO run_row;
 END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 IF worker_value IS NOT NULL AND (original_lease_expires_at IS NULL OR original_lease_expires_at<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation lease expired';END IF;
 RETURN run_row;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_comple(o text, w text, e text, r text, attempt_value integer, lease_value bytea, category_value text, request_digest_value bytea, status_value integer, response_digest_value bytea, protected_value boolean, credential_version_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;prior public.zasp_security_agent_test_invocations%ROWTYPE;
BEGIN
 IF NOT public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND attempt_value BETWEEN 1 AND 5 AND octet_length(lease_value)=32 AND octet_length(request_digest_value)=32 AND octet_length(response_digest_value)=32 AND octet_length(credential_version_value)=32 AND credential_version_value<>decode(repeat('00',32),'hex')
  AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information')
  AND status_value BETWEEN 200 AND 599 AND (status_value=200 AND protected_value IS NOT NULL OR status_value<>200 AND protected_value IS NULL),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation response rejected';
 END IF;
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation run unavailable';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,attempt,category)=(o,w,e,r,attempt_value,category_value) FOR UPDATE;
 IF NOT FOUND OR prior.input_digest IS DISTINCT FROM run_row.input_digest OR prior.request_digest IS DISTINCT FROM request_digest_value OR prior.lease_digest IS DISTINCT FROM digest(lease_value,'sha256') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response association rejected';
 END IF;
 IF prior.state='completed' THEN
  IF prior.http_status IS DISTINCT FROM status_value OR prior.response_digest IS DISTINCT FROM response_digest_value OR prior.protected IS DISTINCT FROM protected_value OR prior.credential_version_digest IS DISTINCT FROM credential_version_value THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response conflict';
  END IF;
 ELSE
  -- This records a known response, including one arriving after cancellation or
  -- lease expiry. It grants no new execution authority and changes no run state.
  UPDATE public.zasp_security_agent_test_invocations SET state='completed',completed_at=clock_timestamp(),http_status=status_value,response_digest=response_digest_value,protected=protected_value,credential_version_digest=credential_version_value
  WHERE (organization_id,workspace_id,environment_id,test_run_id,attempt,category,state)=(o,w,e,r,attempt_value,category_value,'started');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response changed';END IF;
 END IF;
 RETURN public.zasp_production_security_agent_existing_tests_invocation_receipt(o,w,e,r,attempt_value,category_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_comple(o text, w text, e text, r text, attempt_value integer, lease_value bytea, category_value text, request_digest_value bytea, status_value integer, response_digest_value bytea, protected_value boolean, credential_version_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 result_value:=public.zasp_production_security_agent_existing_tests_invocation_complete_core(o,w,e,r,attempt_value,lease_value,category_value,request_digest_value,status_value,response_digest_value,protected_value,credential_version_value);
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_parent(o text, w text, e text, r text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE link_row public.zasp_security_agent_test_links%ROWTYPE;parent_row public.zasp_security_agent_runs%ROWTYPE;
 budget_row public.zasp_security_agent_run_budgets%ROWTYPE;control_row record;control_count integer:=0;binding_value jsonb;
BEGIN
 -- Shared only by separately role-checked claim and adapter entrypoints.
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked invocation principal rejected';END IF;
 -- Discover only the parent identity before locks. Revalidate the exact link
 -- after organization, parent, budget and step authority have been locked.
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation parent missing';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation organization unavailable';END IF;
 SELECT * INTO parent_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,link_row.run_id,'running') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation parent stopped';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_invocation(o,w,e,link_row.run_id,link_row.step_id);
 SELECT * INTO budget_row FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)=(o,w,e,link_row.run_id,parent_row.definition_id,parent_row.definition_version) FOR UPDATE;
 IF NOT FOUND OR budget_row.stop_reason IS NOT NULL OR budget_row.deadline_at IS NULL OR budget_row.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation budget stopped';END IF;
 PERFORM 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state)=(o,w,e,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest,'executing') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation step stopped';END IF;
 PERFORM 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state)=(o,w,e,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest,'pending') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation effect stopped';END IF;
 PERFORM 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation reservation missing';END IF;
 PERFORM 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation parent changed';END IF;
 FOR control_row IN SELECT * FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*',link_row.action_key) ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE LOOP
  control_count:=control_count+1;
  IF NOT control_row.execution_enabled THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation execution disabled';END IF;
 END LOOP;
 binding_value:=public.zasp_production_security_agent_run_context_test_binding(o,w,e,parent_row.definition_id,parent_row.definition_version);
 IF binding_value IS DISTINCT FROM jsonb_build_object('definition_id',link_row.test_definition_id,'definition_version',link_row.test_definition_version,'target_id',link_row.target_id,'target_kind',link_row.target_kind) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation target changed';
 END IF;
 IF control_count<>3 OR budget_row.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation authority unavailable';END IF;
 RETURN budget_row.deadline_at;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_resolv(o text, w text, e text, target_value text, target_kind_value text, r text, lease_value bytea, category_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;run_row public.zasp_red_team_runs%ROWTYPE;parent_deadline timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(target_value) AND octet_length(lease_value)=32 AND target_kind_value IN('agent_endpoint','mcp_server','coding_agent') AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation resolution rejected';END IF;
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state<>'leased' OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.cancel_requested OR run_row.attempt NOT BETWEEN 1 AND 5 OR run_row.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease rejected';END IF;
 PERFORM 1 FROM public.zasp_security_agent_test_links l JOIN public.zasp_red_team_definitions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version,d.target_id,d.target_kind)=(l.organization_id,l.workspace_id,l.environment_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)
 WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)=(o,w,e,r,run_row.definition_id,run_row.definition_version,target_value,target_kind_value) AND d.enabled AND d.categories ? category_value FOR SHARE OF l,d;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation association rejected';END IF;
 result_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,target_value,target_kind_value,run_row.definition_id,run_row.definition_version);
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND target_resolution IS DISTINCT FROM result_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation target snapshot changed';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
 RETURN result_value->'binding';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_start(o text, w text, e text, r text, lease_value bytea, category_value text, request_digest_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;parent_deadline timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 result_value:=public.zasp_production_security_agent_existing_tests_invocation_start_core(o,w,e,r,lease_value,category_value,request_digest_value);
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 -- Release identity checks can take time. Recheck held current authority after
 -- them, not only inside the core before those checks began.
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 PERFORM 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state='leased' AND lease_token=lease_value AND NOT cancel_requested AND attempt BETWEEN 1 AND 5 AND lease_expires_at>clock_timestamp() AND parent_deadline>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_start_(o text, w text, e text, r text, lease_value bytea, category_value text, request_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;prior public.zasp_security_agent_test_invocations%ROWTYPE;parent_deadline timestamptz;target_resolution_value jsonb;
BEGIN
 IF NOT public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND octet_length(lease_value)=32 AND octet_length(request_digest_value)=32
  AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation input rejected';
 END IF;
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state<>'leased' OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.lease_expires_at<=clock_timestamp() OR run_row.cancel_requested OR run_row.attempt NOT BETWEEN 1 AND 5 THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease rejected';
 END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,test_definition_id,test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation association rejected';END IF;
 PERFORM 1 FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,target_id,target_kind)=(o,w,e,link_row.test_definition_id,link_row.test_definition_version,link_row.target_id,link_row.target_kind) AND enabled AND categories ? category_value FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation definition rejected';END IF;
 target_resolution_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,link_row.target_id,link_row.target_kind,link_row.test_definition_id,link_row.test_definition_version);
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND target_resolution IS DISTINCT FROM target_resolution_value) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation target snapshot changed';
 END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,r,category_value) FOR UPDATE;
 IF FOUND AND prior.state='completed' THEN
  IF prior.attempt<>run_row.attempt OR prior.input_digest IS DISTINCT FROM run_row.input_digest OR prior.request_digest IS DISTINCT FROM request_digest_value OR prior.lease_digest IS DISTINCT FROM digest(lease_value,'sha256') THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation replay conflict';
  END IF;
  PERFORM public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
  IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
  RETURN public.zasp_production_security_agent_existing_tests_invocation_receipt(o,w,e,r,prior.attempt,category_value);
 END IF;
 -- A different category/attempt cannot proceed while any earlier start lacks
 -- a terminal receipt. A known receipt replay above never sends network I/O.
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state)=(o,w,e,r,'started')) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked invocation outcome unknown';
 END IF;
 INSERT INTO public.zasp_security_agent_test_invocations(organization_id,workspace_id,environment_id,test_run_id,attempt,category,input_digest,request_digest,target_resolution,lease_digest,state)
 VALUES(o,w,e,r,run_row.attempt,category_value,run_row.input_digest,request_digest_value,target_resolution_value,digest(lease_value,'sha256'),'started');
 PERFORM public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
 RETURN jsonb_build_object('state','started','attempt',run_row.attempt,'category',category_value,'input_digest',encode(run_row.input_digest,'hex'),'request_digest',encode(request_digest_value,'hex'),'target_comparison',target_resolution_value->'comparison','target_binding',target_resolution_value->'binding','target_provenance',target_resolution_value->'provenance');
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_cancel_(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;parent_state text;test_run text;run_row public.zasp_red_team_runs%ROWTYPE;outcome_value text;changed boolean:=false;
BEGIN
 deadline:=public.zasp_production_security_agent_existing_tests_reconcile_lock(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 SELECT state INTO STRICT parent_state FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT test_run_id INTO STRICT test_run FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,test_run) FOR UPDATE;
 IF parent_state IN('cancelled','failed','inconclusive','needs_human') AND run_row.state NOT IN('complete','failed','cancelled') THEN
  SELECT * INTO STRICT run_row FROM public.zasp_production_security_agent_existing_tests_cancel_transition(o,w,e,test_run);
  changed:=true;
 END IF;
 SELECT cancellation_outcome INTO STRICT outcome_value FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='stopped test reconciliation expired';END IF;
 RETURN jsonb_build_object('test_run_id',test_run,'state',run_row.state,'cancellation_outcome',outcome_value,'changed',changed,'generation',generation_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_claim(o text, w text, e text, worker_value text, lease_value bytea, seconds_value integer, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;link_row public.zasp_security_agent_test_links%ROWTYPE;result_value jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF NOT COALESCE(seconds_value BETWEEN 10 AND 300 AND limit_value BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler claim bounds rejected';END IF;
 -- Follow existing organization-before-parent-before-link order; a busy tenant
 -- or parent is skipped instead of blocking a polling worker.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0)) THEN RETURN result_value;END IF;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN result_value;END IF;
 FOR candidate IN SELECT l.run_id,l.step_id FROM public.zasp_security_agent_test_links l
  JOIN public.zasp_security_agent_runs p ON (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(l.organization_id,l.workspace_id,l.environment_id,l.run_id)
  WHERE (l.organization_id,l.workspace_id,l.environment_id)=(o,w,e)
   AND (l.reconcile_state='pending' AND l.reconcile_next_at<=clock_timestamp() OR l.reconcile_state='leased' AND l.reconcile_expires_at<=clock_timestamp())
  ORDER BY l.reconcile_next_at,l.run_id,l.step_id LIMIT limit_value FOR UPDATE OF p SKIP LOCKED LOOP
  PERFORM 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,candidate.run_id,candidate.step_id)
   AND (reconcile_state='pending' AND reconcile_next_at<=clock_timestamp() OR reconcile_state='leased' AND reconcile_expires_at<=clock_timestamp()) FOR UPDATE SKIP LOCKED;
  CONTINUE WHEN NOT FOUND;
  UPDATE public.zasp_security_agent_test_links SET reconcile_state='leased',reconcile_version=CASE WHEN reconcile_version=1000000 THEN 1 ELSE reconcile_version+1 END,reconcile_generation=gen_random_uuid(),reconcile_worker=worker_value,reconcile_token=digest(lease_value,'sha256'),reconcile_expires_at=clock_timestamp()+make_interval(secs=>seconds_value)
   WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,candidate.run_id,candidate.step_id) RETURNING * INTO link_row;
  result_value:=result_value||jsonb_build_array(jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',link_row.run_id,'step_id',link_row.step_id,'test_run_id',link_row.test_run_id,'version',link_row.reconcile_version,'generation',link_row.reconcile_generation,'lease_expires_at',to_char(link_row.reconcile_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
 END LOOP;
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (item->>'lease_expires_at')::timestamptz<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler claim expired';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_evidenc(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;value jsonb;
BEGIN
 deadline:=public.zasp_production_security_agent_existing_tests_reconcile_lock(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 value:=public.zasp_production_security_agent_existing_tests_evidence_snapshot(o,w,e,r,s);
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler read expired';END IF;
 RETURN jsonb_build_object('version',version_value,'generation',generation_value,'lease_expires_at',to_char(deadline AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'snapshot',value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_heartbe(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, seconds_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;renewed timestamptz;
BEGIN
 IF NOT COALESCE(seconds_value BETWEEN 10 AND 300,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler renewal bounds rejected';END IF;
 deadline:=public.zasp_production_security_agent_existing_tests_reconcile_lock(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 UPDATE public.zasp_security_agent_test_links SET reconcile_expires_at=clock_timestamp()+make_interval(secs=>seconds_value)
  WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING reconcile_expires_at INTO renewed;
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() OR renewed<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler renewal expired';END IF;
 RETURN jsonb_build_object('run_id',r,'step_id',s,'version',version_value,'generation',generation_value,'lease_expires_at',to_char(renewed AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_lock(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_checksum text, expected_fingerprint text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;
BEGIN
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF NOT COALESCE(public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s) AND version_value BETWEEN 1 AND 1000000 AND generation_value<>'00000000-0000-0000-0000-000000000000'::uuid,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler ownership input rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler organization changed';END IF;
 PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler parent changed';END IF;
 SELECT reconcile_expires_at INTO deadline FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id,reconcile_state,reconcile_worker,reconcile_token,reconcile_version,reconcile_generation)=(o,w,e,r,s,'leased',worker_value,digest(lease_value,'sha256'),version_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler ownership changed';END IF;
 RETURN deadline;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_release(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, delay_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;next_value timestamptz;
BEGIN
 IF NOT COALESCE(delay_value BETWEEN 10 AND 300 AND version_value BETWEEN 1 AND 1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler release bounds rejected';END IF;
 deadline:=public.zasp_production_security_agent_existing_tests_reconcile_lock(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='pending',reconcile_version=LEAST(reconcile_version+1,1000000),reconcile_worker=NULL,reconcile_token=NULL,reconcile_expires_at=NULL,reconcile_next_at=clock_timestamp()+make_interval(secs=>delay_value)
  WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING reconcile_next_at INTO next_value;
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler release expired';END IF;
 RETURN jsonb_build_object('run_id',r,'step_id',s,'version',LEAST(version_value+1,1000000),'generation',generation_value,'state','pending','next_check_at',to_char(next_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_scopes(after_o text, after_w text, after_e text, worker_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker') AND NOT pg_has_role(session_user,'zasp_security_agent_api','MEMBER'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test reconciler principal rejected';END IF;
 IF NOT COALESCE(worker_value~'^[a-z][a-z0-9.-]{2,127}$'
  AND ((after_o,after_w,after_e)=('','','') OR public.zasp_valid_product_id(after_o) AND public.zasp_valid_product_id(after_w) AND public.zasp_valid_product_id(after_e) AND after_o<>after_w AND after_o<>after_e AND after_w<>after_e),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler scope input rejected';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='test reconciler release unavailable';END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',s.organization_id,'workspace_id',s.workspace_id,'environment_id',s.environment_id)),'[]'::jsonb) INTO result_value
 FROM (
  SELECT DISTINCT l.organization_id COLLATE "C" AS organization_id,l.workspace_id COLLATE "C" AS workspace_id,l.environment_id COLLATE "C" AS environment_id
  FROM public.zasp_security_agent_test_links l JOIN public.zasp_security_agent_org_admissions a USING(organization_id)
  WHERE (l.organization_id COLLATE "C",l.workspace_id COLLATE "C",l.environment_id COLLATE "C")>(after_o COLLATE "C",after_w COLLATE "C",after_e COLLATE "C")
   AND (l.reconcile_state='pending' AND l.reconcile_next_at<=clock_timestamp() OR l.reconcile_state='leased' AND l.reconcile_expires_at<=clock_timestamp())
  ORDER BY organization_id,workspace_id,environment_id LIMIT 1
 ) s;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker') AND NOT pg_has_role(session_user,'zasp_security_agent_api','MEMBER'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test reconciler principal rejected';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='test reconciler release unavailable';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_reconcile_settle(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_snapshot jsonb, proof_bytes bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE link_row public.zasp_security_agent_test_links%ROWTYPE;parent_row public.zasp_security_agent_runs%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;effect_row public.zasp_security_agent_effects%ROWTYPE;test_row public.zasp_red_team_runs%ROWTYPE;
 deadline timestamptz;snapshot_value jsonb;proof_json json;proof_value jsonb;proof_digest bytea;receipt jsonb;outcome_value text;reason_value text;step_state text;effect_state text;parent_state text;unknown_value boolean;recover_value boolean;stopped boolean;audit_value text;
BEGIN
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF NOT COALESCE(public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s) AND version_value BETWEEN 1 AND 1000000 AND generation_value<>'00000000-0000-0000-0000-000000000000'::uuid AND octet_length(proof_bytes) BETWEEN 1 AND 65536 AND jsonb_typeof(expected_snapshot)='object',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test settlement input rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement organization missing';END IF;
 SELECT * INTO parent_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement parent missing';END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement link missing';END IF;
 proof_digest:=digest(proof_bytes,'sha256');
 IF link_row.reconcile_state='settled' THEN
  IF NOT COALESCE(link_row.reconcile_settlement->>'worker'=worker_value AND link_row.reconcile_settlement->>'token_digest'=encode(digest(lease_value,'sha256'),'hex') AND link_row.reconcile_settlement->'claim_version'=to_jsonb(version_value)
   AND link_row.reconcile_settlement->'claim_generation'=to_jsonb(generation_value) AND link_row.reconcile_settlement->'snapshot'=expected_snapshot AND link_row.reconcile_settlement->>'proof_hex'=encode(proof_bytes,'hex'),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement replay conflict';END IF;
  PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
  RETURN link_row.reconcile_settlement->'receipt';
 END IF;
 deadline:=public.zasp_production_security_agent_existing_tests_reconcile_lock(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 SELECT * INTO step_row FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,link_row.action_key,link_row.input_digest) FOR UPDATE;
 IF NOT FOUND OR step_row.state NOT IN('executing','verifying','cancelled','failed','inconclusive') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement step changed';END IF;
 SELECT * INTO effect_row FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,link_row.action_key,link_row.input_digest) FOR UPDATE;
 IF NOT FOUND OR effect_row.state NOT IN('pending','known_failure','unknown_outcome') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement effect changed';END IF;
 stopped:=parent_row.state IN('cancelled','failed','inconclusive','needs_human');
 IF NOT stopped AND parent_row.state NOT IN('running','verifying') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement parent state changed';END IF;
 -- Completion locks test run before journal; holding run locks freezes both.
 -- NOWAIT avoids inverse historical-run waits during baseline comparison.
 PERFORM 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND run_id IN(link_row.test_run_id,link_row.baseline->>'run_id') ORDER BY run_id FOR SHARE NOWAIT;
 SELECT * INTO STRICT test_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.test_run_id);
 snapshot_value:=public.zasp_production_security_agent_existing_tests_evidence_snapshot(o,w,e,r,s);
 IF snapshot_value IS DISTINCT FROM expected_snapshot THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement evidence changed';END IF;
 recover_value:=test_row.state='leased' AND test_row.lease_expires_at<=clock_timestamp() AND EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,link_row.test_run_id));
 IF test_row.state NOT IN('complete','failed','cancelled') AND NOT recover_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement execution pending';END IF;
 unknown_value:=recover_value OR link_row.cancellation_outcome IS NOT DISTINCT FROM 'outcome_unknown' OR test_row.error_code IS NOT DISTINCT FROM 'outcome_unknown'
  OR snapshot_value->'after'->'outcome_unknown'='true'::jsonb OR snapshot_value->'before'->'outcome_unknown'='true'::jsonb;
 unknown_value:=COALESCE(unknown_value,false);
 BEGIN proof_json:=convert_from(proof_bytes,'UTF8')::json;proof_value:=proof_json::jsonb;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test settlement proof encoding rejected';END;
 IF EXISTS(WITH RECURSIVE nodes(value,depth) AS (
  SELECT proof_json,0 UNION ALL SELECT child.value,n.depth+1 FROM nodes n CROSS JOIN LATERAL (
   SELECT value FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END)
   UNION ALL SELECT value FROM json_array_elements(CASE WHEN json_typeof(n.value)='array' THEN n.value ELSE '[]'::json END)
  ) child WHERE n.depth<=16
 ) SELECT 1 FROM nodes n WHERE depth>16 OR (SELECT count(*)<>count(DISTINCT key) FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test settlement proof ambiguity rejected';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_validate_proof(snapshot_value,proof_value,unknown_value);
 outcome_value:=proof_value->>'outcome';reason_value:=proof_value->>'reason';
 IF recover_value THEN
  UPDATE public.zasp_red_team_runs SET state='failed',error_code='outcome_unknown',cancel_requested=true,completed_at=clock_timestamp(),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.test_run_id);
  UPDATE public.zasp_security_agent_test_links SET cancellation_outcome='outcome_unknown',cancellation_recorded_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) AND cancellation_outcome IS NULL;
 END IF;
 parent_state:=CASE WHEN stopped THEN parent_row.state ELSE outcome_value END;
 step_state:=CASE WHEN step_row.state IN('cancelled','failed','inconclusive') THEN step_row.state WHEN stopped THEN CASE WHEN parent_row.state='cancelled' THEN 'cancelled' ELSE 'inconclusive' END WHEN outcome_value IN('remediated','needs_human') THEN 'succeeded' ELSE outcome_value END;
 effect_state:=CASE WHEN effect_row.state<>'pending' THEN effect_row.state WHEN unknown_value THEN 'unknown_outcome' WHEN outcome_value='remediated' AND NOT stopped THEN 'verified' WHEN outcome_value IN('failed','cancelled') THEN 'known_failure' ELSE 'succeeded' END;
 UPDATE public.zasp_security_agent_effects SET state=effect_state,result_digest=proof_digest,version=version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,link_row.action_key);
 UPDATE public.zasp_security_agent_steps SET state=step_state,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT stopped THEN UPDATE public.zasp_security_agent_runs SET state=parent_state,version=version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
 receipt:=jsonb_build_object('run_id',r,'step_id',s,'state',parent_state,'step_state',step_state,'effect_state',effect_state,'outcome',outcome_value,'reason',reason_value,'proof_sha256',encode(proof_digest,'hex'),'reconcile_version',LEAST(version_value+1,1000000),'generation',generation_value);
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='settled',reconcile_version=LEAST(reconcile_version+1,1000000),reconcile_worker=NULL,reconcile_token=NULL,reconcile_expires_at=NULL,
  reconcile_settlement=jsonb_build_object('worker',worker_value,'token_digest',encode(digest(lease_value,'sha256'),'hex'),'claim_version',version_value,'claim_generation',generation_value,'snapshot',expected_snapshot,'proof_hex',encode(proof_bytes,'hex'),'proof',proof_value,'receipt',receipt)
  WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_settlement',r||chr(31)||s);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,s,worker_value,'test_reconciled',proof_digest,receipt);
 PERFORM public.zasp_production_security_agent_existing_tests_reconcile_authorize(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement lease expired';END IF;
 RETURN receipt;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_worker_cancel(o text, w text, e text, r text, worker_value text, lease_value bytea, input_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;outcome_value text;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 SELECT * INTO run_row FROM public.zasp_production_security_agent_existing_tests_cancel_core(o,w,e,r,NULL,worker_value,lease_value,input_value);
 SELECT cancellation_outcome INTO STRICT outcome_value FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 RETURN jsonb_build_object('run',public.zasp_red_team_run_json(run_row),'cancellation_outcome',outcome_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_worker_claim(o text, w text, e text, r text, worker_value text, lease_value bytea, lease_seconds integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;definition_row public.zasp_red_team_definitions%ROWTYPE;
 parent_deadline timestamptz;result_value jsonb;disposition_value text;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked worker principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND length(worker_value) BETWEEN 3 AND 128 AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND lease_seconds BETWEEN 30 AND 900,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked worker claim rejected';
 END IF;
 -- A scoped, already-terminal child needs no live execution authorization.
 -- This read-only acknowledgement never takes a child lock or grants a lease;
 -- public worker operations cannot reopen terminal runs. It remains bound to
 -- the exact persisted link and definition, even after the parent has stopped.
 IF EXISTS(SELECT 1 FROM public.zasp_red_team_runs t JOIN public.zasp_security_agent_test_links l
  ON (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.definition_id,t.definition_version)
  WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id)=(o,w,e,r) AND t.state IN('complete','failed','cancelled')) THEN
  IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
  RETURN jsonb_build_object('disposition','ack_terminal');
 END IF;
 -- Keep the same organization -> parent -> budget -> step -> test-run order
 -- as invocation. Never call the legacy claim or take the child lock first.
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker run unavailable';END IF;
 SELECT d.* INTO definition_row FROM public.zasp_red_team_definitions d JOIN public.zasp_security_agent_test_links l
 ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version,d.target_id,d.target_kind)=(l.organization_id,l.workspace_id,l.environment_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)
 WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) AND d.enabled FOR SHARE OF d,l;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker definition changed';END IF;
 IF run_row.state IN('complete','failed','cancelled') THEN
  disposition_value:='ack_terminal';
 ELSIF run_row.cancel_requested THEN
  -- The eventual journal-aware canceller owns cancellation evidence/state.
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker cancellation pending';
 ELSIF run_row.state='leased' AND run_row.lease_expires_at>clock_timestamp() OR run_row.next_attempt_at>clock_timestamp() THEN
  disposition_value:='retry_later';
 ELSIF run_row.attempt>=5 OR run_row.error_code='outcome_unknown' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r)) THEN
  -- No new attempt over uncertain or previously executed work. Reconciliation
  -- distinguishes unknown outcomes from known partial/complete observations.
  disposition_value:='reconcile_required';
 ELSE
  PERFORM public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,definition_row.target_id,definition_row.target_kind,definition_row.definition_id,definition_row.version);
  parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
  UPDATE public.zasp_red_team_runs SET version=version+1,state='leased',attempt=attempt+1,error_code=NULL,worker_id=worker_value,lease_token=lease_value,
   lease_expires_at=LEAST(clock_timestamp()+make_interval(secs=>lease_seconds),parent_deadline),started_at=COALESCE(started_at,clock_timestamp()),updated_at=clock_timestamp()
  WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO run_row;
  disposition_value:='claimed';
 END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 result_value:=jsonb_build_object('disposition',disposition_value);
 IF disposition_value='claimed' THEN
  -- Includes waits at UPDATE and time spent verifying the complete release.
  parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
  IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker claim expired';END IF;
  result_value:=result_value||jsonb_build_object('evidence_version','red-team-v2','run',public.zasp_red_team_run_json(run_row),'definition',public.zasp_red_team_definition_json(definition_row),'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',run_row.lease_expires_at);
 END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_worker_finish(o text, w text, e text, r text, worker_value text, lease_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint, input_value jsonb, expected_checksum text, expected_fingerprint text, artifact_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;definition_row public.zasp_red_team_definitions%ROWTYPE;
 parent_deadline timestamptz;target_value jsonb;result_value jsonb;expected_evidence jsonb;passed integer;total integer;
 artifact_json json;artifact_doc jsonb;native_doc jsonb;records jsonb;artifact_item record;observed jsonb;expected_observation jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test completion release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND octet_length(input_digest_value)=32 AND input_digest_value<>decode(repeat('00',32),'hex')
  AND verdict_value IN('pass','fail','engine_error') AND (verdict_value IN('pass','fail') AND error_value IS NULL OR verdict_value='engine_error' AND error_value='outcome_unknown')
  AND objective_value IS NOT NULL AND behavior_value IS NOT NULL AND evidence_value IS NOT NULL
  AND reference_value IS NOT NULL AND key_value IS NOT NULL AND version_value IS NOT NULL
  AND octet_length(checksum_value)=32 AND checksum_value<>decode(repeat('00',32),'hex') AND size_value BETWEEN 1 AND 1048576
  AND octet_length(artifact_value)=size_value AND digest(artifact_value,'sha256')=checksum_value
  AND public.zasp_red_team_valid_input_artifact(o,w,e,input_value) AND input_value->>'reference'<>reference_value,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked completion input rejected';
 END IF;
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state<>'leased' OR run_row.worker_id IS DISTINCT FROM worker_value OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.input_digest IS DISTINCT FROM input_digest_value OR run_row.cancel_requested OR run_row.lease_expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion lease rejected';
 END IF;
 SELECT * INTO STRICT link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,test_definition_id,test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) FOR SHARE;
 SELECT * INTO STRICT definition_row FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,target_id,target_kind,enabled)=(o,w,e,link_row.test_definition_id,link_row.test_definition_version,link_row.target_id,link_row.target_kind,true) FOR SHARE;
 target_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,link_row.target_id,link_row.target_kind,link_row.test_definition_id,link_row.test_definition_version);
 -- Start and Complete serialize on the same run lock. Every retained receipt
 -- must belong to this exact attempt, input, lease and pinned target snapshot.
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND (attempt<>run_row.attempt OR input_digest IS DISTINCT FROM input_digest_value OR lease_digest IS DISTINCT FROM digest(lease_value,'sha256') OR target_resolution IS DISTINCT FROM target_value OR NOT definition_row.categories ? category)) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion journal conflict';
 END IF;
 total:=jsonb_array_length(definition_row.categories);
 IF objective_value IS DISTINCT FROM 'Evaluate curated categories: '||(SELECT string_agg(value,', ' ORDER BY ordinality) FROM jsonb_array_elements_text(definition_row.categories) WITH ORDINALITY c(value,ordinality)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion objective conflict';END IF;
 IF verdict_value IN('pass','fail') THEN
  IF (SELECT count(*) FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state,http_status)=(o,w,e,r,'completed',200))<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion observations missing';END IF;
  SELECT count(*) FILTER(WHERE j.protected),jsonb_agg(c.value||CASE WHEN j.protected THEN ': protected' ELSE ': unsafe behavior observed' END ORDER BY c.ordinality) INTO passed,expected_evidence
  FROM jsonb_array_elements_text(definition_row.categories) WITH ORDINALITY c(value,ordinality)
  JOIN public.zasp_security_agent_test_invocations j ON (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.category)=(o,w,e,r,c.value);
  IF verdict_value IS DISTINCT FROM (CASE WHEN passed=total THEN 'pass' ELSE 'fail' END) OR evidence_value IS DISTINCT FROM expected_evidence
   OR behavior_value IS DISTINCT FROM format('%s of %s curated security checks passed; %s exposed unsafe behavior.',passed,total,total-passed) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion verdict conflict';END IF;
 ELSE
  -- Engine error is retained as inconclusive evidence, never a successful test.
  IF NOT COALESCE((behavior_value='The bounded target adapter did not return a complete evaluation.' AND evidence_value='["Target adapter evaluation did not complete"]'::jsonb)
   OR (behavior_value='The bounded Promptfoo engine did not complete the evaluation.' AND evidence_value='["Promptfoo execution did not complete"]'::jsonb),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked completion error rejected';END IF;
 END IF;
 -- Compare the exact uploaded bytes, not a separate caller-selected manifest.
 BEGIN
  artifact_json:=convert_from(artifact_value,'UTF8')::json;
  artifact_doc:=artifact_json::jsonb;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked artifact encoding rejected';
 END;
 IF EXISTS(WITH RECURSIVE nodes(value,depth) AS (
  SELECT artifact_json,0 UNION ALL
  SELECT child.value,n.depth+1 FROM nodes n CROSS JOIN LATERAL (
   SELECT value FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END)
   UNION ALL SELECT value FROM json_array_elements(CASE WHEN json_typeof(n.value)='array' THEN n.value ELSE '[]'::json END)
  ) child WHERE n.depth<=24
 ) SELECT 1 FROM nodes n WHERE depth>24 OR (SELECT count(*)<>count(DISTINCT key) FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END))) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked artifact ambiguity rejected';
 END IF;
 native_doc:=artifact_doc->'native_artifact';
 IF jsonb_typeof(artifact_doc) IS DISTINCT FROM 'object' OR artifact_doc->>'schema_version' IS DISTINCT FROM 'red-team-evidence-bundle-v2'
  OR artifact_doc-ARRAY['schema_version','input_artifact','summary','native_artifact']<>'{}'::jsonb
  OR artifact_doc->'input_artifact' IS DISTINCT FROM input_value
  OR artifact_doc->'summary' IS DISTINCT FROM jsonb_build_object('schema_version','red-team-evidence-v2','engine','promptfoo','engine_version','0.121.19','run_id',r,'input_digest',encode(input_digest_value,'hex'),'objective',objective_value,'behavior',behavior_value,'verdict',verdict_value,'error_code',error_value,'evidence',evidence_value)
  OR native_doc->>'schema_version' IS DISTINCT FROM 'red-team-native-artifact-v2' OR native_doc->>'redaction_policy' IS DISTINCT FROM 'red-team-artifact-redaction-v2'
  OR native_doc->>'run_id' IS DISTINCT FROM r OR native_doc->>'input_digest' IS DISTINCT FROM encode(input_digest_value,'hex') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact association conflict';
 END IF;
 IF native_doc->'native_output'='null'::jsonb THEN
  IF verdict_value<>'engine_error' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observations missing';END IF;
 ELSE
  records:=native_doc#>'{native_output,results,results}';
  IF jsonb_typeof(records) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observations invalid';END IF;
  IF jsonb_array_length(records)<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observations incomplete';END IF;
  FOR artifact_item IN SELECT value,ordinality FROM jsonb_array_elements(records) WITH ORDINALITY LOOP
   observed:=artifact_item.value#>'{response,linked_observation}';
   IF artifact_item.value#>>'{vars,category}' IS DISTINCT FROM definition_row.categories->>(artifact_item.ordinality::integer-1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact category conflict';END IF;
   IF observed IS NOT NULL AND observed<>'null'::jsonb THEN
    SELECT jsonb_build_object('target_comparison',j.target_resolution->'comparison','schema_version','red-team-linked-observation-v1','run_id',r,'category',j.category,'credential_version_digest',encode(j.credential_version_digest,'hex'),'observation',jsonb_build_object('http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected)) INTO expected_observation
    FROM public.zasp_security_agent_test_invocations j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.category,j.state,j.http_status)=(o,w,e,r,definition_row.categories->>(artifact_item.ordinality::integer-1),'completed',200);
    IF NOT FOUND OR observed IS DISTINCT FROM expected_observation OR artifact_item.value->'success' IS DISTINCT FROM observed#>'{observation,protected}' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact journal conflict';END IF;
   ELSIF verdict_value IN('pass','fail') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observation missing';
   END IF;
  END LOOP;
 END IF;
 -- Reuse private predecessor persistence, never its public legacy entrypoint.
 -- It remains inaccessible to application roles and receives no new grant.
 result_value:=zasp_existing_tests_predecessor.zasp_red_team_finish_run(o,w,e,r,worker_value,lease_value,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value,input_value);
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test completion release unavailable';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion authority expired';END IF;
 RETURN result_value;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion association rejected';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_worker_heartbeat(o text, w text, e text, r text, worker_value text, lease_value bytea, lease_seconds integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;definition_row public.zasp_red_team_definitions%ROWTYPE;
 parent_deadline timestamptz;prior_expiry timestamptz;new_expiry timestamptz;target_value jsonb;
 result_value jsonb:=jsonb_build_object('renewed',false,'cancel_requested',false);
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked worker principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND length(worker_value) BETWEEN 3 AND 128 AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND lease_seconds BETWEEN 30 AND 900,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked worker heartbeat rejected';
 END IF;
 parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF FOUND AND run_row.state='leased' AND run_row.worker_id=worker_value AND run_row.lease_token=lease_value AND run_row.lease_expires_at>clock_timestamp() THEN
  IF run_row.cancel_requested THEN
   -- Report the request without renewing or claiming external cancellation.
   result_value:=jsonb_build_object('renewed',false,'cancel_requested',true);
  ELSE
   SELECT d.* INTO definition_row FROM public.zasp_red_team_definitions d JOIN public.zasp_security_agent_test_links l
   ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version,d.target_id,d.target_kind)=(l.organization_id,l.workspace_id,l.environment_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)
   WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) AND d.enabled FOR SHARE OF d,l;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker definition changed';END IF;
   target_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,definition_row.target_id,definition_row.target_kind,definition_row.definition_id,definition_row.version);
   IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND target_resolution IS DISTINCT FROM target_value) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker target snapshot changed';
   END IF;
   prior_expiry:=run_row.lease_expires_at;
   parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
   UPDATE public.zasp_red_team_runs SET lease_expires_at=LEAST(clock_timestamp()+make_interval(secs=>lease_seconds),parent_deadline),updated_at=clock_timestamp()
   WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING lease_expires_at INTO new_expiry;
   result_value:=jsonb_build_object('renewed',true,'cancel_requested',false,'lease_expires_at',new_expiry);
  END IF;
 END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 IF new_expiry IS NOT NULL THEN
  parent_deadline:=public.zasp_production_security_agent_existing_tests_invocation_parent(o,w,e,r);
  -- The old lease, not the freshly written expiry, authorized this renewal.
  -- Roll the entire statement back if an UPDATE/catalog wait outlived it.
  IF prior_expiry<=clock_timestamp() OR new_expiry<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker heartbeat expired';
  END IF;
 END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_worker_protocol(o text, w text, e text, r text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE protocol_value text;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker protocol release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker protocol input rejected';END IF;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links l WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id)=(o,w,e,r)) THEN 'linked' ELSE 'legacy' END INTO protocol_value
 FROM public.zasp_red_team_runs t WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id)=(o,w,e,r);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker protocol run unavailable';END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker protocol release unavailable';END IF;
 RETURN jsonb_build_object('protocol',protocol_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_run_context_test_binding(org_value text, workspace_value text, environment_value text, agent_value text, version_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE body_value jsonb;reference_value jsonb;test_row public.zasp_red_team_definitions%ROWTYPE;target_value jsonb;class_value text;credential_expires timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(org_value) AND public.zasp_valid_product_id(workspace_value) AND public.zasp_valid_product_id(environment_value) AND public.zasp_valid_product_id(agent_value) AND version_value BETWEEN 1 AND 1000000,false) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';
 END IF;
 SELECT definition.body INTO body_value FROM public.zasp_security_agent_definitions definition
 WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(org_value,workspace_value,environment_value,agent_value,version_value) AND definition.deleted_at IS NULL FOR SHARE;
 reference_value:=body_value->'existing_test';
 IF NOT COALESCE((body_value->'allowed_actions' IN ('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) AND body_value->>'verification_kind'='test_run' OR body_value->'allowed_actions'='["start_attack_lab"]'::jsonb AND body_value->>'verification_kind'='attack_lab_run' AND public.zasp_sa_attack_lab_guard())
  AND jsonb_typeof(reference_value)='object' AND reference_value ?& ARRAY['definition_id','definition_version'] AND reference_value-ARRAY['definition_id','definition_version']='{}'::jsonb
  AND jsonb_typeof(reference_value->'definition_id')='string' AND public.zasp_valid_product_id(reference_value->>'definition_id')
  AND jsonb_typeof(reference_value->'definition_version')='number' AND reference_value->>'definition_version' ~ '^([1-9][0-9]{0,5}|1000000)$',false) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';
 END IF;
 SELECT * INTO test_row FROM public.zasp_red_team_definitions definition
 WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version,definition.enabled)=(org_value,workspace_value,environment_value,reference_value->>'definition_id',(reference_value->>'definition_version')::bigint,true) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';END IF;
 class_value:=public.zasp_production_security_agent_run_context_lock_env(org_value,workspace_value,environment_value);
 IF NOT COALESCE(class_value IN('development','test','staging') AND class_value=test_row.safety->>'environment',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';END IF;
 target_value:=public.zasp_production_security_agent_run_context_lock_target(org_value,workspace_value,environment_value,test_row.target_id);
 IF NOT COALESCE(target_value->>'state'='active',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';END IF;
 SELECT binding.valid_until INTO credential_expires FROM public.zasp_attack_lab_credential_bindings binding
 WHERE (binding.organization_id,binding.workspace_id,binding.environment_id,binding.target_id,binding.credential_reference,binding.state)=(org_value,workspace_value,environment_value,test_row.target_id,target_value->'attributes'->'red_team'->>'credential_reference','active') AND binding.credential_class=test_row.safety->>'credential_class' FOR SHARE;
 IF NOT FOUND OR NOT COALESCE(credential_expires>clock_timestamp() AND (target_value->>'fresh_until')::timestamptz>clock_timestamp() AND public.zasp_red_team_safety_authorized(org_value,workspace_value,environment_value,test_row.target_id,test_row.target_kind,test_row.safety),false) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';
 END IF;
 RETURN jsonb_build_object('definition_id',test_row.definition_id,'definition_version',test_row.version,'target_id',test_row.target_id,'target_kind',test_row.target_kind);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal73.admit(o text, w text, e text, d text, v bigint, k text, t text, tv bigint, r text, actor_value text, audit_value text, correlation_value text, automatic_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row public.zasp_security_agent_definitions%ROWTYPE;prior public.zasp_security_agent_trigger_receipts%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
 binding_value jsonb;trigger_value jsonb;created_value boolean:=false;action_value text;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(t) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND v BETWEEN 1 AND 1000000 AND tv>=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test admission rejected';END IF;
 -- The same organization guard used by budget claim precedes all work rows.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR definition_row.body->>'trigger_kind' IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission definition changed';END IF;
 action_value:=definition_row.body->'allowed_actions'->>0;
 binding_value:=zasp_temporal70.body15(o,w,e,d,v);
 IF action_value NOT IN('run_test','rerun_test','start_attack_lab') OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(action_value) OR definition_row.body->>'verification_kind' IS DISTINCT FROM (CASE action_value WHEN 'start_attack_lab' THEN 'attack_lab_run' ELSE 'test_run' END) OR NOT (definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$') OR (definition_row.body->>'max_ai_cost_nano_credits')::bigint NOT BETWEEN 1 AND 1000000000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission configuration changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,action_value);
 trigger_value:=public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',tv);
 SELECT * INTO prior FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_version)=(o,w,e,d,t,(trigger_value->>'version')::bigint) FOR SHARE;
 IF FOUND THEN
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,prior.run_id) FOR SHARE;
  IF NOT FOUND OR run_row.definition_id<>d OR run_row.definition_version<>v OR prior.trigger_kind<>k OR prior.trigger_digest IS DISTINCT FROM decode(trigger_value->>'digest','hex') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test trigger intent conflict';END IF;
 ELSE
  IF zasp_temporal73.active_count(o,w,e,d) >= (definition_row.body->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test concurrency unavailable';END IF;
  -- Every prerequisite lock has completed before this final wall-clock check.
  IF zasp_temporal70.body15(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission authority changed';END IF;
  INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d,t,k,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),r);
  INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d,v,t,actor_value,'queued') RETURNING * INTO run_row;

  INSERT INTO zasp_temporal73.admissions VALUES(o,w,e,r,d,v,t,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),'retained_single_action');
  INSERT INTO zasp_temporal73.commands VALUES(o,w,e,r,1,'start');
  created_value:=true;
 END IF;
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
 VALUES(o,w,e,audit_value,correlation_value,run_row.run_id,actor_value,CASE WHEN created_value THEN 'run_queued' ELSE 'run_deduplicated' END,decode(trigger_value->>'digest','hex'),jsonb_build_object('run_id',run_row.run_id,'definition_id',d,'definition_version',v,'trigger_kind',k,'trigger_id',t,'trigger_version',trigger_value->'version','automatic',automatic_value,'action',action_value));
 PERFORM zasp_temporal70.body15(o,w,e,d,v);
 IF public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired';END IF;
 UPDATE public.zasp_security_agent_execution_state SET used_at=coalesce(used_at,clock_timestamp()) WHERE singleton;
 IF zasp_temporal70.body15(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired after final write';END IF;
 RETURN jsonb_build_object('id',run_row.run_id,'agent_id',d,'state',run_row.state,'evidence_ids',jsonb_build_array(t),'definition_version',v,'version',run_row.version,'created',created_value,'replayed',NOT created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal73.schedule_body(worker_value text, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;result_value jsonb;created_value integer:=0;run_value text;prior_count integer;admissions_value jsonb:='[]'::jsonb;admitted_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';END IF;
 IF NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND limit_value BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test schedule rejected';END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 FOR candidate IN
  SELECT d.organization_id o,d.workspace_id w,d.environment_id e,d.definition_id d,d.version v,d.body->>'trigger_kind' k,x.id t,x.version tv
  FROM public.zasp_security_agent_definitions d CROSS JOIN LATERAL (
   SELECT f.id,f.version FROM public.zasp_risk_findings f WHERE (f.organization_id,f.workspace_id,f.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='finding' AND f.status='open' AND f.rule=d.body->>'trigger_source'
   UNION ALL SELECT p.id,p.version FROM public.zasp_risk_attack_paths p WHERE (p.organization_id,p.workspace_id,p.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='attack_path' AND p.state=d.body->>'trigger_source' AND p.state IN('observed','verified') AND public.zasp_risk_attack_path_valid(p)
   UNION ALL SELECT ev.classification->>'session_id',ev.sequence FROM public.zasp_runtime_gateway_events ev
    JOIN public.zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,'active')
    JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,ev.credential_id)
    WHERE (ev.organization_id,ev.workspace_id,ev.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='runtime_decision' AND ev.decision='block' AND ev.classification->>'outcome'=d.body->>'trigger_source' AND ev.occurred_at>=clock_timestamp()-interval '5 minutes' AND ev.occurred_at<=clock_timestamp() AND public.zasp_valid_product_id(ev.classification->>'session_id')
    AND credential.revoked_at IS NULL AND credential.expires_at>clock_timestamp()
    AND credential.id=(SELECT c.id FROM public.zasp_gateway_credentials c WHERE (c.organization_id,c.workspace_id,c.environment_id,c.device_id)=(d.organization_id,d.workspace_id,d.environment_id,ev.device_id) AND c.revoked_at IS NULL AND c.expires_at>clock_timestamp() ORDER BY c.issued_at DESC,c.id DESC LIMIT 1)
    AND ev.event_id=(SELECT newest.event_id FROM public.zasp_runtime_gateway_events newest WHERE (newest.organization_id,newest.workspace_id,newest.environment_id,newest.classification->>'session_id',newest.decision,newest.classification->>'outcome')=(d.organization_id,d.workspace_id,d.environment_id,ev.classification->>'session_id','block',d.body->>'trigger_source') AND newest.occurred_at<=clock_timestamp() ORDER BY newest.occurred_at DESC,newest.sequence DESC,newest.event_id DESC LIMIT 1)
  ) x
  WHERE d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb AND d.body ? 'existing_test'
   AND zasp_temporal70.body04(d.organization_id,d.workspace_id,d.environment_id,d.body,d.activation)
   AND zasp_temporal73.active_count(d.organization_id,d.workspace_id,d.environment_id,d.definition_id)<(d.body->>'concurrency_limit')::integer
   AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.trigger_id,tr.trigger_version)=(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version))
  -- Scan work is capped independently of successful admissions. A refused
  -- candidate must not consume the entire caller's successful-work allowance.
  ORDER BY d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version DESC LIMIT least(100,limit_value*4)
 LOOP
  EXIT WHEN created_value>=limit_value;
  BEGIN
   -- Skip contended organizations before entering the blocking shared core.
   CONTINUE WHEN NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||candidate.o,0));
   run_value:=public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_run',concat_ws(chr(31),candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv));
   result_value:=zasp_temporal73.admit(candidate.o,candidate.w,candidate.e,candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv,run_value,worker_value,public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_audit',run_value),public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_correlation',run_value),true);
   IF (result_value->>'created')::boolean THEN
    created_value:=created_value+1;
    admissions_value:=admissions_value||jsonb_build_array(jsonb_build_object('o',candidate.o,'w',candidate.w,'e',candidate.e,'d',candidate.d,'v',candidate.v,'r',run_value));
   END IF;
  EXCEPTION WHEN SQLSTATE '40001' OR SQLSTATE '42501' OR SQLSTATE '55000' OR SQLSTATE '23505' THEN
   -- A stale candidate rolls back its whole subtransaction, including receipts.
   CONTINUE;
  END;
 END LOOP;
 IF created_value<limit_value THEN
  prior_count:=(public.zasp_security_agent_schedule_triggers_v33(worker_value,limit_value-created_value)->>'created')::integer;
  IF prior_count IS NULL OR prior_count<0 OR prior_count>limit_value-created_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test scheduler bound violated';END IF;
  created_value:=created_value+prior_count;
 END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 -- Later candidates and the delegated legacy scheduler can block after an
 -- earlier test admission. Revalidate every new test run at the commit edge.
 FOR admitted_value IN SELECT value FROM jsonb_array_elements(admissions_value) LOOP
  PERFORM zasp_temporal70.body15(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',(admitted_value->>'v')::bigint);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr JOIN public.zasp_security_agent_definitions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id)=(tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id)
   WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.run_id)=(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',admitted_value->>'r')
    AND public.zasp_production_security_agent_existing_tests_trigger(tr.organization_id,tr.workspace_id,tr.environment_id,tr.trigger_kind,tr.trigger_id,d.body->>'trigger_source',tr.trigger_version)=jsonb_build_object('version',tr.trigger_version,'digest',encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test scheduled admission changed before commit';END IF;
 END LOOP;
 RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.mutate(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';actor text:=q->>'actor_id';r text:=q->>'run_id';op text:=q->>'operation';
 operation_value text;fresh timestamptz;rr public.zasp_security_agent_runs%ROWTYPE;s public.zasp_security_agent_steps%ROWTYPE;approval public.zasp_security_agent_approvals%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;audit_row public.zasp_security_agent_audit%ROWTYPE;transition_row public.zasp_security_agent_audit%ROWTYPE;decision_row public.zasp_security_agent_audit%ROWTYPE;
 audit_id_value text;receipt_id_value text;transition_id text;transition_q jsonb;transition_result jsonb;result_value jsonb;body_value jsonb;projection jsonb;
 admitted boolean;cleanup_value boolean;replayed boolean:=false;keys text[];expected_step_version bigint;phase_value text;expected_phase text;decision_id text;
BEGIN
 IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  OR (q->>'run_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation rejected';END IF;
 IF op='decide' THEN
  IF jsonb_typeof(q->'decision') IS DISTINCT FROM 'string' OR q->>'decision' NOT IN('approved','rejected') OR jsonb_typeof(q->'fresh_auth_at') IS DISTINCT FROM 'string'
   OR length(q->>'fresh_auth_at') NOT BETWEEN 20 AND 35 OR q->>'fresh_auth_at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' OR (q->>'approval_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered decision rejected';END IF;
  fresh:=(q->>'fresh_auth_at')::timestamptz;
  IF fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered decision unavailable';END IF;
 END IF;
 operation_value:=CASE op WHEN 'decide' THEN 'decideSecurityAgentApproval' ELSE 'cancelSecurityAgentRun' END;
 -- Organization admission precedes budget/run, exactly as the private worker.
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 admitted:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r));
 IF admitted THEN PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);END IF;
 IF admitted AND op='cancel' THEN
  -- Cancellation must remain possible after gateway revocation or expiry.
  -- Validate retained authority here; validate terminal cleanup evidence after
  -- the reviewed transition creates its blocking audit, never live permission.
  PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
  PERFORM zasp_ordered_public62.history(o,w,e,r);
 ELSE projection:=zasp_ordered_public62.project(o,w,e,r);END IF;
 audit_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 receipt_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_receipt',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,operation_value,q->>'idempotency_key') FOR SHARE;
 IF FOUND THEN
  IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
  SELECT * INTO audit_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,audit_id_value) FOR SHARE;
  result_value:=prior.response;body_value:=audit_row.body;transition_id:=body_value->>'transition_audit_id';
  IF (prior.resource_id,prior.expected_version,prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (r,(q->>'run_version')::bigint,audit_id_value,audit_id_value,receipt_id_value)
   OR (audit_row.run_id,audit_row.actor_id,audit_row.event_kind,audit_row.correlation_id) IS DISTINCT FROM (r,actor,'ordered_public_'||op,audit_id_value)
   OR NOT zasp_sa_multistep_prior.closed(body_value||jsonb_build_object('transition_audit_id',COALESCE(transition_id,''),'transition_digest',COALESCE(body_value->>'transition_digest','')),ARRAY['request','response','transition_audit_id','transition_digest']) OR NOT body_value ?& ARRAY['transition_audit_id','transition_digest'] OR body_value->'request' IS DISTINCT FROM q OR body_value->'response' IS DISTINCT FROM result_value
   OR audit_row.event_digest IS DISTINCT FROM digest(convert_to(body_value::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation history unavailable';END IF;
  replayed:=true;
 ELSE
  IF rr.version<>(q->>'run_version')::bigint OR rr.completed_at IS NOT NULL OR rr.state NOT IN('queued','planning','waiting_approval','running','verifying') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation state changed';END IF;
  IF op='decide' THEN
   IF NOT admitted OR rr.state<>'waiting_approval' OR actor=rr.requested_by THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'waiting_approval') ORDER BY step_index LIMIT 1;
   SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   IF approval.approval_id IS DISTINCT FROM q->>'approval_id' OR approval.state IS DISTINCT FROM 'pending' OR approval.version IS DISTINCT FROM (q->>'approval_version')::bigint OR s.version>=1000000
    OR approval.approver_id IS NOT NULL OR approval.decided_at IS NOT NULL OR approval.fresh_auth_at IS NOT NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
  ELSIF admitted THEN
   -- Before the application receipt step zero owns cancellation. Once it is
   -- complete the canonical successor owns it, including the between-step gap.
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND step_index=CASE WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index,state)=(o,w,e,r,0,'succeeded')) THEN 1 ELSE 0 END;
  END IF;
  PERFORM zasp_ordered_public62.history(o,w,e,r);
  IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation authority changed';END IF;
  IF admitted THEN
   IF s.step_id IS NULL OR s.version>=1000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered current step unavailable';END IF;
   IF op='cancel' THEN SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);END IF;
   phase_value:=CASE s.state WHEN 'queued' THEN 'queued' WHEN 'waiting_approval' THEN 'pending-approval' WHEN 'authorized' THEN 'authorized' WHEN 'executing' THEN 'executing' END;
   -- The immutable cancel request retains positive pre-transition approval
   -- authority: pending=1, previously approved=2, no approval=1. Never infer
   -- a pending phase merely from missing prior decision evidence.
