 SELECT predecessor INTO p FROM zasp_temporal65.registration WHERE checksum=c AND fingerprint=f;
 IF p='legacy60' THEN
  RETURN to_regnamespace('zasp_ordered_public62') IS NULL AND public.zasp_discovery_schedule_replay_readiness('37956023196757f30a7ecb415e9d7d7e6f76cfa32a3ffa2d45445c172f6313ab','1ed52fb5f9a83384e1d3fecbc3bc116d3981a36479e9b3b1f6ec04b5cd4f3b36');
 ELSIF p='ordered62' THEN
  IF to_regnamespace('zasp_ordered_public62') IS NULL THEN RETURN false;END IF;
  RETURN zasp_ordered_public62.ready('e4dfae0a990718c2c6b7518b07d7c146cfb9025656378d423c8d96188bcf1b96','07e774a28105095c73275ad959c765a3fddda9ee9aa81e81cd3828222e40aad3');
