CREATE OR REPLACE FUNCTION zasp_temporal66.ready(c text, f text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
