 IF c IS DISTINCT FROM '6e2fbdef64421286476be12a02188d7936e81db3126764bf2ab55e099fcb12cb' OR f IS DISTINCT FROM '422b211febdd6e2b37882dc3f5961a79ca5c58f3f87f1642f7babf1224fbe94a' OR (SELECT count(*) FROM zasp_temporal66.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_temporal66.registration WHERE checksum=c AND fingerprint=f) OR zasp_temporal66.fingerprint() IS DISTINCT FROM f
  OR NOT zasp_ordered_public62.ready('e4dfae0a990718c2c6b7518b07d7c146cfb9025656378d423c8d96188bcf1b96','07e774a28105095c73275ad959c765a3fddda9ee9aa81e81cd3828222e40aad3') OR NOT zasp_temporal65.ready('2cb65040d3be0f7a08722691c5c1fe38b93b4d036cec6b74b4b2ec83c3a2d56a','8c64101128b0b31cd4d12575480035ab1e30f157d92fa96c236babc7620de3f8') THEN RETURN false;END IF;
 FOREACH n IN ARRAY ARRAY['zasp_ordered_worker63','zasp_ordered_scheduler64'] LOOP
