 IF NOT COALESCE(receipt->>'schema'='runtime-stage-receipt-v1' AND receipt->>'stage'='index' AND receipt->>'implementation_version'='runtime-index-v1' AND receipt->>'organization_id'=organization_value AND receipt->>'workspace_id'=workspace_value AND receipt->>'environment_id'=environment_value AND receipt->>'batch_id'=batch_value AND receipt->>'generation'=generation_value::text AND receipt->>'effect_digest'=encode(input_digest_value,'hex') AND receipt->>'archive_digest'=encode(archive_digest_value,'hex') AND receipt->>'archive_reference'=batch_row.raw_artifact_reference AND receipt->>'archive_version_id'=batch_row.raw_artifact_version_id AND receipt->>'input_digest'=encode(archive_digest_value,'hex') AND receipt->>'input_reference'=batch_row.raw_artifact_reference AND receipt->>'input_version_id'=batch_row.raw_artifact_version_id AND archive->>'source'=domain_row.source_kind AND jsonb_typeof(archive->'events')='array' AND jsonb_array_length(archive->'events')=batch_row.event_count,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate archive binding rejected';END IF;
 SELECT * INTO prior FROM zasp_runtime_candidate_snapshots WHERE (organization_id,workspace_id,environment_id,batch_id,generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);
 IF FOUND THEN
  IF convert_from(prior.snapshot_body,'UTF8')::jsonb->>'schema' IS DISTINCT FROM 'runtime-candidate-snapshot-v2' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime sandbox replay version conflict';END IF;
  IF prior.archive_digest IS DISTINCT FROM archive_digest_value OR prior.index_receipt_digest IS DISTINCT FROM receipt_digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime candidate replay conflict';END IF;
  PERFORM zasp_runtime_candidate_execution_live(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,implementation_value,input_digest_value,archive_digest_value,receipt_digest_value);
  IF NOT COALESCE(zasp_production_runtime_sandbox_binding_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 RETURN jsonb_build_object('snapshot',encode(prior.snapshot_body,'hex'),'sha256',encode(prior.snapshot_digest,'hex'),'replayed',true);
 END IF;
 -- Only the two admission identities are locked. Existing candidate identities
 -- are sampled in the selection statement; a later revocation cannot rewrite
 -- an already frozen historical decision. Never lock another batch's stage.
 PERFORM id FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND id IN(domain_row.source_sensor_id,domain_row.runtime_sensor_id) ORDER BY id FOR SHARE;
 now_value:=clock_timestamp();
 IF work_row.lease_expires_at<=now_value OR NOT zasp_runtime_principal_ready('zasp_runtime_correlation_worker') OR NOT EXISTS(SELECT 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id,kind,state)=(organization_value,workspace_value,environment_value,domain_row.source_sensor_id,domain_row.source_kind,'active') AND revoked_at IS NULL) OR domain_row.runtime_sensor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id,kind,state)=(organization_value,workspace_value,environment_value,domain_row.runtime_sensor_id,'tetragon','active') AND revoked_at IS NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime candidate enrollment rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_deliveries WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,disposition)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'held') AND lease_expires_at>now_value AND visibility_deadline>now_value) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate delivery missing';END IF;
 FOR event_value,ordinal_value IN SELECT value,ordinality FROM jsonb_array_elements(archive->'events') WITH ORDINALITY LOOP
  IF event_value ? 'observed_lineage' AND NOT zasp_runtime_candidate_lineage_valid(event_value->'observed_lineage',(event_value->>'event_time')::timestamptz) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate lineage rejected';END IF;
  IF domain_row.source_kind='otlp' AND domain_row.runtime_sensor_id IS NOT NULL AND event_value ? 'observed_lineage' THEN
   IF jsonb_typeof(event_value#>'{attributes,sandbox.id}') IS DISTINCT FROM 'string' OR COALESCE(octet_length(event_value#>>'{attributes,sandbox.id}'),0) NOT BETWEEN 1 AND 256 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime sandbox identity rejected';END IF;
   INSERT INTO zasp_runtime_candidate_observations(organization_id,workspace_id,environment_id,batch_id,generation,event_ordinal,source_sensor_id,runtime_sensor_id,archive_digest,index_receipt_digest,agent_id,session_id,observed_lineage,event_time,cluster_uid,node_uid,boot_id,pod_uid,container_id,sandbox_id)
   VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,ordinal_value,domain_row.source_sensor_id,domain_row.runtime_sensor_id,archive_digest_value,receipt_digest_value,event_value#>>'{attributes,agent.id}',event_value#>>'{attributes,session.id}',event_value->'observed_lineage',(event_value->>'event_time')::timestamptz,event_value#>>'{observed_lineage,cluster_uid}',event_value#>>'{observed_lineage,node_uid}',event_value#>>'{observed_lineage,boot_id}',event_value#>>'{observed_lineage,pod_uid}',event_value#>>'{observed_lineage,container_id}',event_value#>>'{attributes,sandbox.id}');
  END IF;
 END LOOP;
 -- Fixed five-minute event-time profile. At most 1,001 indexed observations
 -- per input event; an overflowing union fails closed rather than truncating.
 WITH targets AS MATERIALIZED (SELECT DISTINCT value->'observed_lineage' lineage,(value->>'event_time')::timestamptz event_time FROM jsonb_array_elements(archive->'events') WHERE value ? 'observed_lineage'),
 possible AS MATERIALIZED (
  SELECT selected.* FROM targets target CROSS JOIN LATERAL (
   SELECT observation.batch_id,observation.event_ordinal FROM zasp_runtime_candidate_observations observation
   WHERE (observation.organization_id,observation.workspace_id,observation.environment_id,observation.runtime_sensor_id,observation.cluster_uid,observation.node_uid,observation.boot_id,observation.pod_uid,observation.container_id)=(organization_value,workspace_value,environment_value,domain_row.runtime_sensor_id,target.lineage->>'cluster_uid',target.lineage->>'node_uid',target.lineage->>'boot_id',target.lineage->>'pod_uid',target.lineage->>'container_id')
    AND observation.event_time BETWEEN target.event_time-interval '5 minutes' AND target.event_time+interval '5 minutes'
   ORDER BY observation.event_time,observation.batch_id,observation.event_ordinal LIMIT 1001
  ) selected
 ), unique_rows AS MATERIALIZED (SELECT DISTINCT * FROM possible), selected AS (
  SELECT observation.* FROM unique_rows occurrence
  JOIN zasp_runtime_candidate_observations observation ON (observation.organization_id,observation.workspace_id,observation.environment_id,observation.batch_id,observation.event_ordinal)=(organization_value,workspace_value,environment_value,occurrence.batch_id,occurrence.event_ordinal)
  JOIN zasp_sensors source ON (source.organization_id,source.workspace_id,source.environment_id,source.id,source.kind,source.state)=(observation.organization_id,observation.workspace_id,observation.environment_id,observation.source_sensor_id,'otlp','active') AND source.revoked_at IS NULL
  JOIN zasp_runtime_batch_authorities origin ON (origin.organization_id,origin.workspace_id,origin.environment_id,origin.batch_id,origin.batch_generation)=(observation.organization_id,observation.workspace_id,observation.environment_id,observation.batch_id,observation.generation) AND origin.state IN('processing','succeeded')
  ORDER BY observation.batch_id,observation.event_ordinal LIMIT 1001
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('batch_id',batch_id,'generation',generation,'event_ordinal',event_ordinal,'source_sensor_id',source_sensor_id,'agent_id',agent_id,'session_id',session_id,'sandbox_id',sandbox_id,'archive_digest',encode(archive_digest,'hex'),'index_receipt_digest',encode(index_receipt_digest,'hex'),'observed_lineage',observed_lineage,'event_time',to_char(event_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ORDER BY batch_id,event_ordinal),'[]'::jsonb),(SELECT count(*) FROM (SELECT 1 FROM unique_rows LIMIT 1001) bounded)
 INTO candidate_values,possible_count FROM selected;
 -- Detect overflow BEFORE authority filtering: revoked/failed rows must never
 -- occupy the internal bound and hide another viable identity beyond it.
 IF possible_count>1000 OR jsonb_array_length(candidate_values)>1000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='runtime candidate snapshot overflow';END IF;
 body_value:=convert_to(jsonb_build_object('schema','runtime-candidate-snapshot-v2','organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'batch_id',batch_value,'generation',generation_value,'source_sensor_id',domain_row.source_sensor_id,'runtime_sensor_id',domain_row.runtime_sensor_id,'archive_digest',encode(archive_digest_value,'hex'),'index_receipt_digest',encode(receipt_digest_value,'hex'),'window_seconds',300,'candidates',candidate_values)::text,'UTF8');
 body_digest:=digest(body_value,'sha256');
 IF clock_timestamp()>=work_row.lease_expires_at THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate lease expired';END IF;
 INSERT INTO zasp_runtime_candidate_snapshots(organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind,runtime_sensor_id,archive_digest,index_receipt_digest,snapshot_body,snapshot_digest)
 VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,domain_row.source_sensor_id,domain_row.source_kind,domain_row.runtime_sensor_id,archive_digest_value,receipt_digest_value,body_value,body_digest);
 PERFORM zasp_runtime_candidate_execution_live(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,implementation_value,input_digest_value,archive_digest_value,receipt_digest_value);
 IF NOT COALESCE(zasp_production_runtime_sandbox_binding_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 RETURN jsonb_build_object('snapshot',encode(body_value,'hex'),'sha256',encode(body_digest,'hex'),'replayed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_heartbeat_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 UPDATE zasp_runtime_deliveries delivery_row SET lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp()
  WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest,delivery_row.lease_owner,delivery_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,worker_value,lease_token_value) AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_heartbeat_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, expected_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE lease_expiration timestamptz;updated_count integer;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR expected_count NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox heartbeat';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 lease_expiration:=transaction_timestamp()+make_interval(secs=>lease_seconds);
 UPDATE zasp_discovery_outbox SET lease_expires_at=lease_expiration WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 GET DIAGNOSTICS updated_count=ROW_COUNT;
 IF updated_count<>expected_count THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease set conflict';END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('id',topic_value,'lease_expires_at',to_char(lease_expiration AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'remaining_count',updated_count);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_heartbeat_stage(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;expires_value timestamptz;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_seconds NOT BETWEEN 5 AND 900 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 UPDATE zasp_runtime_stage_work stage_row SET lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp()
  WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,stage_row.stage,stage_row.state,stage_row.lease_owner,stage_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,stage_value,'leased',worker_value,lease_token_value) AND stage_row.lease_expires_at>transaction_timestamp() RETURNING stage_row.lease_expires_at INTO expires_value;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime stage lease missing';END IF;
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'stage',stage_value,'lease_expires_at',expires_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_lookup_acceptance(locator_value bytea, secret_value bytea, enrollment_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_value text, media_value text, schema_value text, size_value bigint, count_value integer, job_value text, outbox_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;scope_bytes bytea;expected_payload jsonb;response jsonb;now_value timestamptz;
BEGIN
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal rejected';END IF;
 IF NOT COALESCE(octet_length(locator_value)=16 AND octet_length(secret_value)=32 AND enrollment_value ~ '^[0-9a-f]{64}$' AND zasp_valid_product_id(batch_value) AND length(idempotency_value) BETWEEN 16 AND 128 AND octet_length(content_digest_value)=32 AND source_value IN('tetragon','otlp') AND media_value='application/json' AND (schema_value='runtime-event-v1' OR schema_value='runtime-event-v2' AND source_value='tetragon') AND size_value BETWEEN 1 AND 67108864 AND count_value BETWEEN 1 AND 1000 AND zasp_valid_product_id(job_value) AND zasp_valid_product_id(outbox_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime acceptance input rejected';END IF;
 authority:=zasp_runtime_authenticate_sensor(locator_value,secret_value,'event-ingest');
 scope_bytes:=convert_to('zasp.sensor-enrollment.v1','UTF8')||decode('00','hex')||convert_to(authority->>'organization_id','UTF8')||decode('00','hex')||convert_to(authority->>'workspace_id','UTF8')||decode('00','hex')||convert_to(authority->>'environment_id','UTF8')||decode('00','hex')||convert_to(authority->>'sensor_id','UTF8');
 IF encode(digest(scope_bytes,'sha256'),'hex') IS DISTINCT FROM enrollment_value OR authority->>'sensor_kind' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance enrollment rejected';END IF;
 -- Do not wait on a batch while holding sensor authority. A worker may need
 -- that sensor lock; contention is a retry, never a reason to invert locks.
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.sensor_id,b.idempotency_key)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',idempotency_value) FOR SHARE NOWAIT;
 response:=jsonb_build_object('found',false);
 IF FOUND THEN
  IF (batch_row.batch_id,batch_row.content_digest,batch_row.source_kind,batch_row.payload_media_type,batch_row.payload_schema_version,batch_row.payload_size_bytes,batch_row.event_count) IS DISTINCT FROM (batch_value,content_digest_value,source_value,media_value,schema_value,size_value,count_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance conflict';END IF;
  IF batch_row.state NOT IN('uploading','unknown') THEN
   IF NOT COALESCE(batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND batch_row.finalized_at IS NOT NULL AND batch_row.raw_artifact_checksum=content_digest_value AND batch_row.raw_artifact_size_bytes=size_value AND zasp_discovery_s3_object_reference(batch_row.raw_artifact_reference) AND right(batch_row.raw_artifact_reference,length(batch_row.raw_artifact_key)+1)='/'||batch_row.raw_artifact_key AND length(batch_row.raw_artifact_version_id) BETWEEN 1 AND 1024 AND batch_row.raw_artifact_version_id=btrim(batch_row.raw_artifact_version_id) AND batch_row.raw_artifact_kms_key ~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$',false) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance artifact rejected';END IF;
   expected_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
   IF NOT EXISTS(SELECT 1 FROM zasp_runtime_batches b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.id,b.sensor_id,b.idempotency_key,b.payload_digest,b.event_count,b.payload_reference,b.payload_size_bytes,b.payload_media_type,b.payload_schema_version)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.sensor_id,idempotency_value,content_digest_value,count_value,batch_row.raw_artifact_reference,size_value,media_value,schema_value))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_jobs j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.id,j.kind,j.authority_id,j.idempotency_key,j.request_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_value,idempotency_value,batch_row.request_digest))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox o WHERE (o.organization_id,o.workspace_id,o.environment_id,o.id,o.topic,o.deterministic_key,o.payload_version,o.payload,o.payload_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_value,15,expected_payload,digest(convert_to(expected_payload::text,'UTF8'),'sha256')))
   OR (SELECT count(*) FROM zasp_runtime_stage_work s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.batch_id,s.batch_generation)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.batch_generation) AND (s.stage,s.stage_order) IN(('archive',1),('index',2),('correlate',3),('project',4),('complete',5)))<>5
   THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance durable binding rejected';END IF;
   response:=jsonb_build_object('found',true,'batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state);
  END IF;
 END IF;
 -- Authentication locks are still held. Check wall time after the last query,
 -- not transaction start time, so lock waits cannot extend an expired token.
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal expired';END IF;
 now_value:=clock_timestamp();
 IF NOT EXISTS(SELECT 1 FROM zasp_sensor_tokens t JOIN zasp_sensors s ON (s.organization_id,s.workspace_id,s.environment_id,s.id,s.version)=(t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.sensor_version_at_issue) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.id,t.token_generation)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',authority->>'token_id',(authority->>'token_generation')::bigint) AND t.revoked_at IS NULL AND t.expires_at>now_value AND s.state IN('pending','active','degraded')) THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance credential expired';END IF;
 RETURN response;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precise_search_claim(worker_value text, token_value text, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_capability text;work zasp_runtime_sandbox_search_outbox%ROWTYPE;now_value timestamptz:=clock_timestamp();
BEGIN
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_search_claim',true),'');
 PERFORM set_config('zasp.runtime_precision_search_claim','runtime-projection-v3',true);
 IF num_nulls(worker_value,token_value,lease_seconds)>0 OR worker_value !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$' OR token_value !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR lease_seconds NOT BETWEEN 5 AND 900
 OR NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime sandbox search worker rejected';END IF;
 FOR work IN SELECT * FROM zasp_runtime_sandbox_search_outbox q WHERE q.state IN('pending','leased') AND q.attempt>=100 AND (q.lease_until IS NULL OR q.lease_until<=now_value)
 AND EXISTS(SELECT 1 FROM zasp_runtime_stage_work project WHERE (project.organization_id,project.workspace_id,project.environment_id,project.batch_id,project.batch_generation)=(q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation) AND project.stage='project' AND project.state='succeeded' AND project.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3'))
 AND NOT EXISTS(SELECT 1 FROM zasp_recovery_holds h WHERE (h.organization_id,h.workspace_id,h.environment_id)=(q.organization_id,q.workspace_id,q.environment_id) AND h.state IN('requested','draining','held'))
 ORDER BY q.next_attempt_at,q.created_at,q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation FOR UPDATE OF q SKIP LOCKED LIMIT 100 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-recovery-hold',work.organization_id,work.workspace_id,work.environment_id),0)) THEN CONTINUE;END IF;
  IF NOT zasp_recovery_scope_mutable(work.organization_id,work.workspace_id,work.environment_id) THEN CONTINUE;END IF;
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
  UPDATE zasp_runtime_sandbox_search_outbox SET state='quarantined',worker_id=NULL,lease_digest=NULL,lease_until=NULL
  WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation);
 END LOOP;
 FOR work IN SELECT * FROM zasp_runtime_sandbox_search_outbox q WHERE q.attempt<100 AND ((q.state='pending' AND q.next_attempt_at<=now_value) OR (q.state='leased' AND q.lease_until<=now_value))
 AND EXISTS(SELECT 1 FROM zasp_runtime_stage_work project WHERE (project.organization_id,project.workspace_id,project.environment_id,project.batch_id,project.batch_generation)=(q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation) AND project.stage='project' AND project.state='succeeded' AND project.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3'))
 AND NOT EXISTS(SELECT 1 FROM zasp_recovery_holds h WHERE (h.organization_id,h.workspace_id,h.environment_id)=(q.organization_id,q.workspace_id,q.environment_id) AND h.state IN('requested','draining','held'))
 ORDER BY q.next_attempt_at,q.created_at,q.organization_id,q.workspace_id,q.environment_id,q.batch_id,q.batch_generation FOR UPDATE OF q SKIP LOCKED LIMIT 100 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-recovery-hold',work.organization_id,work.workspace_id,work.environment_id),0)) THEN CONTINUE;END IF;
  IF NOT zasp_recovery_scope_mutable(work.organization_id,work.workspace_id,work.environment_id) THEN CONTINUE;END IF;
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
  now_value:=clock_timestamp();
  UPDATE zasp_runtime_sandbox_search_outbox SET state='leased',attempt=attempt+1,worker_id=worker_value,lease_digest=digest(convert_to(token_value,'UTF8'),'sha256'),lease_until=now_value+make_interval(secs=>lease_seconds)
  WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation) RETURNING * INTO work;
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
  PERFORM set_config('zasp.runtime_precision_search_claim',prior_capability,true);
  RETURN jsonb_build_object('projection_implementation_version',(SELECT project.implementation_version FROM zasp_runtime_stage_work project WHERE (project.organization_id,project.workspace_id,project.environment_id,project.batch_id,project.batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation) AND project.stage='project' AND project.state='succeeded'),'organization_id',work.organization_id,'workspace_id',work.workspace_id,'environment_id',work.environment_id,'batch_id',work.batch_id,'generation',work.batch_generation,'receipt_digest',encode(work.receipt_digest,'hex'),'receipt_reference',work.receipt_reference,'receipt_version',work.receipt_version,'document_ids',work.document_ids,'attempt',work.attempt,'lease_until',work.lease_until);
 END LOOP;
 IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 PERFORM set_config('zasp.runtime_precision_search_claim',prior_capability,true);
 RETURN NULL;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_claim_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;prior_capability text;last_organization text;claimed_last_organization text;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF topic_value IS NULL OR worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime outbox claim rejected';END IF;
 IF allow_v2 AND NOT zasp_discovery_principal_ready('zasp_outbox_worker') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime precise outbox principal rejected';END IF;
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_outbox_claim',true),'');
 PERFORM set_config('zasp.runtime_precision_outbox_claim',CASE WHEN allow_v2 THEN 'runtime-event-v2' ELSE '' END,true);
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox claim';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp_runtime_outbox:'||topic_value,0));
 INSERT INTO zasp_discovery_outbox_topic_fairness(topic) VALUES(topic_value) ON CONFLICT(topic) DO NOTHING;
 SELECT last_organization_id INTO last_organization FROM zasp_discovery_outbox_topic_fairness WHERE topic=topic_value FOR UPDATE;
 UPDATE zasp_discovery_outbox SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error=COALESCE(last_error,'maximum publish attempts exhausted')
 WHERE topic=topic_value AND (payload->>'payload_schema_version'='runtime-event-v1' OR allow_v2 AND payload->>'payload_schema_version'='runtime-event-v2') AND attempt>=100 AND (state='failed' OR state='leased' AND lease_expires_at<=transaction_timestamp());
 WITH organizations AS (
  SELECT candidate.organization_id,min(candidate.available_at) due FROM zasp_discovery_outbox candidate
  WHERE candidate.topic=topic_value AND (candidate.payload->>'payload_schema_version'='runtime-event-v1' OR allow_v2 AND candidate.payload->>'payload_schema_version'='runtime-event-v2') AND candidate.attempt<100 AND (candidate.state IN('pending','failed') OR candidate.state='leased' AND candidate.lease_expires_at<=transaction_timestamp()) AND candidate.available_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox live WHERE live.topic=topic_value AND live.organization_id=candidate.organization_id AND live.state='leased' AND live.lease_expires_at>transaction_timestamp())
  GROUP BY candidate.organization_id
 ),ordered_organizations AS (
  SELECT organization_id,due,row_number() OVER(ORDER BY CASE WHEN last_organization IS NULL OR organization_id>last_organization THEN 0 ELSE 1 END,organization_id) fair_order
  FROM organizations ORDER BY fair_order LIMIT claim_limit
 ),picked AS (
  SELECT chosen.ctid,chosen.organization_id,chosen.created_at,chosen.id,organization.fair_order FROM ordered_organizations organization
  CROSS JOIN LATERAL (
   SELECT outbox.ctid,outbox.organization_id,outbox.created_at,outbox.id FROM zasp_discovery_outbox outbox
   WHERE outbox.organization_id=organization.organization_id AND outbox.topic=topic_value AND (outbox.payload->>'payload_schema_version'='runtime-event-v1' OR allow_v2 AND outbox.payload->>'payload_schema_version'='runtime-event-v2') AND outbox.attempt<100
     AND (outbox.state IN('pending','failed') OR outbox.state='leased' AND outbox.lease_expires_at<=transaction_timestamp()) AND outbox.available_at<=transaction_timestamp()
   ORDER BY outbox.created_at,outbox.id LIMIT 1 FOR UPDATE SKIP LOCKED
  ) chosen
 ),claimed AS (
  UPDATE zasp_discovery_outbox outbox SET state='leased',attempt=attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),completion_digest=NULL,completion_result=NULL
  FROM (SELECT * FROM picked ORDER BY fair_order) candidate WHERE outbox.ctid=candidate.ctid
  RETURNING outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.id,outbox.topic,outbox.deterministic_key,outbox.payload_version,outbox.payload,encode(outbox.payload_digest,'base64') payload_digest,outbox.attempt,outbox.lease_expires_at,candidate.fair_order
 )
 SELECT jsonb_build_object('items',COALESCE(jsonb_agg(to_jsonb(claimed)-'fair_order' ORDER BY fair_order),'[]'::jsonb)),(array_agg(organization_id ORDER BY fair_order DESC))[1] INTO response,claimed_last_organization FROM claimed;
 IF claimed_last_organization IS NOT NULL THEN UPDATE zasp_discovery_outbox_topic_fairness SET last_organization_id=claimed_last_organization,updated_at=transaction_timestamp() WHERE topic=topic_value;END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 PERFORM set_config('zasp.runtime_precision_outbox_claim',prior_capability,true);
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_claim_reconciliation(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;prior_capability text;
BEGIN
 PERFORM zasp_runtime_precision_reconciliation_ready();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation claim rejected';END IF;
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_reconciliation_claim',true),'');
 PERFORM set_config('zasp.runtime_precision_reconciliation_claim',CASE WHEN allow_v2 THEN 'runtime-event-v2' ELSE '' END,true);
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF NOT zasp_discovery_principal_ready('zasp_runtime_ingest') OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 60 AND 300 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation claim rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='succeeded',completion_worker='observed',completion_token_digest=digest(convert_to('observed','UTF8'),'sha256'),completion_digest=digest(convert_to(authority_row.completion_result::text,'UTF8'),'sha256'),completion_result=COALESCE(authority_row.completion_result,jsonb_build_object('batch_id',authority_row.batch_id,'generation',authority_row.batch_generation,'state',authority_row.state,'replayed',true)),completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id) AND authority_row.batch_generation=work_row.batch_generation AND (authority_row.payload_schema_version='runtime-event-v1' OR allow_v2 AND authority_row.payload_schema_version='runtime-event-v2') AND work_row.state NOT IN('succeeded','quarantined') AND authority_row.state NOT IN('uploading','unknown');
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp(),last_error_code=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'outcome_unknown' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE state='leased' AND lease_expires_at<=transaction_timestamp() AND EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation) AND (authority_row.payload_schema_version='runtime-event-v1' OR allow_v2 AND authority_row.payload_schema_version='runtime-event-v2'));
 WITH candidates AS (
  SELECT work_row.ctid FROM zasp_runtime_ingest_reconciliation_work work_row JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id)
  WHERE authority_row.batch_generation=work_row.batch_generation AND (authority_row.payload_schema_version='runtime-event-v1' OR allow_v2 AND authority_row.payload_schema_version='runtime-event-v2') AND work_row.state IN('pending','retryable') AND work_row.attempt<100 AND work_row.available_at<=transaction_timestamp() AND authority_row.state IN('uploading','unknown') ORDER BY work_row.available_at,work_row.organization_id,work_row.batch_id FOR UPDATE OF work_row SKIP LOCKED LIMIT claim_limit
 ),claimed AS (
  UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='leased',attempt=work_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_error_code=NULL FROM candidates WHERE work_row.ctid=candidates.ctid
  RETURNING work_row.*
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'attempt',claimed.attempt,'lease_expires_at',claimed.lease_expires_at,'request_digest',encode(authority_row.request_digest,'hex'),'artifact_key',authority_row.raw_artifact_key,'content_digest',encode(authority_row.content_digest,'hex'),'payload_size_bytes',authority_row.payload_size_bytes,'media_type',authority_row.payload_media_type,'schema_version',authority_row.payload_schema_version) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO response FROM claimed JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id);
 PERFORM zasp_runtime_precision_reconciliation_ready();
 PERFORM set_config('zasp.runtime_precision_reconciliation_claim',prior_capability,true);
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_claim_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE expected text;authority text;
BEGIN
 IF NEW.attempt>OLD.attempt OR NEW.state='failed' AND NEW.last_error_class='exhausted' AND (OLD.state IN('pending','retryable') OR OLD.state='leased' AND OLD.lease_expires_at<=transaction_timestamp()) THEN
  IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
  IF (CASE NEW.stage WHEN 'archive' THEN NEW.implementation_version='runtime-archive-v1' WHEN 'index' THEN NEW.implementation_version='runtime-index-v1' WHEN 'correlate' THEN NEW.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3') WHEN 'project' THEN NEW.implementation_version IN('runtime-projection-v1','runtime-projection-v2') WHEN 'complete' THEN NEW.implementation_version IN('runtime-complete-v1','runtime-complete-v2') ELSE false END) THEN RETURN NEW;END IF;
  expected:=CASE NEW.stage WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END;
  authority:=CASE NEW.stage WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
  IF NOT COALESCE(NEW.implementation_version=expected AND current_setting('zasp.runtime_precision_claim_version',true)=expected AND zasp_runtime_stage_for_session()=NEW.stage AND zasp_runtime_principal_ready(authority),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime precision claim version rejected';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_outbox_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF OLD.topic='runtime-events' AND OLD.payload->>'payload_schema_version'='runtime-event-v2' OR NEW.topic='runtime-events' AND NEW.payload->>'payload_schema_version'='runtime-event-v2' THEN
  PERFORM zasp_runtime_precision_transport_ready();
  IF NEW.attempt>OLD.attempt OR NEW.state='leased' AND (OLD.state,OLD.lease_owner,OLD.lease_token) IS DISTINCT FROM (NEW.state,NEW.lease_owner,NEW.lease_token) OR NEW.state='exhausted' AND (OLD.state='failed' OR OLD.state='leased' AND OLD.lease_expires_at<=transaction_timestamp()) THEN
   IF NOT COALESCE(current_setting('zasp.runtime_precision_outbox_claim',true)='runtime-event-v2' AND zasp_discovery_principal_ready('zasp_outbox_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime precision outbox claim rejected';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_precision_stage_insert_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE source_value text;schema_value text;
BEGIN
 SELECT b.source_kind,b.payload_schema_version INTO source_value,schema_value FROM zasp_runtime_batch_authorities b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.batch_id,b.batch_generation)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.batch_id,NEW.batch_generation);
 IF schema_value='runtime-event-v2' OR source_value='otlp' AND schema_value='runtime-event-v1' THEN
  IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
  IF NOT COALESCE(CASE WHEN schema_value='runtime-event-v2' THEN (NEW.stage,NEW.stage_order,NEW.implementation_version) IN(('archive',1,'runtime-archive-v2'),('index',2,'runtime-index-v2'),('correlate',3,'runtime-correlation-v4'),('project',4,'runtime-projection-v3'),('complete',5,'runtime-complete-v3')) ELSE (NEW.stage,NEW.stage_order,NEW.implementation_version) IN(('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v3'),('project',4,'runtime-projection-v2'),('complete',5,'runtime-complete-v2')) END,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precision stage tuple rejected';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_quarantine_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;batch_value_row zasp_runtime_batch_authorities%ROWTYPE;completion_digest_value bytea;result_value jsonb;
BEGIN
 PERFORM zasp_runtime_precision_reconciliation_ready();
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,worker_value,encode(digest(convert_to(lease_token_value,'UTF8'),'sha256'),'hex'),'artifact_drift'),'UTF8'),'sha256');
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 IF work_value.state='quarantined' THEN
  IF (work_value.completion_worker,work_value.completion_token_digest,work_value.completion_digest) IS DISTINCT FROM (worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation quarantine conflict';END IF;
  PERFORM zasp_runtime_precision_reconciliation_ready();
 RETURN work_value.completion_result||jsonb_build_object('replayed',true);
 END IF;
 IF (work_value.state,work_value.lease_owner,work_value.lease_token) IS DISTINCT FROM ('leased',worker_value,lease_token_value) OR work_value.lease_expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 SELECT * INTO batch_value_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_value_row.state NOT IN('uploading','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','artifact_drift','replayed',false);
 UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker=worker_value,completion_token_digest=digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest=completion_digest_value,completion_result=result_value,completed_at=transaction_timestamp(),last_error_code=NULL WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 PERFORM zasp_runtime_precision_reconciliation_ready();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_reconcile_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;completion_digest_value bytea;result_value jsonb;
BEGIN
 IF NOT zasp_discovery_principal_ready('zasp_runtime_ingest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime reconciliation rejected';END IF;
 IF NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation rejected';END IF;
 IF batch_row.state='quarantined' AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value) THEN RETURN batch_row.completion_result;END IF;
 IF batch_row.state NOT IN('uploading','unknown','queued') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation conflict';END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN
  completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,encode(request_digest_value,'hex'),artifact_reference_value,artifact_key_value,artifact_version_value,encode(artifact_checksum_value,'hex'),artifact_size_value::text,artifact_kms_key_value,'reconcile-drift'),'UTF8'),'sha256');
  result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed','replayed',false);
  UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_key=artifact_key_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='quarantined',finalized_at=transaction_timestamp(),completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  RETURN result_value;
 END IF;
 RETURN zasp_runtime_commit_reserved_batch(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_release_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, outcome_value text, error_class_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE completion_digest_value bytea;result_value jsonb;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR outcome_value NOT IN('retryable','unknown','quarantined') OR outcome_value='retryable' AND error_class_value<>'retryable' OR outcome_value='unknown' AND error_class_value<>'outcome_unknown' OR outcome_value='quarantined' AND error_class_value NOT IN('denied','malformed') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),worker_value,lease_token_value,outcome_value,error_class_value),'UTF8'),'sha256');
 result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',outcome_value,'error_class',error_class_value);
 UPDATE zasp_runtime_deliveries delivery_row SET disposition=CASE WHEN outcome_value='retryable' THEN 'held' ELSE outcome_value END,lease_expires_at=CASE WHEN outcome_value='retryable' THEN transaction_timestamp() ELSE NULL END,visibility_deadline=CASE WHEN outcome_value='retryable' THEN transaction_timestamp() ELSE NULL END,lease_owner=CASE WHEN outcome_value='retryable' THEN delivery_row.lease_owner ELSE NULL END,lease_token=CASE WHEN outcome_value='retryable' THEN delivery_row.lease_token ELSE NULL END,updated_at=transaction_timestamp()
  WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest,delivery_row.disposition,delivery_row.lease_owner,delivery_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,'held',worker_value,lease_token_value) AND delivery_row.lease_expires_at>transaction_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 IF outcome_value IN('unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state=outcome_value,completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_release_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, delay_seconds integer, error_code_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 PERFORM zasp_runtime_precision_reconciliation_ready();
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF delay_seconds NOT BETWEEN 5 AND 300 OR error_code_value NOT IN('not_found','dependency_unavailable','outcome_unknown') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation release rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE WHEN work_row.attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp()+make_interval(secs=>delay_seconds),last_error_code=CASE WHEN work_row.attempt>=100 THEN 'exhausted' ELSE error_code_value END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation,work_row.lease_owner,work_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value) AND work_row.state='leased' AND work_row.lease_expires_at>transaction_timestamp()
 RETURNING jsonb_build_object('batch_id',work_row.batch_id,'generation',work_row.batch_generation,'state',work_row.state,'attempt',work_row.attempt,'error_code',work_row.last_error_code,'replayed',false) INTO result_value;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation release rejected';END IF;
 PERFORM zasp_runtime_precision_reconciliation_ready();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_reserve_batch_v15_internal(locator_value bytea, secret_value bytea, audience_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_kind_value text, media_type_value text, schema_version_value text, payload_size_value bigint, event_count_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;sensor_value text;token_value text;token_generation_value bigint;generation_value bigint;request_digest_value bytea;artifact_key_value text;prior_value zasp_runtime_batch_authorities%ROWTYPE;
BEGIN
 IF NOT zasp_valid_product_id(batch_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR octet_length(content_digest_value)<>32 OR source_kind_value NOT IN('tetragon','otlp') OR length(media_type_value) NOT BETWEEN 1 AND 128 OR media_type_value<>btrim(media_type_value) OR length(schema_version_value) NOT BETWEEN 1 AND 64 OR schema_version_value !~ '^[a-z0-9][a-z0-9_.-]+$' OR payload_size_value NOT BETWEEN 1 AND 67108864 OR event_count_value NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 authority_value:=zasp_runtime_authenticate_sensor(locator_value,secret_value,audience_value);
 organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';sensor_value:=authority_value->>'sensor_id';token_value:=authority_value->>'token_id';token_generation_value:=(authority_value->>'token_generation')::bigint;
 IF authority_value->>'sensor_kind'<>source_kind_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 request_digest_value:=digest(convert_to(jsonb_build_object('sensor_id',sensor_value,'token_id',token_value,'token_generation',token_generation_value,'batch_id',batch_value,'idempotency_key',idempotency_value,'content_digest',encode(content_digest_value,'hex'),'source_kind',source_kind_value,'media_type',media_type_value,'schema_version',schema_version_value,'payload_size_bytes',payload_size_value,'event_count',event_count_value)::text,'UTF8'),'sha256');
 SELECT * INTO prior_value FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.sensor_id,authority_row.idempotency_key)=(organization_value,workspace_value,environment_value,sensor_value,idempotency_value);
 IF FOUND THEN
  IF (prior_value.batch_id,prior_value.sensor_token_id,prior_value.token_generation,prior_value.request_digest,prior_value.content_digest,prior_value.source_kind,prior_value.payload_media_type,prior_value.payload_schema_version,prior_value.payload_size_bytes,prior_value.event_count) IS DISTINCT FROM (batch_value,token_value,token_generation_value,request_digest_value,content_digest_value,source_kind_value,media_type_value,schema_version_value,payload_size_value,event_count_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
  RETURN jsonb_build_object('batch_id',prior_value.batch_id,'generation',prior_value.batch_generation,'artifact_key',prior_value.raw_artifact_key,'request_digest',encode(prior_value.request_digest,'hex'),'state',prior_value.state,'replayed',true);
 END IF;
 SELECT COALESCE(max(authority_row.batch_generation),0)+1 INTO generation_value FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value);
 artifact_key_value:=format('runtime/v15/%s/%s/%s/%s/%s/%s.json',organization_value,workspace_value,environment_value,sensor_value,lpad(generation_value::text,20,'0'),batch_value);
 INSERT INTO zasp_runtime_batch_authorities(organization_id,workspace_id,environment_id,batch_id,sensor_id,sensor_token_id,token_generation,batch_generation,idempotency_key,request_digest,content_digest,source_kind,payload_media_type,payload_schema_version,payload_size_bytes,event_count,raw_artifact_key)
 VALUES(organization_value,workspace_value,environment_value,batch_value,sensor_value,token_value,token_generation_value,generation_value,idempotency_value,request_digest_value,content_digest_value,source_kind_value,media_type_value,schema_version_value,payload_size_value,event_count_value,artifact_key_value);
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'artifact_key',artifact_key_value,'request_digest',encode(request_digest_value,'hex'),'state','uploading','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_reserve_batch_v17(locator_value bytea, secret_value bytea, audience_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_kind_value text, media_type_value text, schema_version_value text, payload_size_value bigint, event_count_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;sensor_value text;prior_value zasp_runtime_batch_authorities%ROWTYPE;recent_batches bigint;recent_events bigint;recent_bytes bigint;result_value jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 authority_value:=zasp_runtime_authenticate_sensor(locator_value,secret_value,audience_value);
 organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';sensor_value:=authority_value->>'sensor_id';
 IF authority_value->>'sensor_kind'<>source_kind_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO prior_value FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.sensor_id,authority_row.idempotency_key)=(organization_value,workspace_value,environment_value,sensor_value,idempotency_value);
 IF NOT FOUND THEN
  SELECT count(*),COALESCE(sum(authority_row.event_count),0),COALESCE(sum(authority_row.payload_size_bytes),0) INTO recent_batches,recent_events,recent_bytes FROM zasp_runtime_batch_authorities authority_row
  WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.sensor_id,authority_row.source_kind)=(organization_value,workspace_value,environment_value,sensor_value,source_kind_value) AND authority_row.reserved_at>=transaction_timestamp()-interval '60 seconds';
  IF recent_batches>=600 OR recent_events+event_count_value>600000 OR recent_bytes+payload_size_value>1073741824 THEN RAISE EXCEPTION USING ERRCODE='53300',MESSAGE='runtime batch rate limited';END IF;
 END IF;
 result_value:=zasp_runtime_reserve_batch_v15_internal(locator_value,secret_value,audience_value,batch_value,idempotency_value,content_digest_value,source_kind_value,media_type_value,schema_version_value,payload_size_value,event_count_value);
 IF (result_value->>'state') IN('uploading','unknown') THEN
  INSERT INTO zasp_runtime_ingest_reconciliation_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,available_at)
  VALUES(organization_value,workspace_value,environment_value,batch_value,(result_value->>'generation')::bigint,transaction_timestamp()+interval '30 seconds') ON CONFLICT DO NOTHING;
 END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_retry_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, retry_after_seconds integer, error_code_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF topic_value<>'runtime-events' OR retry_after_seconds NOT BETWEEN 1 AND 3600 OR error_code_value<>'queue_publish_unknown' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox retry';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_retry_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,retry_after_seconds,error_code_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_sandbox_search_finish(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, token_value text, attempt_value integer, receipt_digest_value bytea, outcome_value text, document_values text[], retry_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work zasp_runtime_sandbox_search_outbox%ROWTYPE;now_value timestamptz;
BEGIN
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,token_value,attempt_value,receipt_digest_value,outcome_value,document_values,retry_seconds)>0 OR outcome_value NOT IN('indexed','retryable','quarantined') OR octet_length(receipt_digest_value)<>32
 OR (outcome_value='retryable' AND retry_seconds NOT BETWEEN 1 AND 3600) OR (outcome_value<>'retryable' AND retry_seconds<>0)
 OR NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session search checkpoint rejected';END IF;
 IF NOT zasp_recovery_scope_mutable(organization_value,workspace_value,environment_value) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search recovery hold active';END IF;IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;SELECT * INTO work FROM zasp_runtime_sandbox_search_outbox WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 now_value:=clock_timestamp();IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF NOT FOUND OR (work.worker_id,work.lease_digest,work.attempt,work.receipt_digest) IS DISTINCT FROM (worker_value,digest(convert_to(token_value,'UTF8'),'sha256'),attempt_value,receipt_digest_value)
 OR (outcome_value='indexed' AND work.document_ids IS DISTINCT FROM document_values) OR (outcome_value<>'indexed' AND cardinality(document_values)<>0) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search checkpoint binding rejected';END IF;
 IF work.state='indexed' AND outcome_value='indexed' THEN
  IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;RETURN jsonb_build_object('state','indexed','batch_id',work.batch_id,'generation',work.batch_generation,'attempt',work.attempt,'receipt_digest',encode(work.receipt_digest,'hex'),'indexed_at',work.indexed_at);
 END IF;
 IF work.state<>'leased' OR work.lease_until<=now_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search checkpoint lease lost';END IF;
 UPDATE zasp_runtime_sandbox_search_outbox SET state=CASE WHEN outcome_value='retryable' THEN 'pending' ELSE outcome_value END,
 worker_id=CASE WHEN outcome_value='indexed' THEN worker_id ELSE NULL END,lease_digest=CASE WHEN outcome_value='indexed' THEN lease_digest ELSE NULL END,lease_until=NULL,
 indexed_at=CASE WHEN outcome_value='indexed' THEN now_value ELSE NULL END,next_attempt_at=now_value+make_interval(secs=>retry_seconds)
 WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) RETURNING * INTO work;
 IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;RETURN jsonb_build_object('state',work.state,'batch_id',work.batch_id,'generation',work.batch_generation,'attempt',work.attempt,'receipt_digest',encode(work.receipt_digest,'hex'),'indexed_at',work.indexed_at);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_sandbox_search_heartbeat(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, token_value text, attempt_value integer, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work zasp_runtime_sandbox_search_outbox%ROWTYPE;deadline timestamptz;now_value timestamptz;
BEGIN
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,token_value,attempt_value,lease_seconds)>0 OR lease_seconds NOT BETWEEN 5 AND 900 OR NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session search lease rejected';END IF;
 IF NOT zasp_recovery_scope_mutable(organization_value,workspace_value,environment_value) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search recovery hold active';END IF;IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;SELECT * INTO work FROM zasp_runtime_sandbox_search_outbox WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search lease lost';END IF;
 now_value:=clock_timestamp();IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF work.state<>'leased' OR work.lease_until<=now_value OR (work.worker_id,work.lease_digest,work.attempt) IS DISTINCT FROM (worker_value,digest(convert_to(token_value,'UTF8'),'sha256'),attempt_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search lease lost';END IF;
 UPDATE zasp_runtime_sandbox_search_outbox SET lease_until=now_value+make_interval(secs=>lease_seconds) WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) RETURNING lease_until INTO deadline;
 IF NOT zasp_runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;RETURN jsonb_build_object('lease_until',deadline);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_sandbox_search_mutation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NOT COALESCE(zasp_production_runtime_sandbox_binding_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false)
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF TG_OP IN('UPDATE','DELETE') AND NOT zasp_recovery_scope_mutable(OLD.organization_id,OLD.workspace_id,OLD.environment_id) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search recovery hold active';END IF;
 IF TG_OP IN('INSERT','UPDATE') AND NOT zasp_recovery_scope_mutable(NEW.organization_id,NEW.workspace_id,NEW.environment_id) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search recovery hold active';END IF;
 IF NOT COALESCE(zasp_production_runtime_sandbox_binding_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false)
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_sensor_heartbeat(locator_value bytea, secret_value bytea, audience_value text, sequence_value bigint, status_value text, capabilities_value jsonb, kernel_value text, btf_value boolean, event_rate_value bigint, drops_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;sensor_value text;metadata_value jsonb;request_digest_value bytea;prior_digest bytea;prior_sequence bigint;observed_value timestamptz;
BEGIN
 IF sequence_value<0 OR status_value NOT IN('healthy','degraded') OR jsonb_typeof(capabilities_value)<>'array' OR jsonb_array_length(capabilities_value) NOT BETWEEN 1 AND 32
  OR length(kernel_value) NOT BETWEEN 1 AND 128 OR kernel_value<>btrim(kernel_value) OR kernel_value ~ '[[:cntrl:]]' OR event_rate_value NOT BETWEEN 0 AND 1000000000 OR drops_value NOT BETWEEN 0 AND 1000000000
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(capabilities_value) item WHERE jsonb_typeof(item)<>'string' OR item#>>'{}' !~ '^[a-z0-9][a-z0-9_.-]{0,95}$')
  OR (SELECT count(*) FROM jsonb_array_elements_text(capabilities_value))<>(SELECT count(DISTINCT item) FROM jsonb_array_elements_text(capabilities_value) item)
  OR capabilities_value<>(SELECT jsonb_agg(item ORDER BY item) FROM jsonb_array_elements_text(capabilities_value) item)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor heartbeat rejected';END IF;
 authority_value:=zasp_runtime_authenticate_sensor(locator_value,secret_value,audience_value);
 organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';sensor_value:=authority_value->>'sensor_id';
 metadata_value:=jsonb_build_object('capabilities',capabilities_value,'kernel',kernel_value,'btf',btf_value,'event_rate',event_rate_value,'drops',drops_value,'schema_version','sensor-heartbeat-v1');
 request_digest_value:=digest(convert_to(jsonb_build_object('sensor_id',sensor_value,'sequence',sequence_value,'status',status_value,'dropped_events',drops_value,'metadata',metadata_value)::text,'UTF8'),'sha256');
 SELECT heartbeat.request_digest,heartbeat.sequence,heartbeat.observed_at INTO prior_digest,prior_sequence,observed_value FROM zasp_sensor_heartbeats heartbeat WHERE (heartbeat.organization_id,heartbeat.workspace_id,heartbeat.environment_id,heartbeat.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value);
 IF FOUND AND prior_sequence=sequence_value THEN IF prior_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='sensor heartbeat conflict';END IF;RETURN jsonb_build_object('sensor_id',sensor_value,'sequence',sequence_value,'observed_at',observed_value);ELSIF FOUND AND prior_sequence>sequence_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='sensor heartbeat conflict';END IF;
 INSERT INTO zasp_sensor_heartbeats(organization_id,workspace_id,environment_id,sensor_id,sequence,request_digest,status,dropped_events,metadata)
 VALUES(organization_value,workspace_value,environment_value,sensor_value,sequence_value,request_digest_value,status_value,drops_value,metadata_value)
 ON CONFLICT(organization_id,workspace_id,environment_id,sensor_id) DO UPDATE SET sequence=excluded.sequence,request_digest=excluded.request_digest,status=excluded.status,dropped_events=excluded.dropped_events,metadata=excluded.metadata,observed_at=transaction_timestamp() RETURNING observed_at INTO observed_value;
 UPDATE zasp_sensors sensor_row SET state=CASE WHEN status_value='healthy' THEN 'active' ELSE 'degraded' END,updated_at=transaction_timestamp() WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)=(organization_value,workspace_value,environment_value,sensor_value) AND sensor_row.state IN('pending','active','degraded');
 RETURN jsonb_build_object('sensor_id',sensor_value,'sequence',sequence_value,'observed_at',observed_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_claim_budgeted_runs(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE manual_check_active boolean:=false;organization_value text;run_row zasp_security_agent_runs%ROWTYPE;
 definition_row zasp_security_agent_definitions%ROWTYPE;budget_row zasp_security_agent_run_budgets%ROWTYPE;
 result_value jsonb:='[]'::jsonb;active_count bigint;active_limit integer;incoming_limit integer;
 start_value timestamptz;now_value timestamptz;duration_value integer;has_budget boolean;
BEGIN
 IF NOT COALESCE(zasp_security_agent_principal_ready('zasp_security_agent_worker'),false)
 OR worker_value IS NULL OR length(worker_value) NOT BETWEEN 1 AND 128
 OR lease_token_value IS NULL OR length(lease_token_value) NOT BETWEEN 16 AND 128
 OR lease_seconds IS NULL OR lease_seconds NOT BETWEEN 30 AND 300
 OR claim_limit IS NULL OR claim_limit NOT BETWEEN 1 AND 25 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent claim rejected';
 END IF;
 -- Oldest eligible organization first; do not wait for another tenant's
 -- admission or work-row locks while holding an organization guard.
 FOR organization_value IN SELECT r.organization_id FROM zasp_security_agent_runs r
  WHERE r.state='queued' AND r.available_at<=clock_timestamp()
   OR r.state IN('planning','running','verifying') AND r.lease_expires_at<=clock_timestamp()
  GROUP BY r.organization_id ORDER BY min(r.available_at),r.organization_id
 LOOP
  -- Serialize first creation too: INSERT ON CONFLICT alone can wait on an
  -- uncommitted insertion even when the subsequent row lock uses SKIP LOCKED.
  CONTINUE WHEN NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||organization_value,0));
  INSERT INTO zasp_security_agent_org_admissions(organization_id) VALUES(organization_value) ON CONFLICT DO NOTHING;
  PERFORM 1 FROM zasp_security_agent_org_admissions a WHERE a.organization_id=organization_value FOR UPDATE SKIP LOCKED;
  CONTINUE WHEN NOT FOUND;
  now_value:=clock_timestamp();
  -- Lock run then budget before expiry writes. Bulk UPDATE would wait on an
  -- old worker holding a run or settlement row, blocking unrelated tenants.
  FOR run_row IN SELECT r.* FROM zasp_security_agent_runs r
   JOIN zasp_security_agent_run_budgets b USING(organization_id,workspace_id,environment_id,run_id)
   WHERE r.organization_id=organization_value AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_webhook_deliveries wh WHERE (wh.organization_id,wh.workspace_id,wh.environment_id,wh.run_id)=(r.organization_id,r.workspace_id,r.environment_id,r.run_id)) AND (b.stop_reason IS NOT NULL OR b.deadline_at<=now_value)
    AND r.state IN('queued','planning','waiting_approval','running','verifying')
   ORDER BY r.workspace_id,r.environment_id,r.run_id FOR UPDATE OF r SKIP LOCKED
  LOOP
   SELECT * INTO budget_row FROM zasp_security_agent_run_budgets b
    WHERE (b.organization_id,b.workspace_id,b.environment_id,b.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)
    FOR UPDATE SKIP LOCKED;
   CONTINUE WHEN NOT FOUND;
   UPDATE zasp_security_agent_run_budgets SET stop_reason=coalesce(stop_reason,'budget_deadline_exceeded')
    WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
   UPDATE zasp_security_agent_runs SET state='needs_human',last_error_code=coalesce(budget_row.stop_reason,'budget_deadline_exceeded'),
    lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=now_value
    WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
  END LOOP;
  FOR run_row IN SELECT r.* FROM zasp_security_agent_runs r WHERE r.organization_id=organization_value AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_webhook_deliveries wh WHERE (wh.organization_id,wh.workspace_id,wh.environment_id,wh.run_id)=(r.organization_id,r.workspace_id,r.environment_id,r.run_id))
   AND (r.state='queued' AND r.available_at<=clock_timestamp()
    OR r.state IN('planning','running','verifying') AND r.lease_expires_at<=clock_timestamp())
   ORDER BY r.available_at,r.workspace_id,r.environment_id,r.run_id FOR UPDATE SKIP LOCKED
  LOOP
   BEGIN
   manual_check_active:=true;
   PERFORM public.zasp_sa_manual_recheck(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
   manual_check_active:=false;
   now_value:=clock_timestamp();
   SELECT * INTO budget_row FROM zasp_security_agent_run_budgets b
    WHERE (b.organization_id,b.workspace_id,b.environment_id,b.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)
    FOR UPDATE SKIP LOCKED;
   has_budget:=FOUND;
   IF NOT has_budget THEN
    -- A locked snapshot is not an absent snapshot and must never be replaced.
    CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_run_budgets b
     WHERE (b.organization_id,b.workspace_id,b.environment_id,b.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id));
    SELECT * INTO definition_row FROM zasp_security_agent_definitions d
     WHERE (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.definition_id,run_row.definition_version)
     AND d.deleted_at IS NULL FOR SHARE SKIP LOCKED;
    IF NOT FOUND THEN
     CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_definitions d
      WHERE (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.definition_id,run_row.definition_version) AND d.deleted_at IS NULL);
     UPDATE zasp_security_agent_runs SET state='needs_human',last_error_code='budget_definition_unavailable',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=now_value
      WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
     CONTINUE;
    END IF;
    incoming_limit:=(definition_row.body->>'concurrency_limit')::integer;
    SELECT count(*),min(b.concurrency_limit) INTO active_count,active_limit
     FROM zasp_security_agent_run_budgets b JOIN zasp_security_agent_runs r
      USING(organization_id,workspace_id,environment_id,run_id)
     WHERE b.organization_id=organization_value AND b.stop_reason IS NULL
      AND r.state IN('queued','planning','waiting_approval','running','verifying','contained');
    CONTINUE WHEN active_count>=least(incoming_limit,coalesce(active_limit,incoming_limit));
    duration_value:=(definition_row.body->>'max_duration_seconds')::integer;
    IF duration_value NOT BETWEEN 1 AND 86400 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent duration rejected';END IF;
    start_value:=CASE WHEN run_row.attempt>0 THEN run_row.created_at ELSE now_value END;
    INSERT INTO zasp_security_agent_run_budgets(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,started_at,deadline_at,max_steps,max_tokens,max_cost_nano_credits,concurrency_limit)
     VALUES(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id,run_row.definition_id,run_row.definition_version,start_value,start_value+make_interval(secs=>duration_value),
      (definition_row.body->>'max_steps')::integer,(definition_row.body->>'ai_token_budget')::bigint,(definition_row.body->>'max_ai_cost_nano_credits')::bigint,incoming_limit)
     RETURNING * INTO budget_row;
   END IF;
   IF budget_row.stop_reason IS NOT NULL OR budget_row.deadline_at<=clock_timestamp() THEN
    UPDATE zasp_security_agent_run_budgets SET stop_reason=coalesce(stop_reason,'budget_deadline_exceeded')
     WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
    UPDATE zasp_security_agent_runs SET state='needs_human',last_error_code=coalesce(budget_row.stop_reason,'budget_deadline_exceeded'),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp()
     WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
    CONTINUE;
   END IF;
   UPDATE zasp_security_agent_runs SET state='planning',attempt=attempt+1,lease_owner=worker_value,lease_token=lease_token_value,
    lease_expires_at=clock_timestamp()+make_interval(secs=>lease_seconds),version=version+1,updated_at=clock_timestamp()
    WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)
    RETURNING * INTO run_row;
   manual_check_active:=true;
   PERFORM public.zasp_sa_manual_recheck(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
   manual_check_active:=false;
result_value:=result_value||jsonb_build_array(jsonb_build_object('organization_id',run_row.organization_id,'workspace_id',run_row.workspace_id,'environment_id',run_row.environment_id,'run_id',run_row.run_id,'definition_id',run_row.definition_id,'definition_version',run_row.definition_version,'trigger_id',run_row.trigger_id,'state',run_row.state,'version',run_row.version,'attempt',run_row.attempt,'lease_expires_at',to_char(run_row.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'prepared',EXISTS(SELECT 1 FROM zasp_security_agent_plans p WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id)))||public.zasp_sa_manual_fields(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id));
   EXCEPTION WHEN insufficient_privilege OR serialization_failure OR object_not_in_prerequisite_state OR no_data_found THEN
    -- Only domain refusals from the marked check are candidate-local. Role,
    -- catalog, infrastructure and actual serialization failures still abort.
    IF NOT manual_check_active OR NOT (
     SQLSTATE='42501' AND SQLERRM IN('export actor rejected','export membership rejected','export source permission rejected')
     OR SQLSTATE='40001' AND SQLERRM IN('manual definition unavailable','manual original definition changed','manual actions unavailable','manual export verification unavailable','manual action source prerequisite unavailable','run original trigger unavailable','run original trigger malformed','manual original trigger malformed','manual original intent changed','security agent test binding unavailable','attack lab planner reference changed','attack lab source changed','attack lab safety unavailable','attack lab safety expired')
     OR SQLSTATE='55000' AND SQLERRM='existing test execution disabled'
     OR SQLSTATE='P0002' AND SQLERRM IN('attack lab preflight unavailable','query returned no rows')
    ) THEN RAISE;END IF;
    manual_check_active:=false;
    UPDATE public.zasp_security_agent_runs SET state='needs_human',last_error_code='manual_authority_unavailable',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp()
     WHERE (organization_id,workspace_id,environment_id,run_id)=(run_row.organization_id,run_row.workspace_id,run_row.environment_id,run_row.run_id);
    CONTINUE;
   END;
   EXIT WHEN jsonb_array_length(result_value)>=claim_limit;
  END LOOP;
  EXIT WHEN jsonb_array_length(result_value)>=claim_limit;
 END LOOP;
 RETURN jsonb_build_object('items',result_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.project_core(o text, w text, e text, r text, retained_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;s public.zasp_security_agent_steps%ROWTYPE;a public.zasp_security_agent_approvals%ROWTYPE;
 receipt public.zasp_sa_multistep_receipts%ROWTYPE;fx public.zasp_security_agent_effects%ROWTYPE;
 cleanup zasp_sa_multistep_prior.cleanups%ROWTYPE;cleaned zasp_sa_multistep_prior.cleanup_receipts%ROWTYPE;
 completion public.zasp_security_agent_audit%ROWTYPE;control_row public.zasp_security_agent_controls%ROWTYPE;completed_body jsonb;
 result_value jsonb;steps jsonb:='[]';receipt_value jsonb;cleanup_value jsonb;snapshot_value jsonb;predecessor text;settlement text;
 admitted boolean;application boolean;live_value boolean;terminal boolean;dependency_ready boolean;retained_live boolean:=true;
BEGIN
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 admitted:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r));
 IF admitted THEN
  PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);
  PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
 ELSE
  PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
  PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
  PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 END IF;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 PERFORM zasp_ordered_public62.history(o,w,e,r);
 terminal:=rr.state IN('contained','remediated','needs_human','failed','inconclusive','cancelled');
 IF (terminal AND rr.completed_at IS NULL) OR (NOT terminal AND rr.completed_at IS NOT NULL) OR rr.version NOT BETWEEN 1 AND 1000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered aggregate unavailable';END IF;
 IF NOT admitted THEN
  IF rr.plan_hash IS NOT NULL OR rr.state NOT IN('queued','planning','needs_human','cancelled','failed','inconclusive') OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) OR EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
   OR rr.state='queued' AND (rr.version<>1 OR rr.attempt<>0)
   OR rr.state='planning' AND NOT EXISTS(SELECT 1 FROM zasp_sa_multistep_prior.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered state unavailable';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.run_id,tr.definition_id,tr.trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) AND r=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',rr.definition_id||chr(31)||rr.trigger_id||chr(31)||tr.trigger_version::text)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger unavailable';END IF;
 ELSE
  application:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_receipts WHERE (organization_id,workspace_id,environment_id,run_id,receipt_kind)=(o,w,e,r,'temporary_policy_applied.v1'));
  SELECT step_id INTO predecessor FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index)=(o,w,e,r,0);
  SELECT * INTO cleanup FROM zasp_sa_multistep_prior.cleanups WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  SELECT * INTO cleaned FROM zasp_sa_multistep_prior.cleanup_receipts WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  IF (SELECT count(*) FROM zasp_sa_multistep_prior.cleanups WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))>1
   OR (SELECT count(*) FROM zasp_sa_multistep_prior.cleanup_receipts WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cleanup multiplicity';END IF;
  IF terminal AND (application OR cleanup.run_id IS NOT NULL) THEN snapshot_value:=zasp_sa_multistep_prior.cleanup_snapshot(o,w,e,r,predecessor);END IF;
  IF NOT terminal AND application THEN
   IF retained_value THEN retained_live:=zasp_ordered_public62.retained_application(o,w,e,r);
   ELSIF NOT zasp_sa_multistep_prior.application_ready(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered application unavailable';END IF;
  END IF;
  IF cleanup.run_id IS NOT NULL AND (cleanup.step_id<>predecessor OR cleanup.snapshot IS DISTINCT FROM snapshot_value)
   OR (cleanup.state='cleaned') IS DISTINCT FROM (cleaned.run_id IS NOT NULL) AND cleanup.run_id IS NOT NULL
   OR cleanup.run_id IS NULL AND cleaned.run_id IS NOT NULL
   OR cleaned.run_id IS NOT NULL AND (cleaned.digest IS DISTINCT FROM digest(convert_to(zasp_sa_multistep_prior.deployment_json(cleaned.body),'UTF8'),'sha256') OR cleaned.receipt_kind IS DISTINCT FROM (CASE WHEN cleanup.snapshot->>'kind'='partial' THEN 'temporary_policy_partial_cleaned.v1' ELSE 'temporary_policy_cleaned.v1' END)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cleanup unavailable';END IF;
  IF cleanup.state='cleaned' THEN
   SELECT * INTO fx FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,predecessor,'create_temporary_policy');
   SELECT * INTO completion FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,step_id,event_kind)=(o,w,e,r,predecessor,'ordered_cleanup_complete');
   IF (SELECT count(*) FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'ordered_cleanup_complete'))<>1
    OR completion.audit_id IS NULL OR completion.audit_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_cleanup_operation',r||chr(31)||predecessor||chr(31)||encode(completion.event_digest,'hex'))
    OR completion.correlation_id IS DISTINCT FROM completion.audit_id OR completion.body->'owner' IS DISTINCT FROM to_jsonb(cleanup)-'lease_token'
    OR fx.state IS DISTINCT FROM 'cleaned' OR fx.lease_owner IS NOT NULL OR fx.lease_token IS NOT NULL OR fx.lease_expires_at IS NOT NULL
    OR cleanup.lease_owner IS NOT NULL OR cleanup.lease_token IS NOT NULL OR cleanup.lease_expires_at IS NOT NULL OR cleanup.completed_at IS NULL
    OR cleaned.step_id IS DISTINCT FROM predecessor
    OR completion.body->'request'->>'operation' IS DISTINCT FROM 'complete' OR completion.body->'request'->>'run_id' IS DISTINCT FROM r OR completion.body->'request'->>'step_id' IS DISTINCT FROM predecessor
    OR completion.body->'request'->'effect_version' IS DISTINCT FROM to_jsonb(fx.version-1) OR completion.body->'request'->'version' IS DISTINCT FROM to_jsonb(cleanup.version-1)
    OR completion.body->'request'->'run_version' IS DISTINCT FROM to_jsonb(rr.version-1)
    OR completion.body->'response'->'effect_version' IS DISTINCT FROM to_jsonb(fx.version) OR completion.body->'response'->>'effect_state' IS DISTINCT FROM fx.state
    OR completion.body->'response'->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR completion.body->'response'->>'run_state' IS DISTINCT FROM rr.state
    OR completion.body->'response'->'version' IS DISTINCT FROM to_jsonb(cleanup.version) OR completion.body->'response'->>'state' IS DISTINCT FROM 'cleaned'
    OR completion.body->'response'->'receipt' IS DISTINCT FROM cleaned.body OR completion.body->'response'->>'receipt_kind' IS DISTINCT FROM cleaned.receipt_kind
    OR completion.body->'response'->>'receipt_digest' IS DISTINCT FROM 'sha256:'||encode(cleaned.digest,'hex')
    OR completion.body->'response'->'targets' IS DISTINCT FROM zasp_sa_multistep_prior.cleanup_targets(o,w,e,r,predecessor) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered completion unavailable';END IF;
   completed_body:=jsonb_build_object('cleanup_id',cleanup.cleanup_id,'removed_source_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'targets'),'UTF8'),'sha256'),'hex'),
    'cleanup_deployment_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(cleaned.body->'targets'),'UTF8'),'sha256'),'hex'),'targets',cleaned.body->'targets',
    'started_at',to_char(cleanup.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',to_char(cleanup.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'attempts',cleanup.attempt,'outcome','cleaned');
   IF snapshot_value->>'kind'='partial' THEN
    IF rr.state NOT IN('cancelled','needs_human') OR EXISTS(SELECT 1 FROM public.zasp_security_agent_controls WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) OR fx.outcome_id IS NOT NULL OR fx.result_digest IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered partial completion unavailable';END IF;
    completed_body:=completed_body||jsonb_build_object('partial_application_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'application'),'UTF8'),'sha256'),'hex'),'cancellation_evidence_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'test'),'UTF8'),'sha256'),'hex'));
   ELSE
    SELECT * INTO control_row FROM public.zasp_security_agent_controls WHERE (organization_id,workspace_id,environment_id,run_id,step_id,control_id)=(o,w,e,r,predecessor,cleanup.control_id);
    IF control_row.state IS DISTINCT FROM 'disabled' OR control_row.version IS DISTINCT FROM (snapshot_value->'control'->>'version')::bigint+1
     OR control_row.lease_owner IS NOT NULL OR control_row.lease_token IS NOT NULL OR control_row.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered completed control unavailable';END IF;
    completed_body:=completed_body||jsonb_build_object('control_id',control_row.control_id,'control_version',control_row.version,'effect_id',fx.outcome_id,
     'application_receipt_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'application'),'UTF8'),'sha256'),'hex'),'test_evidence_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'test'),'UTF8'),'sha256'),'hex'));
   END IF;
   IF cleaned.body IS DISTINCT FROM completed_body THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered completed receipt unavailable';END IF;
  ELSIF EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'ordered_cleanup_complete')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered premature completion';END IF;
  live_value:=NOT terminal AND retained_live AND NOT zasp_sa_multistep_prior.orchestration_stop_required(o,w,e,r);
  FOR s IN SELECT * FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) ORDER BY step_index LOOP
   SELECT * INTO a FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   SELECT * INTO receipt FROM public.zasp_sa_multistep_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   SELECT * INTO fx FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   dependency_ready:=s.step_index=0 OR application;
   IF s.version NOT BETWEEN 1 AND 1000000 OR s.state NOT IN('queued','waiting_approval','authorized','executing','verifying','succeeded','failed','inconclusive','cancelled')
    OR s.step_index=0 AND s.state='queued' OR s.step_index=1 AND NOT application AND s.state NOT IN('queued','cancelled')
    OR s.state='queued' AND a.approval_id IS NOT NULL
    OR s.state='waiting_approval' AND (a.approval_id IS NULL OR a.state<>'pending')
    OR s.state IN('authorized','executing','verifying','succeeded') AND (a.approval_id IS NULL OR a.state<>'approved')
    OR s.state='succeeded' AND receipt.run_id IS NULL
    OR receipt.run_id IS NOT NULL AND (s.state<>'succeeded' OR receipt.action_key IS DISTINCT FROM s.action_key OR receipt.input_digest IS DISTINCT FROM s.input_digest OR receipt.plan_hash IS DISTINCT FROM rr.plan_hash OR receipt.result_digest IS DISTINCT FROM fx.result_digest OR NOT public.zasp_sa_multistep_body_valid(receipt.receipt_kind,receipt.body)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered step unavailable';END IF;
   receipt_value:=CASE WHEN receipt.run_id IS NULL THEN 'null'::jsonb ELSE jsonb_build_object('kind',receipt.receipt_kind,'version',receipt.receipt_version,'digest','sha256:'||encode(receipt.result_digest,'hex'),'reference',public.zasp_discovery_canonical_id(o,w,e,'public62_evidence',r||chr(31)||s.step_id||chr(31)||receipt.receipt_kind)) END;
   settlement:=CASE WHEN s.step_index=0 THEN 'not_applicable' WHEN receipt.run_id IS NULL THEN 'pending' ELSE receipt.body->>'outcome' END;
   cleanup_value:=CASE WHEN s.step_index=1 THEN jsonb_build_object('state','not_applicable','version',0,'attempt',0,'partial',false,'cleaned',false)
    ELSE jsonb_build_object('state',COALESCE(cleanup.state,CASE WHEN application THEN 'pending' ELSE 'not_started' END),'version',COALESCE(cleanup.version,0),'attempt',COALESCE(cleanup.attempt,0),'partial',COALESCE(cleanup.snapshot->>'kind'='partial' OR cleanup.reason='partial_acknowledgement',false),'cleaned',COALESCE(cleanup.state='cleaned',false)) END;
   steps:=steps||jsonb_build_array(jsonb_build_object('step_id',s.step_id,'index',s.step_index,'action',s.action_key,'state',CASE WHEN s.step_index=1 AND s.state='queued' THEN 'blocked' ELSE s.state END,'version',s.version,
    'dependency',jsonb_build_object('predecessor_step_id',CASE WHEN s.step_index=1 THEN predecessor END,'required_receipt_kind',CASE WHEN s.step_index=1 THEN 'temporary_policy_applied.v1' END,'satisfied',dependency_ready,'blocked',s.state='queued','ready',live_value AND dependency_ready AND s.state IN('authorized','waiting_approval')),
    'authorization',s.authorization_result,'approval',jsonb_build_object('state',COALESCE(a.state,'absent'),'version',COALESCE(a.version,0),'approval_id',a.approval_id),'receipt',receipt_value,'settlement',settlement,'cleanup',cleanup_value));
  END LOOP;
  IF jsonb_array_length(steps)<>2 OR rr.state IN('contained','remediated') AND steps->1->>'settlement'<>'not_reproduced' OR rr.state='remediated' AND cleanup.state IS DISTINCT FROM 'cleaned' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered verification unavailable';END IF;
 END IF;
 result_value:=jsonb_build_object('contract_version',62,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'definition_id',rr.definition_id,'definition_version',rr.definition_version,'state',rr.state,'version',rr.version,'admitted',admitted,'steps',steps,'verification',CASE WHEN terminal THEN rr.state ELSE 'pending' END);
 IF octet_length(result_value::text)>8192 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered projection bound exceeded';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_sa_multistep_prior.planning(checksum_value text, fingerprint_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;k text;op text;cv jsonb;now_value timestamptz;payload jsonb;selection jsonb;body_value text;bound_value jsonb;send_value boolean:=false;reason text;admission_request jsonb;
 rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;
 job zasp_sa_multistep_prior.planning_jobs%ROWTYPE;tr public.zasp_security_agent_trigger_receipts%ROWTYPE;
 reservation public.zasp_security_agent_provider_reservations%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='planning requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='planning principal rejected';END IF;
 IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planning release unavailable';END IF;
 IF octet_length(q::text)>524288 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','worker_id','lease_token','operation','payload']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning scope rejected';END IF;
 END LOOP;
 IF jsonb_typeof(q->'worker_id') IS DISTINCT FROM 'string' OR q->>'worker_id'!~'^[A-Za-z0-9_.-]{1,128}$'
  OR jsonb_typeof(q->'lease_token') IS DISTINCT FROM 'string' OR q->>'lease_token'!~'^[A-Za-z0-9_.-]{16,128}$'
  OR q->>'operation' NOT IN('claim','prepare','start','result','settle','artifacts','admit','reconcile') OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning operation rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';op:=q->>'operation';
 payload:=q->'payload';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning run absent';END IF;
 SELECT * INTO job FROM zasp_sa_multistep_prior.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN
  IF op<>'claim' OR payload<>'{}'::jsonb OR rr.state<>'queued' OR rr.attempt<>0 OR rr.version<>1 OR rr.available_at>clock_timestamp() OR rr.plan_hash IS NOT NULL OR b.run_id IS NOT NULL
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning run not fresh';END IF;
  SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) FOR SHARE;
  IF NOT FOUND OR r<>public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',rr.definition_id||chr(31)||rr.trigger_id||chr(31)||tr.trigger_version::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning trigger identity rejected';END IF;
  -- The first claim fixes attempt and all artifact identities. No lease takeover
  -- can authorize a second outbound call for the same canonical trigger.
  UPDATE public.zasp_security_agent_runs SET state='planning',attempt=1,version=2,lease_owner=q->>'worker_id',lease_token=q->>'lease_token',lease_expires_at=clock_timestamp()+interval '300 seconds' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO rr;
  cv:=zasp_sa_multistep_prior.context(o,w,e,r);
  IF octet_length(cv::text)>65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning input too large';END IF;
  IF (SELECT count(*) FROM public.zasp_security_agent_runs WHERE organization_id=o AND state IN('planning','running','verifying','waiting_approval'))>(cv->'definition'->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning concurrency exceeded';END IF;
  now_value:=clock_timestamp();
  INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
  INSERT INTO public.zasp_security_agent_run_budgets(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,started_at,deadline_at,max_steps,max_tokens,max_cost_nano_credits,concurrency_limit)
   VALUES(o,w,e,r,rr.definition_id,rr.definition_version,now_value,now_value+make_interval(secs=>(cv->'definition'->>'max_duration_seconds')::integer),2,(cv->'definition'->>'ai_token_budget')::bigint,(cv->'definition'->>'max_ai_cost_nano_credits')::bigint,(cv->'definition'->>'concurrency_limit')::integer) RETURNING * INTO b;
  INSERT INTO zasp_sa_multistep_prior.planning_jobs(organization_id,workspace_id,environment_id,run_id,worker_id,lease_token_digest,lease_expires_at,budget_started_at,budget_deadline_at,run_version,attempt,state,context_value,input_body,input_digest,input_artifact_id,output_artifact_id,reservation_id)
   VALUES(o,w,e,r,q->>'worker_id',digest(convert_to(q->>'lease_token','UTF8'),'sha256'),rr.lease_expires_at,b.started_at,b.deadline_at,rr.version,1,'claimed',cv,cv::text,'sha256:'||encode(digest(convert_to(cv::text,'UTF8'),'sha256'),'hex'),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_input',r),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_output',r),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_reservation',r)) RETURNING * INTO job;
 END IF;
 IF op='reconcile' THEN
  IF payload<>'{}'::jsonb OR job.lease_expires_at>clock_timestamp() OR job.state='admitted' OR rr.state NOT IN('planning','needs_human') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning recovery unavailable';END IF;
  SELECT * INTO reservation FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,job.attempt) FOR UPDATE;
  IF job.state='needs_human' THEN RETURN to_jsonb(job)-'lease_token_digest';END IF;
  reason:=CASE WHEN job.state IN('claimed','prepared') THEN 'planner_not_sent' WHEN job.state='started' THEN 'budget_usage_unknown' ELSE 'planner_completed_unadmitted' END;
  IF job.state IN('completed','settled','artifacts') THEN
   IF job.provider_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.raw_result,'UTF8'),'sha256'),'hex') OR job.result_value IS DISTINCT FROM zasp_sa_multistep_prior.planning_result(job.raw_result,job.lookup_request->>'model',job.context_value) OR reservation.reservation_id IS DISTINCT FROM job.reservation_id OR reservation.input_digest IS DISTINCT FROM decode(substring(job.input_digest FROM 8),'hex') OR reservation.model IS DISTINCT FROM job.lookup_request->>'model' OR reservation.cost_policy_version IS DISTINCT FROM job.pricing_bound->>'cost_policy_version' OR reservation.worker_id IS DISTINCT FROM job.worker_id OR reservation.lease_token_digest IS DISTINCT FROM job.lease_token_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning recovery evidence drift';END IF;
   cv:=job.result_value->'usage';
   IF cv='null'::jsonb THEN reason:='budget_usage_unknown';
   ELSE
    IF reservation.settled_at IS NULL THEN
     UPDATE public.zasp_security_agent_provider_reservations SET settled_at=clock_timestamp(),output_digest=decode(substring(job.provider_digest FROM 8),'hex'),prompt_tokens=(cv->>'prompt_tokens')::bigint,completion_tokens=(cv->>'completion_tokens')::bigint,total_tokens=(cv->>'total_tokens')::bigint,cost_nano_credits=(cv->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,job.attempt);
    ELSIF (reservation.output_digest,reservation.prompt_tokens,reservation.completion_tokens,reservation.total_tokens,reservation.cost_nano_credits) IS DISTINCT FROM (decode(substring(job.provider_digest FROM 8),'hex'),(cv->>'prompt_tokens')::bigint,(cv->>'completion_tokens')::bigint,(cv->>'total_tokens')::bigint,(cv->>'cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning recovery settlement drift';END IF;
    IF (cv->>'total_tokens')::bigint>least(reservation.maximum_tokens,b.max_tokens) THEN reason:='budget_tokens_exceeded';ELSIF (cv->>'cost_nano_credits')::bigint>least(reservation.maximum_cost_nano_credits,b.max_cost_nano_credits) THEN reason:='budget_cost_exceeded';END IF;
   END IF;
  END IF;
  IF reason LIKE 'budget_%' THEN UPDATE public.zasp_security_agent_run_budgets SET stop_reason=coalesce(stop_reason,reason) WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
  UPDATE public.zasp_security_agent_runs SET state='needs_human',last_error_code=reason,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1 WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  UPDATE zasp_sa_multistep_prior.planning_jobs SET state='needs_human' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning recovery readiness changed';END IF;
  RETURN to_jsonb(job)-'lease_token_digest';
 END IF;
 IF (job.worker_id,job.lease_token_digest) IS DISTINCT FROM (q->>'worker_id',digest(convert_to(q->>'lease_token','UTF8'),'sha256'))
  OR NOT ((rr.state,rr.attempt,rr.version,rr.lease_owner,rr.lease_token,rr.lease_expires_at) IS NOT DISTINCT FROM ('planning',job.attempt,job.run_version,job.worker_id,q->>'lease_token',job.lease_expires_at) OR op IN('claim','admit') AND job.state='admitted' AND rr.state='waiting_approval' AND rr.version=job.run_version+1)
  OR job.lease_expires_at<=clock_timestamp() OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp()
  OR (b.started_at,b.deadline_at) IS DISTINCT FROM (job.budget_started_at,job.budget_deadline_at) OR b.started_at>clock_timestamp() OR b.deadline_at IS DISTINCT FROM b.started_at+make_interval(secs=>(job.context_value->'definition'->>'max_duration_seconds')::integer)
  OR b.run_id IS NULL OR (b.definition_id,b.definition_version,b.max_steps,b.max_tokens,b.max_cost_nano_credits,b.concurrency_limit) IS DISTINCT FROM (rr.definition_id,rr.definition_version,2,(job.context_value->'definition'->>'ai_token_budget')::bigint,(job.context_value->'definition'->>'max_ai_cost_nano_credits')::bigint,(job.context_value->'definition'->>'concurrency_limit')::integer)
  OR job.input_body IS DISTINCT FROM job.context_value::text OR job.input_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.input_body,'UTF8'),'sha256'),'hex')
  OR zasp_sa_multistep_prior.context(o,w,e,r) IS DISTINCT FROM job.context_value
  OR NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning authority changed';END IF;
 SELECT * INTO reservation FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,job.attempt) FOR UPDATE;
 IF op IN('claim','start','settle','admit') AND payload<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning unexpected payload';END IF;
 IF op='prepare' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['pricing','input_version']) OR jsonb_typeof(payload->'input_version') IS DISTINCT FROM 'string' OR length(payload->>'input_version') NOT BETWEEN 1 AND 1024 OR payload->>'input_version'!~'^[!-~]+$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning input artifact rejected';END IF;
  selection:=payload->'pricing';body_value:=zasp_sa_multistep_prior.planning_body(job.context_value,selection);
  selection:=selection||jsonb_build_object('body',body_value,'body_digest','sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex'));
  IF (selection->>'organization_id',selection->>'workspace_id',selection->>'environment_id') IS DISTINCT FROM (o,w,e) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning pricing scope rejected';END IF;
  bound_value:=zasp_sa_multistep_prior.pricing_lookup(checksum_value,fingerprint_value,selection);
  IF job.state='claimed' THEN
   IF reservation.run_id IS NOT NULL OR (bound_value->>'maximum_tokens')::bigint>b.max_tokens OR (bound_value->>'maximum_cost_nano_credits')::bigint>b.max_cost_nano_credits THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning ceiling exceeds budget';END IF;
   INSERT INTO public.zasp_security_agent_provider_reservations(organization_id,workspace_id,environment_id,run_id,attempt,reservation_id,input_digest,model,cost_policy_version,cost_unit,maximum_tokens,maximum_cost_nano_credits,worker_id,lease_token_digest)
    VALUES(o,w,e,r,job.attempt,job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),selection->>'model',bound_value->>'cost_policy_version','openrouter_credit',(bound_value->>'maximum_tokens')::bigint,(bound_value->>'maximum_cost_nano_credits')::bigint,job.worker_id,job.lease_token_digest);
   UPDATE zasp_sa_multistep_prior.planning_jobs SET state='prepared',request_body=body_value,request_digest=selection->>'body_digest',lookup_request=selection,pricing_bound=bound_value,input_version=payload->>'input_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.lookup_request IS DISTINCT FROM selection OR job.input_version IS DISTINCT FROM payload->>'input_version' OR job.pricing_bound IS DISTINCT FROM bound_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning intent conflict';END IF;
 END IF;
 IF job.lookup_request IS NOT NULL THEN
  IF job.request_body IS DISTINCT FROM zasp_sa_multistep_prior.planning_body(job.context_value,job.lookup_request) OR job.request_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.request_body,'UTF8'),'sha256'),'hex') OR job.pricing_bound IS DISTINCT FROM zasp_sa_multistep_prior.pricing_lookup(checksum_value,fingerprint_value,job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning pricing or request drift';END IF;
  SELECT * INTO reservation FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,job.attempt) FOR UPDATE;
  IF (reservation.reservation_id,reservation.input_digest,reservation.model,reservation.cost_policy_version,reservation.cost_unit,reservation.maximum_tokens,reservation.maximum_cost_nano_credits,reservation.worker_id,reservation.lease_token_digest) IS DISTINCT FROM (job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),job.lookup_request->>'model',job.pricing_bound->>'cost_policy_version','openrouter_credit',(job.pricing_bound->>'maximum_tokens')::bigint,(job.pricing_bound->>'maximum_cost_nano_credits')::bigint,job.worker_id,job.lease_token_digest) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning reservation drift';END IF;
  IF reservation.settled_at IS NOT NULL AND (reservation.output_digest,reservation.prompt_tokens,reservation.completion_tokens,reservation.total_tokens,reservation.cost_nano_credits) IS DISTINCT FROM (decode(substring(job.provider_digest FROM 8),'hex'),(job.result_value->'usage'->>'prompt_tokens')::bigint,(job.result_value->'usage'->>'completion_tokens')::bigint,(job.result_value->'usage'->>'total_tokens')::bigint,(job.result_value->'usage'->>'cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning settlement differs from provider evidence';END IF;
 END IF;
 IF op='start' THEN
  IF job.state='prepared' THEN
   UPDATE zasp_sa_multistep_prior.planning_jobs SET state='started' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;send_value:=true;
  ELSIF job.state<>'started' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning send not available';END IF;
 ELSIF op='result' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['raw']) OR jsonb_typeof(payload->'raw') IS DISTINCT FROM 'string' OR octet_length(payload->>'raw') NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='planning result bytes rejected';END IF;
  IF job.state='started' THEN
   cv:=zasp_sa_multistep_prior.planning_result(payload->>'raw',job.lookup_request->>'model',job.context_value);
   body_value:=jsonb_build_object('raw',payload->>'raw','candidate',cv->'candidate')::text;
   UPDATE zasp_sa_multistep_prior.planning_jobs SET state='completed',raw_result=payload->>'raw',result_value=cv,provider_digest='sha256:'||encode(digest(convert_to(payload->>'raw','UTF8'),'sha256'),'hex'),output_body=body_value,output_digest='sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.raw_result IS DISTINCT FROM payload->>'raw' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning result is immutable';END IF;
 ELSIF op='settle' THEN
  IF job.state NOT IN('completed','settled','artifacts') OR reservation.reservation_id IS DISTINCT FROM job.reservation_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning result not ready for settlement';END IF;
  IF job.result_value IS DISTINCT FROM zasp_sa_multistep_prior.planning_result(job.raw_result,job.lookup_request->>'model',job.context_value) OR job.provider_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.raw_result,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning result drift';END IF;
  IF job.state='completed' THEN
   cv:=job.result_value->'usage';
   IF cv='null'::jsonb THEN reason:='budget_usage_unknown';
   ELSE
    UPDATE public.zasp_security_agent_provider_reservations SET settled_at=clock_timestamp(),output_digest=decode(substring(job.provider_digest FROM 8),'hex'),prompt_tokens=(cv->>'prompt_tokens')::bigint,completion_tokens=(cv->>'completion_tokens')::bigint,total_tokens=(cv->>'total_tokens')::bigint,cost_nano_credits=(cv->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,job.attempt);
    IF (cv->>'total_tokens')::bigint>least(reservation.maximum_tokens,b.max_tokens) THEN reason:='budget_tokens_exceeded';ELSIF (cv->>'cost_nano_credits')::bigint>least(reservation.maximum_cost_nano_credits,b.max_cost_nano_credits) THEN reason:='budget_cost_exceeded';END IF;
   END IF;
   UPDATE zasp_sa_multistep_prior.planning_jobs SET state='settled' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
   IF reason IS NOT NULL OR job.result_value->'candidate'='null'::jsonb THEN
    IF reason IS NOT NULL THEN UPDATE public.zasp_security_agent_run_budgets SET stop_reason=reason WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
    UPDATE public.zasp_security_agent_runs SET state='needs_human',last_error_code=coalesce(reason,'planner_rejected'),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1 WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
    UPDATE zasp_sa_multistep_prior.planning_jobs SET state='needs_human' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
   END IF;
  END IF;
 ELSIF op='artifacts' THEN
  IF job.state NOT IN('settled','artifacts') OR NOT zasp_sa_multistep_prior.closed(payload,ARRAY['input_version','output_version','output_digest']) OR payload->>'input_version' IS DISTINCT FROM job.input_version OR payload->>'output_digest' IS DISTINCT FROM job.output_digest OR jsonb_typeof(payload->'output_version') IS DISTINCT FROM 'string' OR length(payload->>'output_version') NOT BETWEEN 1 AND 1024 OR payload->>'output_version'!~'^[!-~]+$' OR job.output_version IS NOT NULL AND job.output_version IS DISTINCT FROM payload->>'output_version' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning immutable artifact conflict';END IF;
  UPDATE zasp_sa_multistep_prior.planning_jobs SET state='artifacts',output_version=payload->>'output_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 ELSIF op='admit' THEN
  IF job.state NOT IN('artifacts','admitted') OR job.output_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.output_body,'UTF8'),'sha256'),'hex') OR job.output_body IS DISTINCT FROM jsonb_build_object('raw',job.raw_result,'candidate',job.result_value->'candidate')::text THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning immutable result unavailable';END IF;
  admission_request:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'definition_id',rr.definition_id,'definition_version',rr.definition_version,'trigger_id',rr.trigger_id,'attempt',job.attempt,'run_version',job.run_version,'worker_id',job.worker_id,'lease_token',q->>'lease_token','input_digest',job.input_digest,'output_digest',job.provider_digest,'model',job.lookup_request->>'model','policy_version',job.lookup_request->>'request_policy_version','candidate',job.result_value->'candidate');
  cv:=zasp_sa_multistep_prior.admit(checksum_value,fingerprint_value,admission_request);
  UPDATE zasp_sa_multistep_prior.planning_jobs SET state='admitted',receipt=cv WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 END IF;
 -- Last writes can wait on FKs, uniqueness or audit. Refuse atomically if any
 -- current authority, lease, deadline or registered identity changed meanwhile.
 IF job.lease_expires_at<=clock_timestamp() OR b.deadline_at<=clock_timestamp() OR zasp_sa_multistep_prior.context(o,w,e,r) IS DISTINCT FROM job.context_value OR NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) OR job.lookup_request IS NOT NULL AND job.pricing_bound IS DISTINCT FROM zasp_sa_multistep_prior.pricing_lookup(checksum_value,fingerprint_value,job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='planning expired after wait';END IF;
 IF op='admit' THEN RETURN job.receipt;END IF;
 IF op='start' THEN RETURN (to_jsonb(job)-'lease_token_digest')||jsonb_build_object('send_permit',send_value);END IF;
 RETURN to_jsonb(job)-'lease_token_digest';
END $function$

CREATE OR REPLACE FUNCTION zasp_sa_multistep_prior.transition(checksum_value text, fingerprint_value text, request_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;actor text;role_value text;key text;fresh timestamptz;
 rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;step public.zasp_security_agent_steps%ROWTYPE;approval public.zasp_security_agent_approvals%ROWTYPE;
 membership public.zasp_identity_memberships%ROWTYPE;scope_row public.zasp_authorized_scopes%ROWTYPE;
 old_audit public.zasp_security_agent_audit%ROWTYPE;response_value jsonb;approval_value text;event_value text;audit_value text;next_state text;outcome text;
live_value boolean;blocked boolean;execution_stopped boolean;changed boolean:=false;replayed boolean:=false;application boolean:=false;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered transition requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_sa_multistep_prior.closed(request_value,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','operation','actor_id','run_version','approval_version','fresh_auth_at']) OR octet_length(request_value::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition input rejected';END IF;
 FOREACH key IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(request_value->>key),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition identity rejected';END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['run_version','approval_version'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'number' OR (request_value->>key)!~'^[1-9][0-9]{0,5}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition version rejected';END IF;
 END LOOP;
 o:=request_value->>'organization_id';w:=request_value->>'workspace_id';e:=request_value->>'environment_id';r:=request_value->>'run_id';s:=request_value->>'step_id';op:=request_value->>'operation';actor:=request_value->>'actor_id';
 IF NOT COALESCE(op IN('progress','stop','approve','reject','cancel'),false) OR jsonb_typeof(request_value->'actor_id') IS DISTINCT FROM 'string' OR length(btrim(actor)) NOT BETWEEN 1 AND 128 OR actor~'[[:cntrl:]]'
  OR jsonb_typeof(request_value->'fresh_auth_at') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition operation rejected';END IF;
 role_value:=CASE WHEN op IN('progress','stop') THEN 'zasp_security_agent_worker' ELSE 'zasp_security_agent_api' END;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready(role_value),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered transition principal rejected';END IF;
 IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered transition release unavailable';END IF;
 IF op NOT IN('progress','stop') THEN
  IF NOT public.zasp_valid_product_id(actor) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered actor rejected';END IF;
  fresh:=(request_value->>'fresh_auth_at')::timestamptz;
 END IF;
 PERFORM zasp_sa_multistep_prior.transition_lock(o,w,e,r);
 PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO step FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT FOUND OR op IN('progress','stop') AND step.step_index<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered step unavailable';END IF;
 approval_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s);
 event_value:=CASE WHEN op IN('progress','stop') THEN 'ordered_step_ready' WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END;
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s||chr(31)||event_value);
 -- A disabled execution switch revokes new work but must not prevent the
 -- durable conservative transition that makes retained cleanup possible.
 PERFORM 1 FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*','create_temporary_policy','run_test') ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE NOWAIT;
 SELECT count(*)<>4 OR NOT COALESCE(bool_and(execution_enabled),false) INTO execution_stopped FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*','create_temporary_policy','run_test');
 blocked:=rr.state NOT IN('waiting_approval','running','verifying') OR rr.completed_at IS NOT NULL
  OR op='stop' AND execution_stopped
  OR b.stop_reason IS NOT NULL OR b.deadline_at IS NULL OR b.deadline_at<=clock_timestamp()
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND expires_at<=clock_timestamp())
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index)=(o,w,e,r,0) AND state IN('failed','inconclusive','cancelled'))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state IN('known_failure','unknown_outcome','cleanup_failed','cleaned'));
 -- Only the closed worker stop operation consumes the reader's signal, and
 -- it must establish it again under these locks. Ordinary progress retains
 -- its reviewed current-authority refusal contract.
 IF op='stop' AND NOT blocked THEN blocked:=zasp_sa_multistep_prior.orchestration_stop_required(o,w,e,r);END IF;
 IF op='stop' AND NOT blocked THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered stop no longer required';END IF;
 -- A later stop is not a replay of the earlier successor-ready transition.
 -- Keep its immutable evidence under a distinct, deterministic identity.
 IF blocked AND op IN('progress','stop') THEN audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s||chr(31)||event_value||chr(31)||'blocked');END IF;
 SELECT * INTO old_audit FROM public.zasp_security_agent_audit WHERE organization_id=o AND audit_id=audit_value FOR SHARE;
 IF FOUND THEN
  IF NOT(blocked AND op IN('progress','stop')) AND old_audit.body->'request' IS DISTINCT FROM request_value
   OR blocked AND op IN('progress','stop') AND rr.version<>(request_value->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered transition replay changed';END IF;
  replayed:=true;
 ELSIF rr.version<>(request_value->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered run version changed';END IF;
 IF op='stop' AND (rr.state NOT IN('waiting_approval','running','verifying') OR rr.completed_at IS NOT NULL)
  AND (old_audit.body->'request'->>'operation' IS DISTINCT FROM 'stop' OR old_audit.body->'response'->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR rr.state<>'needs_human') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered stop terminal replay changed';END IF;
 IF op NOT IN('progress','stop') THEN
  SELECT * INTO membership FROM public.zasp_identity_memberships WHERE (organization_id,principal_id)=(o,actor) FOR SHARE;
  scope_row:=zasp_sa_multistep_prior.lock_scope(o,w,e,actor);
  IF membership.active IS DISTINCT FROM true OR NOT COALESCE(public.zasp_effective_scope_permissions(scope_row.permissions,membership.role) ?& ARRAY['view','manage_workflows','run_tests'],false)
   OR fresh IS NULL OR fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds'
   OR op IN('approve','reject') AND actor=rr.requested_by THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered decision authority rejected';END IF;
 END IF;
 IF op IN('approve','reject') AND blocked THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered decision parent stopped';END IF;
 live_value:=NOT blocked AND op<>'cancel';
 PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,live_value);
 IF op='progress' AND NOT blocked OR op IN('approve','reject') AND step.step_index=1 THEN application:=zasp_sa_multistep_prior.application_ready(o,w,e,r);END IF;
 IF op IN('approve','reject') THEN
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  IF approval.approval_id IS NULL OR approval.expires_at<=clock_timestamp() OR step.step_index=1 AND NOT application
   OR NOT replayed AND (step.state<>'waiting_approval' OR approval.state<>'pending' OR approval.version<>(request_value->>'approval_version')::bigint OR approval.approver_id IS NOT NULL OR approval.fresh_auth_at IS NOT NULL OR approval.decided_at IS NOT NULL)
   OR replayed AND (approval.state IS DISTINCT FROM CASE op WHEN 'approve' THEN 'approved' ELSE 'rejected' END OR approval.approver_id IS DISTINCT FROM actor OR approval.fresh_auth_at IS DISTINCT FROM fresh
    OR approval.version<>(request_value->>'approval_version')::bigint+1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered approval is not ready';END IF;
 END IF;
 IF replayed AND NOT blocked THEN
  IF op='progress' AND NOT application
   OR old_audit.body->'response'->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR old_audit.body->'response'->>'run_state' IS DISTINCT FROM rr.state
   OR old_audit.body->'response'->>'step_state' IS DISTINCT FROM step.state
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_approvals a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.step_id,a.approval_id)=(o,w,e,r,s,approval_value)
    AND to_jsonb(a.version)=old_audit.body->'response'->'approval_version'
    AND (op<>'progress' OR a.state='pending' AND a.approver_id IS NULL AND a.fresh_auth_at IS NULL AND a.decided_at IS NULL)) THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered replay state changed';END IF;
  response_value:=old_audit.body->'response';
 ELSIF op='cancel' OR op='reject' OR blocked THEN
  next_state:=CASE WHEN rr.state NOT IN('waiting_approval','running','verifying') OR rr.completed_at IS NOT NULL THEN rr.state WHEN op='cancel' THEN 'cancelled' ELSE 'needs_human' END;
  UPDATE public.zasp_security_agent_steps SET state='cancelled',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state IN('queued','authorized','waiting_approval');
  changed:=FOUND;
  UPDATE public.zasp_security_agent_approvals SET state=CASE WHEN op='reject' AND step_id=s THEN 'rejected' ELSE 'cancelled' END,
   approver_id=CASE WHEN op='reject' AND step_id=s THEN actor ELSE approver_id END,fresh_auth_at=CASE WHEN op='reject' AND step_id=s THEN fresh ELSE fresh_auth_at END,decided_at=clock_timestamp(),version=version+1
   WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'pending');
  changed:=changed OR FOUND OR rr.state<>next_state;
  outcome:='blocked';
 ELSIF op='approve' THEN
  UPDATE public.zasp_security_agent_approvals SET state='approved',approver_id=actor,fresh_auth_at=fresh,decided_at=clock_timestamp(),version=version+1 WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,approval_value);
  UPDATE public.zasp_security_agent_steps SET state='authorized',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  next_state:='running';outcome:='approved';changed:=true;
 ELSIF application THEN
  IF step.state<>'queued' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered successor changed';END IF;
  INSERT INTO public.zasp_security_agent_approvals(organization_id,workspace_id,environment_id,approval_id,run_id,step_id,plan_hash,state,requester_id,expires_at)
   SELECT o,w,e,approval_value,r,s,plan_hash,'pending',rr.requested_by,expires_at FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  UPDATE public.zasp_security_agent_steps SET state='waiting_approval',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  next_state:='waiting_approval';outcome:='ready';changed:=true;
 ELSE outcome:='waiting';next_state:=rr.state;
 END IF;
 IF response_value IS NULL THEN
  IF changed THEN UPDATE public.zasp_security_agent_runs SET state=next_state,version=version+1,updated_at=clock_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,
   completed_at=CASE WHEN next_state IN('cancelled','needs_human') THEN COALESCE(completed_at,clock_timestamp()) ELSE completed_at END WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
  SELECT jsonb_build_object('contract_version',61,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,'outcome',outcome,'run_state',x.state,'run_version',x.version,'step_state',y.state,'approval_id',COALESCE(a.approval_id,''),'approval_version',COALESCE(a.version,0)) INTO response_value
   FROM public.zasp_security_agent_runs x JOIN public.zasp_security_agent_steps y USING(organization_id,workspace_id,environment_id,run_id)
   LEFT JOIN public.zasp_security_agent_approvals a ON (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.step_id)=(o,w,e,r,s)
   WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,y.step_id)=(o,w,e,r,s);
  IF changed AND NOT replayed THEN INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body)
   VALUES(o,w,e,audit_value,audit_value,r,s,actor,event_value,digest(convert_to(request_value::text,'UTF8'),'sha256'),jsonb_build_object('contract_version',61,'request',request_value,'response',response_value));END IF;
 END IF;
 -- Audit/approval writes can wait. Recheck locked authority, clocks, session
 -- role and readiness after those waits; all provisional writes roll back.
 PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,live_value AND op<>'reject');
 IF application AND NOT blocked AND op<>'cancel' AND NOT zasp_sa_multistep_prior.application_ready(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application changed after wait';END IF;
 IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) OR NOT COALESCE(public.zasp_security_agent_principal_ready(role_value),false)
  OR op NOT IN('progress','stop') AND (fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds')
  OR op IN('approve','reject') AND approval.expires_at<=clock_timestamp()
  OR rr.lease_expires_at IS NOT NULL AND live_value AND rr.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered transition expired after wait';END IF;
 RETURN response_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal67.ready(c text, f text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n text;retired zasp_temporal66.retired_authorities%ROWTYPE;actual text;BEGIN
 IF c IS DISTINCT FROM 'b0ce6cf26b4b5f7e909f2e8e8ba5fdc987318efb21878c503117b4583b1544a8' OR f IS DISTINCT FROM '3559e54be45e44575699fb6fad8f23edffe3e98a5b8228f2b2b96ae42057ae92'
  OR (SELECT count(*) FROM zasp_temporal67.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_temporal67.registration WHERE checksum=c AND fingerprint=f)
  OR NOT zasp_temporal67.base_ready() OR zasp_temporal67.fingerprint() IS DISTINCT FROM f
  OR (SELECT count(*) FROM zasp_ordered_public62.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_ordered_public62.registration WHERE checksum='e4dfae0a990718c2c6b7518b07d7c146cfb9025656378d423c8d96188bcf1b96' AND fingerprint='07e774a28105095c73275ad959c765a3fddda9ee9aa81e81cd3828222e40aad3')
  OR (SELECT count(*) FROM zasp_temporal65.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_temporal65.registration x JOIN zasp_temporal67.registration y ON x.predecessor=y.outbox_predecessor WHERE x.checksum='2cb65040d3be0f7a08722691c5c1fe38b93b4d036cec6b74b4b2ec83c3a2d56a' AND x.fingerprint='8c64101128b0b31cd4d12575480035ab1e30f157d92fa96c236babc7620de3f8')
  OR (SELECT count(*) FROM zasp_temporal66.registration)<>1 OR NOT EXISTS(SELECT 1 FROM zasp_temporal66.registration WHERE checksum='6e2fbdef64421286476be12a02188d7936e81db3126764bf2ab55e099fcb12cb' AND fingerprint='422b211febdd6e2b37882dc3f5961a79ca5c58f3f87f1642f7babf1224fbe94a') THEN RETURN false;END IF;
 FOREACH n IN ARRAY ARRAY['zasp_ordered_worker63','zasp_ordered_scheduler64'] LOOP
  SELECT * INTO retired FROM zasp_temporal66.retired_authorities WHERE schema_name=n;
  IF (to_regnamespace(n) IS NOT NULL) IS DISTINCT FROM FOUND THEN RETURN false;END IF;
  IF NOT FOUND THEN CONTINUE;END IF;
  IF retired.original_fingerprint IS DISTINCT FROM (CASE n WHEN 'zasp_ordered_worker63' THEN 'c81c4cb4cb799894ab9bf69b16815341ac53665e967fd0405b32009898510239' ELSE '9a8a090c97a4c8b913921dd1503b6ca0925c837adf5da9219c3c8f1e3a6d0419' END) THEN RETURN false;END IF;
  EXECUTE format('SELECT %I.fingerprint()',n) INTO actual;
  IF actual IS DISTINCT FROM retired.retired_fingerprint OR EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace=to_regnamespace(n) AND has_function_privilege('zasp_security_agent_worker',oid,'EXECUTE')) THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal68.progress_transition(checksum_value text, fingerprint_value text, request_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;actor text;role_value text;key text;fresh timestamptz;
 rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;step public.zasp_security_agent_steps%ROWTYPE;approval public.zasp_security_agent_approvals%ROWTYPE;
 membership public.zasp_identity_memberships%ROWTYPE;scope_row public.zasp_authorized_scopes%ROWTYPE;
 old_audit public.zasp_security_agent_audit%ROWTYPE;response_value jsonb;approval_value text;event_value text;audit_value text;next_state text;outcome text;
live_value boolean;blocked boolean;execution_stopped boolean;changed boolean:=false;replayed boolean:=false;application boolean:=false;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered transition requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_sa_multistep_prior.closed(request_value,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','operation','actor_id','run_version','approval_version','fresh_auth_at']) OR octet_length(request_value::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition input rejected';END IF;
 FOREACH key IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(request_value->>key),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition identity rejected';END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['run_version','approval_version'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'number' OR (request_value->>key)!~'^[1-9][0-9]{0,5}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition version rejected';END IF;
 END LOOP;
 o:=request_value->>'organization_id';w:=request_value->>'workspace_id';e:=request_value->>'environment_id';r:=request_value->>'run_id';s:=request_value->>'step_id';op:=request_value->>'operation';actor:=request_value->>'actor_id';
 IF NOT COALESCE(op IN('progress','stop'),false) OR jsonb_typeof(request_value->'actor_id') IS DISTINCT FROM 'string' OR length(btrim(actor)) NOT BETWEEN 1 AND 128 OR actor~'[[:cntrl:]]'
  OR jsonb_typeof(request_value->'fresh_auth_at') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered transition operation rejected';END IF;
 role_value:=CASE WHEN op IN('progress','stop') THEN 'zasp_security_agent_worker' ELSE 'zasp_security_agent_api' END;
 IF NOT COALESCE((zasp_temporal68.principal_ready('zasp_temporal_executor') OR op='stop' AND zasp_temporal68.principal_ready('zasp_temporal_compensation')),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered transition principal rejected';END IF;
 IF NOT COALESCE(zasp_temporal68.current_ready(),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered transition release unavailable';END IF;
 IF op NOT IN('progress','stop') THEN
  IF NOT public.zasp_valid_product_id(actor) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered actor rejected';END IF;
  fresh:=(request_value->>'fresh_auth_at')::timestamptz;
 END IF;
 IF NOT zasp_temporal66.is_temporal(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor progress owner rejected';END IF;
 PERFORM zasp_sa_multistep_prior.transition_lock(o,w,e,r);
 PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO step FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT FOUND OR op IN('progress','stop') AND step.step_index<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered step unavailable';END IF;
 approval_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s);
 event_value:=CASE WHEN op IN('progress','stop') THEN 'ordered_step_ready' WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END;
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s||chr(31)||event_value);
 -- A disabled execution switch revokes new work but must not prevent the
 -- durable conservative transition that makes retained cleanup possible.
 PERFORM 1 FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*','create_temporary_policy','run_test') ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE NOWAIT;
 SELECT count(*)<>4 OR NOT COALESCE(bool_and(execution_enabled),false) INTO execution_stopped FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*','create_temporary_policy','run_test');
 blocked:=rr.state NOT IN('waiting_approval','running','verifying') OR rr.completed_at IS NOT NULL
  OR op='stop' AND execution_stopped
  OR b.stop_reason IS NOT NULL OR b.deadline_at IS NULL OR b.deadline_at<=clock_timestamp()
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND expires_at<=clock_timestamp())
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index)=(o,w,e,r,0) AND state IN('failed','inconclusive','cancelled'))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state IN('known_failure','unknown_outcome','cleanup_failed','cleaned'));
 -- Only the closed worker stop operation consumes the reader's signal, and
 -- it must establish it again under these locks. Ordinary progress retains
 -- its reviewed current-authority refusal contract.
 IF op='stop' AND NOT blocked THEN blocked:=zasp_sa_multistep_prior.orchestration_stop_required(o,w,e,r);END IF;
 IF op='stop' AND NOT blocked THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered stop no longer required';END IF;
 -- A later stop is not a replay of the earlier successor-ready transition.
 -- Keep its immutable evidence under a distinct, deterministic identity.
 IF blocked AND op IN('progress','stop') THEN audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s||chr(31)||event_value||chr(31)||'blocked');END IF;
 SELECT * INTO old_audit FROM public.zasp_security_agent_audit WHERE organization_id=o AND audit_id=audit_value FOR SHARE;
 IF FOUND THEN
  IF NOT(blocked AND op IN('progress','stop')) AND old_audit.body->'request' IS DISTINCT FROM request_value
   OR blocked AND op IN('progress','stop') AND rr.version<>(request_value->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered transition replay changed';END IF;
  replayed:=true;
 ELSIF rr.version<>(request_value->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered run version changed';END IF;
 IF op='stop' AND (rr.state NOT IN('waiting_approval','running','verifying') OR rr.completed_at IS NOT NULL)
  AND (old_audit.body->'request'->>'operation' IS DISTINCT FROM 'stop' OR old_audit.body->'response'->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR rr.state<>'needs_human') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered stop terminal replay changed';END IF;
 IF op NOT IN('progress','stop') THEN
  SELECT * INTO membership FROM public.zasp_identity_memberships WHERE (organization_id,principal_id)=(o,actor) FOR SHARE;
  scope_row:=zasp_sa_multistep_prior.lock_scope(o,w,e,actor);
  IF membership.active IS DISTINCT FROM true OR NOT COALESCE(public.zasp_effective_scope_permissions(scope_row.permissions,membership.role) ?& ARRAY['view','manage_workflows','run_tests'],false)
   OR fresh IS NULL OR fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds'
   OR op IN('approve','reject') AND actor=rr.requested_by THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered decision authority rejected';END IF;
 END IF;
 IF op IN('approve','reject') AND blocked THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered decision parent stopped';END IF;
 live_value:=NOT blocked AND op<>'cancel';
 PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,live_value);
 IF op='progress' AND NOT blocked OR op IN('approve','reject') AND step.step_index=1 THEN application:=zasp_sa_multistep_prior.application_ready(o,w,e,r);END IF;
 IF op IN('approve','reject') THEN
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  IF approval.approval_id IS NULL OR approval.expires_at<=clock_timestamp() OR step.step_index=1 AND NOT application
   OR NOT replayed AND (step.state<>'waiting_approval' OR approval.state<>'pending' OR approval.version<>(request_value->>'approval_version')::bigint OR approval.approver_id IS NOT NULL OR approval.fresh_auth_at IS NOT NULL OR approval.decided_at IS NOT NULL)
   OR replayed AND (approval.state IS DISTINCT FROM CASE op WHEN 'approve' THEN 'approved' ELSE 'rejected' END OR approval.approver_id IS DISTINCT FROM actor OR approval.fresh_auth_at IS DISTINCT FROM fresh
    OR approval.version<>(request_value->>'approval_version')::bigint+1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered approval is not ready';END IF;
 END IF;
 IF replayed AND NOT blocked THEN
  IF op='progress' AND NOT application
   OR old_audit.body->'response'->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR old_audit.body->'response'->>'run_state' IS DISTINCT FROM rr.state
   OR old_audit.body->'response'->>'step_state' IS DISTINCT FROM step.state
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_approvals a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.step_id,a.approval_id)=(o,w,e,r,s,approval_value)
    AND to_jsonb(a.version)=old_audit.body->'response'->'approval_version'
    AND (op<>'progress' OR a.state='pending' AND a.approver_id IS NULL AND a.fresh_auth_at IS NULL AND a.decided_at IS NULL)) THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered replay state changed';END IF;
  response_value:=old_audit.body->'response';
 ELSIF op='cancel' OR op='reject' OR blocked THEN
  next_state:=CASE WHEN rr.state NOT IN('waiting_approval','running','verifying') OR rr.completed_at IS NOT NULL THEN rr.state WHEN op='cancel' THEN 'cancelled' ELSE 'needs_human' END;
  UPDATE public.zasp_security_agent_steps SET state='cancelled',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state IN('queued','authorized','waiting_approval');
  changed:=FOUND;
  UPDATE public.zasp_security_agent_approvals SET state=CASE WHEN op='reject' AND step_id=s THEN 'rejected' ELSE 'cancelled' END,
   approver_id=CASE WHEN op='reject' AND step_id=s THEN actor ELSE approver_id END,fresh_auth_at=CASE WHEN op='reject' AND step_id=s THEN fresh ELSE fresh_auth_at END,decided_at=clock_timestamp(),version=version+1
   WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'pending');
  changed:=changed OR FOUND OR rr.state<>next_state;
  outcome:='blocked';
 ELSIF op='approve' THEN
  UPDATE public.zasp_security_agent_approvals SET state='approved',approver_id=actor,fresh_auth_at=fresh,decided_at=clock_timestamp(),version=version+1 WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,approval_value);
  UPDATE public.zasp_security_agent_steps SET state='authorized',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  next_state:='running';outcome:='approved';changed:=true;
 ELSIF application THEN
  IF step.state<>'queued' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered successor changed';END IF;
  INSERT INTO public.zasp_security_agent_approvals(organization_id,workspace_id,environment_id,approval_id,run_id,step_id,plan_hash,state,requester_id,expires_at)
   SELECT o,w,e,approval_value,r,s,plan_hash,'pending',rr.requested_by,expires_at FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  UPDATE public.zasp_security_agent_steps SET state='waiting_approval',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  next_state:='waiting_approval';outcome:='ready';changed:=true;
 ELSE outcome:='waiting';next_state:=rr.state;
 END IF;
 IF response_value IS NULL THEN
  IF changed THEN UPDATE public.zasp_security_agent_runs SET state=next_state,version=version+1,updated_at=clock_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,
   completed_at=CASE WHEN next_state IN('cancelled','needs_human') THEN COALESCE(completed_at,clock_timestamp()) ELSE completed_at END WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
  SELECT jsonb_build_object('contract_version',61,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,'outcome',outcome,'run_state',x.state,'run_version',x.version,'step_state',y.state,'approval_id',COALESCE(a.approval_id,''),'approval_version',COALESCE(a.version,0)) INTO response_value
   FROM public.zasp_security_agent_runs x JOIN public.zasp_security_agent_steps y USING(organization_id,workspace_id,environment_id,run_id)
   LEFT JOIN public.zasp_security_agent_approvals a ON (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.step_id)=(o,w,e,r,s)
   WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,y.step_id)=(o,w,e,r,s);
  IF changed AND NOT replayed THEN INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body)
   VALUES(o,w,e,audit_value,audit_value,r,s,actor,event_value,digest(convert_to(request_value::text,'UTF8'),'sha256'),jsonb_build_object('contract_version',61,'request',request_value,'response',response_value));END IF;
 END IF;
 -- Audit/approval writes can wait. Recheck locked authority, clocks, session
 -- role and readiness after those waits; all provisional writes roll back.
 PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,live_value AND op<>'reject');
 IF application AND NOT blocked AND op<>'cancel' AND NOT zasp_sa_multistep_prior.application_ready(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application changed after wait';END IF;
 IF NOT COALESCE(zasp_temporal68.current_ready(),false) OR NOT COALESCE((zasp_temporal68.principal_ready('zasp_temporal_executor') OR op='stop' AND zasp_temporal68.principal_ready('zasp_temporal_compensation')),false)
  OR op NOT IN('progress','stop') AND (fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds')
  OR op IN('approve','reject') AND approval.expires_at<=clock_timestamp()
  OR rr.lease_expires_at IS NOT NULL AND live_value AND rr.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered transition expired after wait';END IF;
 RETURN response_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal68.test_stop(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;intent jsonb;snapshot_value jsonb;result_value jsonb;audit_id text;uncertain boolean;child public.zasp_red_team_runs%ROWTYPE;t zasp_temporal68.test_stops%ROWTYPE;
BEGIN
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor stop principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR q->>'operation' IS DISTINCT FROM 'stop' OR q->'payload' IS DISTINCT FROM '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor stop request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';
 intent:=zasp_temporal68.effect(q||jsonb_build_object('operation','read'));
 IF intent->>'action_key' IS DISTINCT FROM 'run_test' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor stop action rejected';END IF;
 PERFORM zasp_sa_multistep_prior.test_lock(o,w,e,r);
 SELECT * INTO t FROM zasp_temporal68.test_stops WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF FOUND THEN PERFORM zasp_temporal68.test_stop_evidence(o,w,e,r,s);RETURN t.response;END IF;
 IF intent->>'state' NOT IN('reserved','started','unknown') OR intent->>'state'='reserved' AND NOT zasp_sa_multistep_prior.orchestration_stop_required(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor stop not required';END IF;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,intent->'snapshot'->'targets'->>'test_run_id') FOR UPDATE NOWAIT;
 IF child.run_id IS NULL OR child.state<>'queued' OR child.attempt<>0 OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL
  OR EXISTS(SELECT 1 FROM public.zasp_red_team_attempts WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child.run_id))
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id,test_run_id,reconcile_state,reconcile_version)=(o,w,e,r,s,child.run_id,'pending',1) AND reconcile_worker IS NULL AND reconcile_token IS NULL AND reconcile_expires_at IS NULL AND reconcile_settlement IS NULL)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor stopped child association changed';END IF;
 uncertain:=intent->>'state'<>'reserved';
 UPDATE public.zasp_red_team_runs SET state=CASE WHEN uncertain THEN 'failed' ELSE 'cancelled' END,error_code=CASE WHEN uncertain THEN 'outcome_unknown' ELSE 'cancelled' END,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child.run_id);
 UPDATE public.zasp_security_agent_steps SET state='inconclusive',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE zasp_temporal68.effects SET state='stopped',completed_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='cancelled' THEN state ELSE 'needs_human' END,version=version+1,completed_at=COALESCE(completed_at,clock_timestamp()),updated_at=clock_timestamp(),last_error_code='test_outcome_unknown' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 result_value:=jsonb_build_object('effect_key',intent->>'effect_key','generation',1,'test_run_id',child.run_id,'run_state',(SELECT state FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)),'reason',CASE WHEN uncertain THEN 'test_outcome_unknown' ELSE 'test_cancelled_before_dispatch' END);
 snapshot_value:=zasp_temporal68.test_stop_snapshot(o,w,e,r,s);
 INSERT INTO zasp_temporal68.test_stops VALUES(o,w,e,r,s,intent->>'effect_key',snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),result_value);
 audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_test_stop',intent->>'effect_key');
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id,audit_id,r,s,session_user,'temporal_test_stopped',digest(convert_to(jsonb_build_object('snapshot',snapshot_value,'response',result_value)::text,'UTF8'),'sha256'),jsonb_build_object('snapshot',snapshot_value,'response',result_value));
 PERFORM zasp_temporal68.test_stop_evidence(o,w,e,r,s);
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor stop catalog changed';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_schedule_triggers_v21(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;trigger_digest_value bytea;run_value text;audit_value text;correlation_value text;created_value integer:=0;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent trigger scheduling rejected';
  END IF;
  FOR candidate IN
    WITH eligible AS (
      SELECT definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version AS definition_version,
             (definition.body->>'concurrency_limit')::integer AS concurrency_limit,finding.id AS trigger_id,finding.version AS trigger_version,
             finding.updated_at,row_number() OVER(PARTITION BY definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id ORDER BY finding.updated_at,finding.id) AS definition_ordinal
      FROM zasp_security_agent_definitions definition
      JOIN zasp_risk_findings finding ON (finding.organization_id,finding.workspace_id,finding.environment_id)=(definition.organization_id,definition.workspace_id,definition.environment_id)
      WHERE definition.activation IN('supervised','autonomous') AND definition.deleted_at IS NULL AND definition.body->>'enabled'='true'
        AND definition.body->>'trigger_kind'='finding' AND definition.body->'environment_ids' ? definition.environment_id
        AND COALESCE(finding.rule,finding.source)=definition.body->>'trigger_source' AND finding.status='open'
        AND definition.body->'allowed_actions'=jsonb_build_array('update_finding_response') AND definition.body->>'verification_kind'='finding_state'
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=('*','*','*','*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'update_finding_response',true))
        AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,finding.id,finding.version))
        AND (SELECT count(*) FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.definition_id)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id) AND run.state IN('queued','planning','waiting_approval','running','verifying'))<(definition.body->>'concurrency_limit')::integer
    )
    SELECT organization_id,workspace_id,environment_id,definition_id,definition_version,concurrency_limit,trigger_id,trigger_version
    FROM eligible WHERE definition_ordinal=1
    ORDER BY updated_at,organization_id,workspace_id,environment_id,definition_id,trigger_id
    LIMIT limit_value
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,'automatic-trigger'),0));
    CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.trigger_id,candidate.trigger_version));
    CONTINUE WHEN (SELECT count(*) FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.definition_id)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id) AND run.state IN('queued','planning','waiting_approval','running','verifying'))>=candidate.concurrency_limit;
    trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','finding','id',candidate.trigger_id,'version',candidate.trigger_version)::text,'UTF8'),'sha256');
    run_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_run',candidate.definition_id||chr(31)||candidate.trigger_id||chr(31)||candidate.trigger_version::text);
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id)
    VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.trigger_id,'finding',candidate.trigger_version,trigger_digest_value,run_value)
    ON CONFLICT DO NOTHING;
    CONTINUE WHEN NOT FOUND;
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state)
    VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,run_value,candidate.definition_id,candidate.definition_version,candidate.trigger_id,worker_value,'queued');
    audit_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_audit',run_value||chr(31)||'automatic-trigger');
    correlation_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_correlation',run_value||chr(31)||'automatic-trigger');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
    VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,audit_value,correlation_value,run_value,worker_value,'run_queued',trigger_digest_value,jsonb_build_object('run_id',run_value,'definition_id',candidate.definition_id,'definition_version',candidate.definition_version,'trigger_kind','finding','trigger_id',candidate.trigger_id,'trigger_version',candidate.trigger_version,'automatic',true));
    created_value:=created_value+1;
  END LOOP;
  IF created_value>0 THEN UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;END IF;
  RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_schedule_triggers_v22(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE temporary_result jsonb;finding_result jsonb;temporary_limit integer;temporary_created integer;finding_created integer:=0;
BEGIN
  IF limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent scheduling rejected';END IF;
  temporary_limit:=greatest(1,(limit_value+1)/2);
  temporary_result:=zasp_security_agent_schedule_temporary_policy_triggers(worker_value,temporary_limit);
  temporary_created:=(temporary_result->>'created')::integer;
  IF temporary_created<limit_value THEN finding_result:=zasp_security_agent_schedule_triggers_v21(worker_value,limit_value-temporary_created);finding_created:=(finding_result->>'created')::integer;END IF;
  RETURN jsonb_build_object('created',temporary_created+finding_created);
END
$function$

